def unpack(fmt, data, offset):
    size = struct.calcsize(fmt)
    if offset < 0 or offset + size > len(data):
        raise FormatError(f"truncated: need {size} bytes at offset {offset:#x}, file has {len(data)}")
    return struct.unpack_from(fmt, data, offset)


def detect_format(data):
    if len(data) < 4:
        raise FormatError("file too short to hold a magic number")
    if data[:4] == b"\x7fELF":
        if len(data) < 6 or data[4] != 2:
            raise FormatError("only ELF64 (EI_CLASS 2) is supported")
        if data[5] != 1:
            raise FormatError("only little-endian ELF (EI_DATA 1) is supported")
        return "elf64"
    if data[:2] == b"MZ":
        (lfanew,) = unpack("<I", data, 0x3C)
        if unpack("<4s", data, lfanew)[0] != b"PE\0\0":
            raise FormatError(f"MZ header points at {lfanew:#x}, which has no PE signature")
        return "pe"
    magic = int.from_bytes(data[:4], "little")
    if magic == 0xFEEDFACF:
        return "macho64"
    if magic == 0xFEEDFACE:
        raise FormatError("32-bit Mach-O is not supported")
    if data[:4] == b"\xca\xfe\xba\xbe":
        raise FormatError("universal (fat) Mach-O: extract one slice with lipo first")
    if len(data) >= 20:
        machine, count, _, _, _, optional, _ = unpack("<HHIIIHH", data, 0)
        if machine in COFF_MACHINES and optional == 0 and 0 < count <= 96:
            return "coff"
    raise FormatError(f"unknown format: first bytes {data[:4].hex()}")


def _elf_header(data):
    fields = unpack("<16sHHIQQQIHHHHHH", data, 0)
    _, e_type, machine, _, entry, phoff, shoff, flags, _, phentsize, phnum, shentsize, shnum, shstrndx = fields
    if shnum and shentsize != 64:
        raise FormatError(f"section header entry size {shentsize}, expected 64")
    if phnum and phentsize != 56:
        raise FormatError(f"program header entry size {phentsize}, expected 56")
    if shoff + shnum * 64 > len(data):
        raise FormatError("section header table runs past the end of the file")
    if phoff + phnum * 56 > len(data):
        raise FormatError("program header table runs past the end of the file")
    if shnum and shstrndx >= shnum:
        raise FormatError(f"e_shstrndx {shstrndx} is not below e_shnum {shnum}")
    kind = ELF_KINDS.get(e_type, f"type {e_type}")
    return {
        "format": "elf64",
        "arch": ELF_MACHINES.get(machine, f"machine {machine:#x}"),
        "bits": 64,
        "endian": "little",
        "kind": kind,
        "entry": entry if kind in ("executable", "shared") and entry else None,
        "fields": {
            "e_type": e_type, "e_machine": machine, "e_flags": flags,
            "e_phoff": phoff, "e_phnum": phnum, "e_shoff": shoff, "e_shnum": shnum, "e_shstrndx": shstrndx,
        },
    }


def coff_file_header(data, offset):
    machine, count, stamp, symtab, nsyms, optional, characteristics = unpack("<HHIIIHH", data, offset)
    if symtab and symtab + nsyms * 18 > len(data):
        raise FormatError("COFF symbol table runs past the end of the file")
    return {
        "machine": machine, "number_of_sections": count, "time_date_stamp": stamp,
        "pointer_to_symbol_table": symtab, "number_of_symbols": nsyms,
        "size_of_optional_header": optional, "characteristics": characteristics,
        "section_table": offset + 20 + optional,
    }


def _coff_header(data):
    fields = coff_file_header(data, 0)
    return {
        "format": "coff",
        "arch": COFF_MACHINES[fields["machine"]],
        "bits": 64 if fields["machine"] != 0x14C else 32,
        "endian": "little",
        "kind": "relocatable",
        "entry": None,
        "fields": fields,
    }


def _pe_header(data):
    (lfanew,) = unpack("<I", data, 0x3C)
    fields = coff_file_header(data, lfanew + 4)
    optional = lfanew + 24
    (magic,) = unpack("<H", data, optional)
    if magic != 0x20B:
        raise FormatError(f"optional header magic {magic:#x}: only PE32+ (0x20b) is supported")
    if fields["size_of_optional_header"] < 112:
        raise FormatError("optional header too small for PE32+")
    entry_rva, = unpack("<I", data, optional + 16)
    image_base, section_alignment, file_alignment = unpack("<QII", data, optional + 24)
    size_of_image, size_of_headers = unpack("<II", data, optional + 56)
    subsystem, dll = unpack("<HH", data, optional + 68)
    (count,) = unpack("<I", data, optional + 108)
    count = min(count, 16, (fields["size_of_optional_header"] - 112) // 8)
    directories = {}
    for index in range(count):
        rva, size = unpack("<II", data, optional + 112 + 8 * index)
        if rva or size:
            directories[PE_DIRECTORIES[index]] = {"rva": rva, "size": size}
    fields.update({
        "magic": magic, "entry_rva": entry_rva, "image_base": image_base,
        "section_alignment": section_alignment, "file_alignment": file_alignment,
        "size_of_image": size_of_image, "size_of_headers": size_of_headers, "subsystem": subsystem,
        "dll_characteristics": dll,
        "dll_flags": [name for bit, name in DLL_CHARACTERISTICS.items() if dll & bit],
        "data_directories": directories,
    })
    return {
        "format": "pe",
        "arch": COFF_MACHINES.get(fields["machine"], f"machine {fields['machine']:#x}"),
        "bits": 64,
        "endian": "little",
        "kind": "shared" if fields["characteristics"] & 0x2000 else "executable",
        "entry": image_base + entry_rva if entry_rva else None,
        "fields": fields,
    }


def load_commands(data):
    _, _, _, _, ncmds, sizeofcmds, _, _ = unpack("<IiiIIIII", data, 0)
    if 32 + sizeofcmds > len(data):
        raise FormatError("load commands run past the end of the file")
    commands, offset = [], 32
    for _ in range(ncmds):
        cmd, size = unpack("<II", data, offset)
        if size < 8 or size % 8 or offset + size > 32 + sizeofcmds:
            raise FormatError(f"load command at {offset:#x} has invalid size {size}")
        commands.append({"cmd": cmd, "name": LOAD_COMMANDS.get(cmd, f"LC_{cmd:#x}"), "offset": offset, "size": size})
        offset += size
    return commands


def _macho_header(data):
    _, cputype, _, filetype, ncmds, sizeofcmds, flags, _ = unpack("<IiiIIIII", data, 0)
    commands = load_commands(data)
    entry = None
    text_base = None
    for command in commands:
        if command["name"] == "LC_SEGMENT_64":
            name, vmaddr = unpack("<16sQ", data, command["offset"] + 8)
            if name.rstrip(b"\0") == b"__TEXT":
                text_base = vmaddr
    for command in commands:
        if command["name"] == "LC_MAIN" and text_base is not None:
            (entryoff,) = unpack("<Q", data, command["offset"] + 8)
            entry = text_base + entryoff
    return {
        "format": "macho64",
        "arch": MACHO_CPUS.get(cputype & 0xFFFFFFFF, f"cpu {cputype:#x}"),
        "bits": 64,
        "endian": "little",
        "kind": MACHO_KINDS.get(filetype, f"filetype {filetype}"),
        "entry": entry,
        "fields": {
            "cputype": cputype, "filetype": filetype, "ncmds": ncmds, "sizeofcmds": sizeofcmds, "flags": flags,
            "flag_names": [name for bit, name in MACHO_FLAGS.items() if flags & bit],
            "load_commands": [command["name"] for command in commands],
        },
    }


def parse_header(data):
    kind = detect_format(data)
    if kind == "elf64":
        return _elf_header(data)
    if kind == "pe":
        return _pe_header(data)
    if kind == "coff":
        return _coff_header(data)
    return _macho_header(data)

import math
from collections import Counter

from .formats import FormatError, load_commands, parse_header, unpack

ELF_SECTION_TYPES = {
    0: "NULL", 1: "PROGBITS", 2: "SYMTAB", 3: "STRTAB", 4: "RELA", 5: "HASH", 6: "DYNAMIC", 7: "NOTE",
    8: "NOBITS", 9: "REL", 11: "DYNSYM", 14: "INIT_ARRAY", 15: "FINI_ARRAY", 17: "GROUP",
    0x6FFF4C03: "LLVM_ADDRSIG", 0x6FFFFFF6: "GNU_HASH", 0x6FFFFFFE: "VERNEED", 0x6FFFFFFF: "VERSYM",
}
ELF_SEGMENT_TYPES = {
    0: "NULL", 1: "LOAD", 2: "DYNAMIC", 3: "INTERP", 4: "NOTE", 6: "PHDR", 7: "TLS",
    0x6474E550: "GNU_EH_FRAME", 0x6474E551: "GNU_STACK", 0x6474E552: "GNU_RELRO", 0x6474E553: "GNU_PROPERTY",
}
MACHO_SECTION_TYPES = {
    0: "regular", 1: "zerofill", 2: "cstring_literals", 6: "non_lazy_symbol_pointers",
    7: "lazy_symbol_pointers", 8: "symbol_stubs", 9: "mod_init_func_pointers", 0xC: "gb_zerofill",
    0x11: "thread_local_regular", 0x12: "thread_local_zerofill", 0x13: "thread_local_variables",
}
MACHO_ZEROFILL = {1, 0xC, 0x12}
MACHO_SEGMENT_PERMS = {"__TEXT": "r-x", "__DATA": "rw-", "__DATA_CONST": "rw-", "__LINKEDIT": "r--"}


def shannon_entropy(data):
    if not data:
        return 0.0
    total = len(data)
    value = -sum(count / total * math.log2(count / total) for count in Counter(data).values())
    return round(value + 0.0, 4)


def perms(read, write, execute):
    return ("r" if read else "-") + ("w" if write else "-") + ("x" if execute else "-")


def _entry(index, name, segment, kind, addr, offset, size, file_size, permissions, code, data):
    if file_size and offset + file_size > len(data):
        raise FormatError(f"section {name} runs past the end of the file")
    return {
        "index": index, "name": name, "segment": segment, "type": kind, "addr": addr, "offset": offset,
        "size": size, "file_size": file_size, "perms": permissions, "code": bool(code),
        "entropy": shannon_entropy(data[offset:offset + file_size]),
    }


def _elf_sections(data, header):
    fields = header["fields"]
    raw = [unpack("<IIQQQQIIQQ", data, fields["e_shoff"] + 64 * i) for i in range(fields["e_shnum"])]
    if not raw:
        return []
    names = raw[fields["e_shstrndx"]]
    result = []
    for index, (name, kind, flags, addr, offset, size, *_rest) in enumerate(raw):
        if index == 0:
            continue
        file_size = 0 if kind == 8 else size
        result.append(_entry(
            index, _cstring(data, names[4] + name, names[4] + names[5]), None,
            ELF_SECTION_TYPES.get(kind, f"{kind:#x}"), addr, offset, size, file_size,
            perms(flags & 2, flags & 1, flags & 4) if flags & 2 else "---", flags & 4, data,
        ))
    return result


def _cstring(data, start, end):
    end = min(end, len(data))
    stop = data.find(b"\0", start, end)
    if start < 0 or start >= end or stop < 0:
        raise FormatError(f"string at {start:#x} is not terminated inside its table")
    return data[start:stop].decode("utf-8", "replace")


def coff_string_table(data, fields):
    start = fields["pointer_to_symbol_table"] + 18 * fields["number_of_symbols"]
    if not fields["pointer_to_symbol_table"]:
        return start, start
    (size,) = unpack("<I", data, start)
    return start, start + size


def coff_section_name(data, raw, fields):
    text = raw.rstrip(b"\0").decode("utf-8", "replace")
    if text.startswith("/") and text[1:].isdigit():
        start, end = coff_string_table(data, fields)
        return _cstring(data, start + int(text[1:]), end)
    return text


def _coff_sections(data, header):
    fields = header["fields"]
    image = header["format"] == "pe"
    base = fields.get("image_base", 0)
    result = []
    for index in range(fields["number_of_sections"]):
        raw = unpack("<8sIIIIIIHHI", data, fields["section_table"] + 40 * index)
        name, vsize, vaddr, raw_size, raw_ptr, _, _, _, _, flags = raw
        uninitialized = bool(flags & 0x80)
        if image:
            size = vsize or raw_size
            file_size = 0 if uninitialized else min(raw_size, size)
            addr = base + vaddr
        else:
            size = raw_size
            file_size = 0 if uninitialized or not raw_ptr else raw_size
            addr = 0
        kind = "code" if flags & 0x20 else "initialized" if flags & 0x40 else "uninitialized" if uninitialized else "other"
        result.append(_entry(
            index + 1, coff_section_name(data, name, fields), None, kind, addr, raw_ptr if file_size else 0,
            size, file_size, perms(flags & 0x40000000, flags & 0x80000000, flags & 0x20000000), flags & 0x20000020, data,
        ))
    return result


def macho_segments_raw(data):
    segments = []
    for command in load_commands(data):
        if command["name"] != "LC_SEGMENT_64":
            continue
        fields = unpack("<II16sQQQQiiII", data, command["offset"])
        _, _, name, vmaddr, vmsize, fileoff, filesize, maxprot, initprot, nsects, _ = fields
        if command["size"] < 72 + 80 * nsects:
            raise FormatError("LC_SEGMENT_64 is too small for its sections")
        sections = []
        for index in range(nsects):
            sect = unpack("<16s16sQQIIIIIIII", data, command["offset"] + 72 + 80 * index)
            sections.append({
                "sectname": sect[0].rstrip(b"\0").decode(), "segname": sect[1].rstrip(b"\0").decode(),
                "addr": sect[2], "size": sect[3], "offset": sect[4], "reloff": sect[6], "nreloc": sect[7],
                "flags": sect[8], "reserved1": sect[9], "reserved2": sect[10],
            })
        segments.append({
            "name": name.rstrip(b"\0").decode(), "vmaddr": vmaddr, "vmsize": vmsize, "fileoff": fileoff,
            "filesize": filesize, "maxprot": maxprot, "initprot": initprot, "sections": sections,
        })
    return segments


def _prot(value):
    return perms(value & 1, value & 2, value & 4)


def macho_sections_raw(data):
    return [section for segment in macho_segments_raw(data) for section in segment["sections"]]


def _macho_sections(data):
    named = {segment["name"]: segment for segment in macho_segments_raw(data) if segment["name"]}
    result = []
    for index, section in enumerate(macho_sections_raw(data), 1):
        kind = section["flags"] & 0xFF
        file_size = 0 if kind in MACHO_ZEROFILL else section["size"]
        segment = named.get(section["segname"])
        if segment:
            permissions = _prot(segment["initprot"])
        elif section["flags"] & 0x80000400:
            permissions = "r-x"
        else:
            permissions = MACHO_SEGMENT_PERMS.get(section["segname"], "r--")
        result.append(_entry(
            index, section["sectname"], section["segname"], MACHO_SECTION_TYPES.get(kind, f"{kind:#x}"),
            section["addr"], section["offset"] if file_size else 0, section["size"], file_size, permissions,
            section["flags"] & 0x80000400, data,
        ))
    return result


def sections(data):
    header = parse_header(data)
    if header["format"] == "elf64":
        return _elf_sections(data, header)
    if header["format"] in ("pe", "coff"):
        return _coff_sections(data, header)
    return _macho_sections(data)


def segments(data):
    header = parse_header(data)
    result = []
    if header["format"] == "elf64":
        fields = header["fields"]
        for index in range(fields["e_phnum"]):
            kind, flags, offset, vaddr, _, filesz, memsz, _ = unpack("<IIQQQQQQ", data, fields["e_phoff"] + 56 * index)
            if offset + filesz > len(data):
                raise FormatError(f"program header {index} runs past the end of the file")
            result.append({
                "name": ELF_SEGMENT_TYPES.get(kind, f"{kind:#x}"), "addr": vaddr, "size": memsz, "offset": offset,
                "file_size": filesz, "perms": perms(flags & 4, flags & 2, flags & 1), "max_perms": None,
                "entropy": shannon_entropy(data[offset:offset + filesz]),
            })
    elif header["format"] == "macho64":
        for segment in macho_segments_raw(data):
            if segment["fileoff"] + segment["filesize"] > len(data):
                raise FormatError(f"segment {segment['name']} runs past the end of the file")
            result.append({
                "name": segment["name"], "addr": segment["vmaddr"], "size": segment["vmsize"],
                "offset": segment["fileoff"], "file_size": segment["filesize"],
                "perms": _prot(segment["initprot"]), "max_perms": _prot(segment["maxprot"]),
                "entropy": shannon_entropy(data[segment["fileoff"]:segment["fileoff"] + segment["filesize"]]),
            })
    return result


def section_at_offset(section_list, offset):
    best = None
    for section in section_list:
        if section["file_size"] and section["offset"] <= offset < section["offset"] + section["file_size"]:
            if best is None or section["file_size"] < best["file_size"]:
                best = section
    return best


def section_at_address(section_list, address):
    for section in section_list:
        if section["size"] and section["addr"] <= address < section["addr"] + section["size"]:
            return section
    return None

from .formats import FormatError, load_commands, parse_header, unpack
from .layout import macho_segments_raw, macho_sections_raw, section_at_address, sections
from .symbols import coff_symbols, elf_symbol_table, read_cstring, symbols

X86_64_ELF = {
    0: "NONE", 1: "64", 2: "PC32", 3: "GOT32", 4: "PLT32", 6: "GLOB_DAT", 7: "JUMP_SLOT", 8: "RELATIVE",
    9: "GOTPCREL", 10: "32", 11: "32S", 24: "PC64", 41: "GOTPCRELX", 42: "REX_GOTPCRELX",
}
AARCH64_ELF = {
    257: "ABS64", 258: "ABS32", 261: "PREL32", 275: "ADR_PREL_PG_HI21", 277: "ADD_ABS_LO12_NC",
    278: "LDST8_ABS_LO12_NC", 282: "JUMP26", 283: "CALL26", 284: "LDST16_ABS_LO12_NC",
    285: "LDST32_ABS_LO12_NC", 286: "LDST64_ABS_LO12_NC", 311: "ADR_GOT_PAGE", 312: "LD64_GOT_LO12_NC",
    1025: "GLOB_DAT", 1026: "JUMP_SLOT", 1027: "RELATIVE",
}
AMD64_COFF = {
    0: "ABSOLUTE", 1: "ADDR64", 2: "ADDR32", 3: "ADDR32NB", 4: "REL32", 5: "REL32_1", 6: "REL32_2",
    7: "REL32_3", 8: "REL32_4", 9: "REL32_5", 10: "SECTION", 11: "SECREL",
}
ARM64_COFF = {1: "ADDR32", 2: "ADDR32NB", 3: "BRANCH26", 4: "PAGEBASE_REL21", 6: "PAGEOFFSET_12A", 7: "PAGEOFFSET_12L", 14: "ADDR64"}
ARM64_MACHO = {
    0: "UNSIGNED", 1: "SUBTRACTOR", 2: "BRANCH26", 3: "PAGE21", 4: "PAGEOFF12", 5: "GOT_LOAD_PAGE21",
    6: "GOT_LOAD_PAGEOFF12", 7: "POINTER_TO_GOT", 8: "TLVP_LOAD_PAGE21", 9: "TLVP_LOAD_PAGEOFF12", 10: "ADDEND",
}
X86_64_MACHO = {
    0: "UNSIGNED", 1: "SIGNED", 2: "BRANCH", 3: "GOT_LOAD", 4: "GOT", 5: "SUBTRACTOR", 6: "SIGNED_1",
    7: "SIGNED_2", 8: "SIGNED_4", 9: "TLV",
}
BASE_RELOCATIONS = {0: "ABSOLUTE", 3: "HIGHLOW", 10: "DIR64"}
POINTER_FORMATS = {2: "DYLD_CHAINED_PTR_64", 6: "DYLD_CHAINED_PTR_64_OFFSET"}


def uleb128(data, offset):
    value = shift = 0
    for count in range(10):
        if offset + count >= len(data):
            raise FormatError(f"uleb128 at {offset:#x} runs past the end of its data")
        byte = data[offset + count]
        value |= (byte & 0x7F) << shift
        shift += 7
        if not byte & 0x80:
            return value, offset + count + 1
    raise FormatError(f"uleb128 at {offset:#x} is longer than 10 bytes")


def _relocation(section, offset, kind, symbol, addend):
    return {"section": section, "offset": offset, "type": kind, "symbol": symbol, "addend": addend}


def _elf_relocations(data, header):
    section_list = sections(data)
    by_index = {section["index"]: section for section in section_list}
    names = AARCH64_ELF if header["arch"] == "arm64" else X86_64_ELF
    prefix = "R_AARCH64_" if header["arch"] == "arm64" else "R_X86_64_"
    tables, result = {}, []
    for section in section_list:
        if section["type"] not in ("RELA", "REL"):
            continue
        link, info = unpack("<II", data, header["fields"]["e_shoff"] + 64 * section["index"] + 40)
        if link not in tables:
            tables[link] = {symbol["index"]: symbol["name"] for symbol in elf_symbol_table(data, section_list, link)} if link else {}
        target = by_index.get(info, {"name": None})["name"]
        size = 24 if section["type"] == "RELA" else 16
        if section["size"] % size:
            raise FormatError(f"{section['name']} size is not a multiple of {size}")
        for index in range(section["size"] // size):
            if size == 24:
                offset, word, addend = unpack("<QQq", data, section["offset"] + 24 * index)
            else:
                (offset, word), addend = unpack("<QQ", data, section["offset"] + 16 * index), None
            symbol_index, kind = word >> 32, word & 0xFFFFFFFF
            if symbol_index and symbol_index not in tables[link]:
                raise FormatError(f"relocation {index} in {section['name']} names missing symbol {symbol_index}")
            result.append(_relocation(target, offset, prefix + names.get(kind, str(kind)),
                                      tables[link].get(symbol_index), addend))
    return result


def _coff_relocations(data, header):
    names = ARM64_COFF if header["arch"] == "arm64" else AMD64_COFF
    prefix = "IMAGE_REL_ARM64_" if header["arch"] == "arm64" else "IMAGE_REL_AMD64_"
    table = {symbol["index"]: symbol["name"] for symbol in coff_symbols(data)}
    result = []
    for index, section in enumerate(sections(data)):
        raw = unpack("<8sIIIIIIHHI", data, header["fields"]["section_table"] + 40 * index)
        pointer, count = raw[5], raw[7]
        for item in range(count):
            offset, symbol_index, kind = unpack("<IIH", data, pointer + 10 * item)
            if symbol_index not in table:
                raise FormatError(f"relocation {item} in {section['name']} names missing symbol {symbol_index}")
            result.append(_relocation(section["name"], offset, prefix + names.get(kind, str(kind)), table[symbol_index], None))
    return result


def rva_to_offset(section_list, image_base, rva):
    for section in section_list:
        start = section["addr"] - image_base
        if section["file_size"] and start <= rva < start + section["file_size"]:
            return section["offset"] + rva - start
    raise FormatError(f"RVA {rva:#x} is not backed by any section")


def _pe_relocations(data, header):
    fields = header["fields"]
    directory = fields["data_directories"].get("basereloc")
    if not directory:
        return []
    section_list = sections(data)
    base = fields["image_base"]
    offset = rva_to_offset(section_list, base, directory["rva"])
    end = offset + directory["size"]
    result = []
    while offset < end:
        page, size = unpack("<II", data, offset)
        if size < 8 or offset + size > end:
            raise FormatError(f"base relocation block at {offset:#x} has invalid size {size}")
        for item in range((size - 8) // 2):
            (entry,) = unpack("<H", data, offset + 8 + 2 * item)
            kind = entry >> 12
            if kind == 0:
                continue
            rva = page + (entry & 0xFFF)
            owner = section_at_address(section_list, base + rva)
            result.append(_relocation(owner["name"] if owner else None, rva,
                                      "IMAGE_REL_BASED_" + BASE_RELOCATIONS.get(kind, str(kind)), None, None))
        offset += size
    return result


def _macho_relocations(data, header):
    names = ARM64_MACHO if header["arch"] == "arm64" else X86_64_MACHO
    prefix = "ARM64_RELOC_" if header["arch"] == "arm64" else "X86_64_RELOC_"
    table = {symbol["index"]: symbol["name"] for symbol in symbols(data)}
    raw_sections = macho_sections_raw(data)
    result = []
    for section in raw_sections:
        pending = None
        for item in range(section["nreloc"]):
            address, word = unpack("<iI", data, section["reloff"] + 8 * item)
            if address < 0:
                raise FormatError("scattered relocations are not supported")
            number, external, kind = word & 0xFFFFFF, (word >> 27) & 1, word >> 28
            if header["arch"] == "arm64" and kind == 10:
                pending = number - (1 << 24) if number & 0x800000 else number
                continue
            if external:
                if number not in table:
                    raise FormatError(f"relocation {item} in {section['sectname']} names missing symbol {number}")
                symbol = table[number]
            else:
                if not 1 <= number <= len(raw_sections):
                    raise FormatError(f"relocation {item} in {section['sectname']} names missing section {number}")
                symbol = raw_sections[number - 1]["sectname"]
            result.append(_relocation(section["sectname"], address, prefix + names.get(kind, str(kind)), symbol, pending))
            pending = None
    return result


def relocations(data):
    header = parse_header(data)
    if header["format"] == "elf64":
        return _elf_relocations(data, header)
    if header["format"] == "coff":
        return _coff_relocations(data, header)
    if header["format"] == "pe":
        return _pe_relocations(data, header)
    return _macho_relocations(data, header)


def dylibs(data):
    result = []
    for command in load_commands(data):
        if command["name"] in ("LC_LOAD_DYLIB", "LC_LOAD_WEAK_DYLIB"):
            (name_offset,) = unpack("<I", data, command["offset"] + 8)
            result.append(read_cstring(data, command["offset"] + name_offset, command["offset"] + command["size"]))
    return result


def library_name(libraries, ordinal):
    if ordinal == 0:
        return "self"
    if ordinal in (0xFF, -1):
        return "main-executable"
    if ordinal in (0xFE, -2):
        return "flat-lookup"
    if 1 <= ordinal <= len(libraries):
        return libraries[ordinal - 1]
    raise FormatError(f"library ordinal {ordinal} has no LC_LOAD_DYLIB")


def linkedit_data(data, name):
    for command in load_commands(data):
        if command["name"] == name:
            dataoff, datasize = unpack("<II", data, command["offset"] + 8)
            if dataoff + datasize > len(data):
                raise FormatError(f"{name} points past the end of the file")
            return dataoff, datasize
    return None


def chained_fixups(data):
    header = parse_header(data)
    empty = {"header": None, "imports": [], "fixups": []}
    if header["format"] != "macho64":
        return empty
    found = linkedit_data(data, "LC_DYLD_CHAINED_FIXUPS")
    if not found:
        return empty
    base, size = found
    blob = data[base:base + size]
    version, starts, imports_offset, symbols_offset, count, imports_format, symbols_format = unpack("<7I", blob, 0)
    if version != 0:
        raise FormatError(f"chained fixups version {version} is not supported")
    if symbols_format != 0:
        raise FormatError("compressed chained fixup symbol names are not supported")
    libraries = dylibs(data)
    width = {1: 4, 2: 8, 3: 16}.get(imports_format)
    if width is None:
        raise FormatError(f"chained imports format {imports_format} is not supported")
    imports = []
    for index in range(count):
        if imports_format == 3:
            word, addend = unpack("<QQ", blob, imports_offset + 16 * index)
            ordinal, weak, name_offset = word & 0xFFFF, (word >> 16) & 1, word >> 32
            ordinal = ordinal - 0x10000 if ordinal >= 0xFFF0 else ordinal
        else:
            (word,) = unpack("<I", blob, imports_offset + width * index)
            addend = unpack("<i", blob, imports_offset + width * index + 4)[0] if imports_format == 2 else 0
            ordinal, weak, name_offset = word & 0xFF, (word >> 8) & 1, word >> 9
            ordinal = ordinal - 0x100 if ordinal >= 0xF0 else ordinal
        imports.append({
            "index": index, "name": read_cstring(blob, symbols_offset + name_offset),
            "library": library_name(libraries, ordinal), "weak": bool(weak), "addend": addend,
        })
    segments = macho_segments_raw(data)
    image_base = next((segment["vmaddr"] for segment in segments if segment["name"] == "__TEXT"), 0)
    section_list = sections(data)
    (seg_count,) = unpack("<I", blob, starts)
    if seg_count > len(segments):
        raise FormatError(f"chained starts list {seg_count} segments, file has {len(segments)}")
    fixups = []
    for segment_index in range(seg_count):
        (start_offset,) = unpack("<I", blob, starts + 4 + 4 * segment_index)
        if not start_offset:
            continue
        where = starts + start_offset
        _, page_size, pointer_format, _, _, page_count = unpack("<IHHQIH", blob, where)
        if pointer_format not in POINTER_FORMATS:
            raise FormatError(f"chained pointer format {pointer_format} is not supported")
        segment = segments[segment_index]
        for page in range(page_count):
            (first,) = unpack("<H", blob, where + 22 + 2 * page)
            if first == 0xFFFF:
                continue
            if first & 0x8000:
                raise FormatError("multi-start chained pages are not supported")
            page_start = segment["fileoff"] + page * page_size
            offset = page_start + first
            for _ in range(page_size // 4 + 1):
                if offset + 8 > page_start + page_size:
                    raise FormatError(f"fixup chain leaves its page at {offset:#x}")
                (raw,) = unpack("<Q", data, offset)
                step = (raw >> 51) & 0xFFF
                address = segment["vmaddr"] + offset - segment["fileoff"]
                owner = section_at_address(section_list, address)
                fixup = {"offset": offset, "address": address, "section": owner["name"] if owner else None,
                         "raw": raw, "next": step}
                if raw >> 63:
                    ordinal = raw & 0xFFFFFF
                    if ordinal >= len(imports):
                        raise FormatError(f"bind at {offset:#x} uses import {ordinal}, table has {len(imports)}")
                    fixup.update(kind="bind", ordinal=ordinal, name=imports[ordinal]["name"],
                                 library=imports[ordinal]["library"], addend=(raw >> 24) & 0xFF)
                else:
                    target = raw & 0xFFFFFFFFF
                    high8 = (raw >> 36) & 0xFF
                    if pointer_format == 6:
                        target += image_base
                    fixup.update(kind="rebase", target=target | (high8 << 56))
                fixups.append(fixup)
                if not step:
                    break
                offset += step * 4
            else:
                raise FormatError("fixup chain does not terminate inside its page")
    return {
        "header": {"version": version, "imports_count": count, "imports_format": imports_format,
                   "pointer_formats": sorted({POINTER_FORMATS[f] for f in _formats(blob, starts, seg_count)})},
        "imports": imports,
        "fixups": fixups,
    }


def _formats(blob, starts, seg_count):
    result = []
    for index in range(seg_count):
        (start_offset,) = unpack("<I", blob, starts + 4 + 4 * index)
        if start_offset:
            result.append(unpack("<H", blob, starts + start_offset + 6)[0])
    return result


def _pe_imports(data, header):
    fields = header["fields"]
    directory = fields["data_directories"].get("import")
    if not directory:
        return []
    section_list = sections(data)
    base = fields["image_base"]
    offset = rva_to_offset(section_list, base, directory["rva"])
    result = []
    for _ in range(4096):
        ilt, _, _, name_rva, iat = unpack("<IIIII", data, offset)
        if not (ilt or name_rva or iat):
            return result
        library = read_cstring(data, rva_to_offset(section_list, base, name_rva))
        thunk = rva_to_offset(section_list, base, ilt or iat)
        for slot in range(65536):
            (entry,) = unpack("<Q", data, thunk + 8 * slot)
            if not entry:
                break
            item = {"name": None, "library": library, "slots": [base + iat + 8 * slot], "hint": None, "ordinal": None}
            if entry >> 63:
                item["ordinal"] = entry & 0xFFFF
                item["name"] = f"#{entry & 0xFFFF}"
            else:
                where = rva_to_offset(section_list, base, entry & 0x7FFFFFFF)
                (item["hint"],) = unpack("<H", data, where)
                item["name"] = read_cstring(data, where + 2)
            result.append(item)
        offset += 20
    raise FormatError("import directory has no terminating descriptor")


def imports(data):
    header = parse_header(data)
    if header["format"] == "pe":
        return _pe_imports(data, header)
    fixups = chained_fixups(data)
    if fixups["header"]:
        slots = {}
        for fixup in fixups["fixups"]:
            if fixup["kind"] == "bind":
                slots.setdefault(fixup["ordinal"], []).append(fixup["address"])
        return [{"name": item["name"], "library": item["library"], "slots": slots.get(item["index"], []),
                 "hint": None, "ordinal": item["index"]} for item in fixups["imports"]]
    libraries = dylibs(data) if header["format"] == "macho64" else []
    result, seen = [], set()
    for symbol in symbols(data):
        if symbol["defined"] or symbol["binding"] == "local" or symbol["kind"] in ("section", "file"):
            continue
        if symbol["name"] in seen or not symbol["name"]:
            continue
        seen.add(symbol["name"])
        library = None
        if libraries and symbol.get("library_ordinal") is not None:
            library = library_name(libraries, symbol["library_ordinal"])
        result.append({"name": symbol["name"], "library": library, "slots": [], "hint": None, "ordinal": None})
    return result


def exports_trie(blob, image_base):
    result, stack, visited = [], [(0, "")], set()
    while stack:
        node, prefix = stack.pop()
        if node in visited:
            raise FormatError(f"exports trie revisits node {node:#x}")
        visited.add(node)
        size, cursor = uleb128(blob, node)
        children_at = cursor + size
        if size:
            flags, cursor = uleb128(blob, cursor)
            if flags & 0x08:
                ordinal, cursor = uleb128(blob, cursor)
                result.append({"name": prefix, "address": None, "flags": flags, "reexport": ordinal})
            else:
                offset, cursor = uleb128(blob, cursor)
                result.append({"name": prefix, "address": image_base + offset, "flags": flags, "reexport": None})
        if children_at >= len(blob):
            raise FormatError(f"exports trie node {node:#x} runs past the end of the trie")
        count, cursor = blob[children_at], children_at + 1
        children = []
        for _ in range(count):
            stop = blob.find(b"\0", cursor)
            if stop < 0:
                raise FormatError("exports trie edge has no terminating NUL")
            edge = blob[cursor:stop].decode("utf-8", "replace")
            child, cursor = uleb128(blob, stop + 1)
            if not 0 < child < len(blob):
                raise FormatError(f"exports trie child offset {child:#x} is outside the trie")
            children.append((child, prefix + edge))
        stack.extend(reversed(children))
    return sorted(result, key=lambda item: item["name"])


def _pe_exports(data, header):
    fields = header["fields"]
    directory = fields["data_directories"].get("export")
    if not directory:
        return []
    section_list = sections(data)
    base = fields["image_base"]
    offset = rva_to_offset(section_list, base, directory["rva"])
    values = unpack("<IIHHIIIIIII", data, offset)
    ordinal_base, functions, names, eat, enpt, eot = values[5], values[6], values[7], values[8], values[9], values[10]
    if names > functions:
        raise FormatError("export directory has more names than addresses")
    result = []
    for index in range(names):
        (name_rva,) = unpack("<I", data, rva_to_offset(section_list, base, enpt + 4 * index))
        (slot,) = unpack("<H", data, rva_to_offset(section_list, base, eot + 2 * index))
        if slot >= functions:
            raise FormatError(f"export ordinal index {slot} is outside the address table")
        (target,) = unpack("<I", data, rva_to_offset(section_list, base, eat + 4 * slot))
        name = read_cstring(data, rva_to_offset(section_list, base, name_rva))
        forwarder = None
        if directory["rva"] <= target < directory["rva"] + directory["size"]:
            forwarder = read_cstring(data, rva_to_offset(section_list, base, target))
        result.append({"name": name, "address": None if forwarder else base + target,
                       "ordinal": ordinal_base + slot, "forwarder": forwarder})
    return result


def exports(data):
    header = parse_header(data)
    if header["format"] == "pe":
        return _pe_exports(data, header)
    if header["format"] == "macho64":
        trie = linkedit_data(data, "LC_DYLD_EXPORTS_TRIE")
        if trie and trie[1]:
            base = next((s["vmaddr"] for s in macho_segments_raw(data) if s["name"] == "__TEXT"), 0)
            return [{"name": item["name"], "address": item["address"], "ordinal": None,
                     "forwarder": None if item["reexport"] is None else f"dylib {item['reexport']}"}
                    for item in exports_trie(data[trie[0]:trie[0] + trie[1]], base)]
    pool = symbols(data)
    if any(symbol["table"] == "dynsym" for symbol in pool):
        pool = [symbol for symbol in pool if symbol["table"] == "dynsym"]
    result = []
    for symbol in pool:
        if symbol["defined"] and symbol["binding"] in ("global", "weak") and symbol["kind"] not in ("section", "file"):
            if symbol["section"] in ("*ABS*", "*DEBUG*"):
                continue
            result.append({"name": symbol["name"], "address": symbol["value"], "ordinal": None, "forwarder": None})
    return result

import hashlib
import html
import zlib

from .discovery import extract_strings, function_starts, score_starts
from .formats import parse_header
from .layout import sections, segments, shannon_entropy
from .linkage import chained_fixups, exports, imports, relocations
from .symbols import symbols

REPORT_SCHEMA = "binary-inspector/report/v1"
DIFF_SCHEMA = "binary-inspector/diff/v1"
REPORT_FIELDS = {
    "schema": str, "file": dict, "header": dict, "sections": list, "segments": list, "symbols": list,
    "imports": list, "exports": list, "relocations": list, "fixups": list, "strings": list,
    "function_starts": dict, "byte_map": list, "summary": dict,
}
ITEM_FIELDS = {
    "sections": ("name", "offset", "size", "file_size", "perms", "entropy"),
    "segments": ("name", "offset", "size", "file_size", "perms", "entropy"),
    "symbols": ("name", "value", "kind", "binding", "section", "defined"),
    "imports": ("name", "library", "slots"),
    "exports": ("name", "address"),
    "relocations": ("section", "offset", "type", "symbol"),
    "fixups": ("offset", "address", "kind", "raw"),
    "strings": ("offset", "text", "encoding", "section"),
    "byte_map": ("offset", "length", "region", "entropy"),
}


def _covering(items, start, end):
    best, best_overlap = None, 0
    for item in items:
        if not item["file_size"]:
            continue
        overlap = min(end, item["offset"] + item["file_size"]) - max(start, item["offset"])
        if overlap > best_overlap or (overlap == best_overlap and overlap > 0 and item["file_size"] < best["file_size"]):
            best, best_overlap = item, overlap
    return best


def byte_map(data, section_list, segment_list=(), cells=128):
    if cells < 1:
        raise ValueError("cells must be at least 1")
    cells = min(cells, len(data)) or 1
    first = min((s["offset"] for s in section_list if s["file_size"]), default=len(data))
    result = []
    for index in range(cells):
        start = index * len(data) // cells
        end = (index + 1) * len(data) // cells
        section = _covering(section_list, start, end)
        if section:
            region = section["name"]
        elif end <= first:
            region = "headers"
        else:
            segment = _covering(segment_list, start, end)
            region = segment["name"] if segment else "unmapped"
        result.append({"index": index, "offset": start, "length": end - start, "region": region,
                       "entropy": shannon_entropy(data[start:end])})
    return result


def build_report(data, name="input", truth=None, min_string=4, cells=128):
    header = parse_header(data)
    section_list = sections(data)
    segment_list = segments(data)
    symbol_list = symbols(data)
    starts = function_starts(data)
    if truth is not None:
        expected = function_starts(truth)["symbols"]
        starts["truth"] = expected
        starts["scores"] = {method: score_starts(found, expected)
                            for method, found in starts.items() if method not in ("truth", "scores")}
    fixups = chained_fixups(data)
    report = {
        "schema": REPORT_SCHEMA,
        "file": {"name": name, "size": len(data), "sha256": hashlib.sha256(data).hexdigest()},
        "header": header,
        "sections": section_list,
        "segments": segment_list,
        "symbols": symbol_list,
        "imports": imports(data),
        "exports": exports(data),
        "relocations": relocations(data),
        "fixups": fixups["fixups"],
        "strings": extract_strings(data, section_list, segment_list, min_string),
        "function_starts": starts,
        "byte_map": byte_map(data, section_list, segment_list, cells),
    }
    report["summary"] = {
        "format": header["format"], "arch": header["arch"], "kind": header["kind"],
        "sections": len(section_list), "segments": len(segment_list), "symbols": len(symbol_list),
        "defined_functions": len(starts["symbols"]), "imports": len(report["imports"]),
        "exports": len(report["exports"]), "relocations": len(report["relocations"]),
        "fixups": len(report["fixups"]), "strings": len(report["strings"]),
        "recovered_starts": len(starts["recovered"]), "file_entropy": shannon_entropy(data),
    }
    return report


def validate_report(report):
    errors = []
    if not isinstance(report, dict):
        return ["report must be an object"]
    for key, kind in REPORT_FIELDS.items():
        if key not in report:
            errors.append(f"missing key {key}")
        elif not isinstance(report[key], kind):
            errors.append(f"{key} must be {kind.__name__}")
    if report.get("schema") not in (None, REPORT_SCHEMA) and isinstance(report.get("schema"), str):
        errors.append(f"schema must be {REPORT_SCHEMA}")
    for key, fields in ITEM_FIELDS.items():
        for position, item in enumerate(report.get(key) or []):
            if not isinstance(item, dict):
                errors.append(f"{key}[{position}] must be an object")
                continue
            for field in fields:
                if field not in item:
                    errors.append(f"{key}[{position}] missing {field}")
    for field in ("name", "size", "sha256"):
        if isinstance(report.get("file"), dict) and field not in report["file"]:
            errors.append(f"file missing {field}")
    for field in ("format", "arch", "kind"):
        if isinstance(report.get("header"), dict) and field not in report["header"]:
            errors.append(f"header missing {field}")
    return errors


def region_color(region):
    if region == "headers":
        return "hsl(220 10% 55%)"
    if region == "unmapped":
        return "hsl(0 0% 40%)"
    hue = zlib.crc32(region.encode()) % 360
    return f"hsl({hue} 65% 50%)"


def _hex(value):
    return "" if value is None else f"0x{value:x}"


def _table(columns, rows):
    head = "".join(f"<th>{html.escape(c)}</th>" for c in columns)
    body = "".join("<tr>" + "".join(f"<td>{html.escape(str(cell))}</td>" for cell in row) + "</tr>" for row in rows)
    if not rows:
        body = f'<tr><td colspan="{len(columns)}">none</td></tr>'
    return f"<table><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table>"


