import csv, io, unicodedata, re, json, hashlib


def import_catalog(text, source):
    """Parse CSV requiring nonempty unique id and title, optional creator and extra fields. Return records with source and source_id keys; preserve original fields. Reject ragged rows, duplicate headers and blank source names."""
    try:
        parsed = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as error:
        raise ValueError("malformed CSV: " + str(error)) from error
    if (
        not source
        or not parsed
        or (not {"id", "title"} <= set(parsed[0]))
        or (len(set(parsed[0])) != len(parsed[0]))
    ):
        raise ValueError("source, id and title required")
    if {"source", "source_id"} & set(parsed[0]):
        raise ValueError("reserved column")
    seen = set()
    out = []
    for row in parsed[1:]:
        if len(row) != len(parsed[0]):
            raise ValueError("ragged row")
        r = dict(zip(parsed[0], row))
        if not r["id"].strip() or not r["title"].strip() or r["id"] in seen:
            raise ValueError("invalid or duplicate record id")
        seen.add(r["id"])
        out.append({**r, "source": source, "source_id": source + ":" + r["id"]})
    return out


def _tokens(text):
    return set(re.findall("\\w+", unicodedata.normalize("NFKC", text).casefold()))


def _score(a, b):
    x, y = (_tokens(a), _tokens(b))
    return len(x & y) / len(x | y) if x | y else 0.0


def candidates(left, right, threshold=0.25):
    """Return descending candidate pairs {left,right,score,title_score,creator_score}; title Jaccard contributes 0.8, creator Jaccard 0.2. Include scores >= threshold; use source IDs to break ties. Threshold must be finite in [0,1]."""
    if not isinstance(threshold, (int, float)) or not 0 <= threshold <= 1:
        raise ValueError("invalid threshold")
    out = []
    for a in left:
        for b in right:
            title = _score(a["title"], b["title"])
            creator = _score(a.get("creator", ""), b.get("creator", ""))
            score = 0.8 * title + 0.2 * creator
            if score >= threshold:
                out.append(
                    {
                        "left": a["source_id"],
                        "right": b["source_id"],
                        "score": round(score, 6),
                        "title_score": round(title, 6),
                        "creator_score": round(creator, 6),
                    }
                )
    return sorted(out, key=lambda p: (-p["score"], p["left"], p["right"]))


def reconcile(left, right, decisions):
    """Return merged entities with sources (complete original records), fields and unresolved conflicts. Decisions are [{left,right,match:bool,values:{field:chosen string}}]. Require one-to-one accepted links, known IDs and unique pair decisions. Unmatched records remain separate."""
    a = {r["source_id"]: r for r in left}
    b = {r["source_id"]: r for r in right}
    if set(a) & set(b):
        raise ValueError("catalog source IDs overlap")
    used_a = set()
    used_b = set()
    seen = set()
    result = []
    for d in decisions:
        x, y = (d["left"], d["right"])
        pair = (x, y)
        if (
            x not in a
            or y not in b
            or pair in seen
            or (type(d.get("match")) is not bool)
        ):
            raise ValueError("invalid decision")
        seen.add(pair)
        if not d["match"]:
            continue
        if x in used_a or y in used_b:
            raise ValueError("one-to-one match violated")
        used_a.add(x)
        used_b.add(y)
        fields = {}
        conflicts = []
        values = d.get("values", {})
        keys = (set(a[x]) | set(b[y])) - {"id", "source", "source_id"}
        if not set(values) <= keys or any(
            (not isinstance(v, str) for v in values.values())
        ):
            raise ValueError("invalid field resolution")
        for k in sorted(keys):
            av, bv = (a[x].get(k, ""), b[y].get(k, ""))
            fields[k] = values.get(k, av or bv)
            if av and bv and (av != bv) and (k not in values):
                conflicts.append({"field": k, "left": av, "right": bv})
        result.append(
            {
                "id": x + "|" + y,
                "sources": [a[x], b[y]],
                "fields": fields,
                "conflicts": conflicts,
            }
        )
    for records, used in [(left, used_a), (right, used_b)]:
        for r in records:
            if r["source_id"] not in used:
                result.append(
                    {
                        "id": r["source_id"],
                        "sources": [r],
                        "fields": {
                            k: v
                            for k, v in r.items()
                            if k not in ("id", "source", "source_id")
                        },
                        "conflicts": [],
                    }
                )
    return result


def export_catalog(left, right, review=None):
    """Return schema_version=1 {fingerprint,entities,crosswalk,ready}; crosswalk is CSV source_id,entity_id. Optional review {fingerprint,pairs:[decisions]} is bound to source records. ready means every accepted merge has resolved field conflicts, not that every candidate was reviewed."""
    fingerprint = hashlib.sha256(
        json.dumps([left, right], sort_keys=True).encode()
    ).hexdigest()
    if review is not None and review.get("fingerprint") != fingerprint:
        raise ValueError("stale review")
    entities = reconcile(left, right, (review or {}).get("pairs", []))
    buf = io.StringIO(newline="")
    w = csv.writer(buf)
    w.writerow(["source_id", "entity_id"])
    for e in entities:
        for s in e["sources"]:
            w.writerow([s["source_id"], e["id"]])
    return {
        "schema_version": 1,
        "fingerprint": fingerprint,
        "entities": entities,
        "crosswalk": buf.getvalue(),
        "ready": not any((e["conflicts"] for e in entities)),
    }

package main

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os/exec"
	"regexp"
	"strings"
	"time"
)

type GitRecord struct {
	Commit                   Commit
	Body, Migration, Reverts string
}
type GitSnapshot struct {
	From, To, SHA256 string
	Records          []GitRecord
}

func ParseGitExport(raw []byte) ([]GitRecord, error) {
	if len(raw) > 4<<20 {
		return nil, ErrLimit
	}
	if len(bytes.TrimSpace(raw)) == 0 {
		return []GitRecord{}, nil
	}
	parts := strings.Split(string(raw), "\x00")
	if len(parts)%3 != 1 || strings.TrimSpace(parts[len(parts)-1]) != "" {
		return nil, ErrInvalid
	}
	records := []GitRecord{}
	seen := map[string]bool{}
	for i := 0; i < len(parts)-1; i += 3 {
		parsed, err := ParseLog(strings.TrimSpace(parts[i]) + "\t" + parts[i+1])
		if err != nil || len(parsed) != 1 {
			return nil, ErrInvalid
		}
		c := parsed[0]
		if seen[c.Hash] {
			return nil, ErrConflict
		}
		seen[c.Hash] = true
		body := parts[i+2]
		migration := ""
		collecting := false
		for _, line := range strings.Split(body, "\n") {
			if strings.HasPrefix(line, "BREAKING CHANGE:") || strings.HasPrefix(line, "BREAKING-CHANGE:") {
				migration = strings.TrimSpace(strings.SplitN(line, ":", 2)[1])
				collecting = true
			} else if collecting && strings.TrimSpace(line) != "" {
				migration += " " + strings.TrimSpace(line)
			} else {
				collecting = false
			}
		}
		c.Breaking = migration != ""
		target := ""
		match := regexp.MustCompile(`(?m)^This reverts commit ([0-9a-f]{40})\.$`).FindStringSubmatch(body)
		if match != nil {
			target = match[1]
		}
		records = append(records, GitRecord{c, body, migration, target})
	}
	return records, nil
}

type boundedBuffer struct {
	bytes.Buffer
	limit int
}

func (b *boundedBuffer) Write(p []byte) (int, error) {
	if len(p) > b.limit-b.Len() {
		return 0, ErrLimit
	}
	return b.Buffer.Write(p)
}
func gitRead(ctx context.Context, repo string, args ...string) ([]byte, error) {
	command := exec.CommandContext(ctx, "git", append([]string{"--no-pager", "-C", repo}, args...)...)
	out := &boundedBuffer{limit: 4 << 20}
	command.Stdout = out
	command.Stderr = io.Discard
	if err := command.Run(); err != nil {
		return nil, fmt.Errorf("git read failed: %w", err)
	}
	return out.Bytes(), nil
}
func ReadRepository(repo, from, to string) (GitSnapshot, error) {
	var snapshot GitSnapshot
	if repo == "" || from == "" || to == "" {
		return snapshot, ErrInvalid
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	resolve := func(ref string) (string, error) {
		raw, err := gitRead(ctx, repo, "rev-parse", "--verify", "--end-of-options", ref+"^{commit}")
		if err != nil {
			return "", err
		}
		id := strings.TrimSpace(string(raw))
		if !regexp.MustCompile(`^[0-9a-f]{40}$`).MatchString(id) {
			return "", ErrInvalid
		}
		return id, nil
	}
	var err error
	snapshot.From, err = resolve(from)
	if err != nil {
		return snapshot, err
	}
	snapshot.To, err = resolve(to)
	if err != nil {
		return snapshot, err
	}
	raw, err := gitRead(ctx, repo, "log", "--no-show-signature", "--format=%H%x00%s%x00%b%x00", snapshot.From+".."+snapshot.To, "--")
	if err != nil {
		return snapshot, err
	}
	snapshot.Records, err = ParseGitExport(raw)
	sum := sha256.Sum256(raw)
	snapshot.SHA256 = hex.EncodeToString(sum[:])
	return snapshot, err
}
func ReleaseSnapshot(label string, snapshot GitSnapshot, max int) (string, error) {
	commits := make([]Commit, len(snapshot.Records))
	for i, r := range snapshot.Records {
		commits[i] = r.Commit
	}
	output, err := Release(label, commits, max)
	if err != nil {
		return "", err
	}
	escape := strings.NewReplacer("\\", "\\\\", "[", "\\[", "]", "\\]", "<", "&lt;", ">", "&gt;", "*", "\\*", "_", "\\_", "`", "\\`", "\n", " ", "\r", " ")
	output += "\n## Migration and revert review\n"
	found := false
	for _, record := range snapshot.Records {
		if record.Migration != "" {
			output += fmt.Sprintf("- %s: %s\n", record.Commit.Hash, escape.Replace(record.Migration))
			found = true
		}
		if record.Reverts != "" {
			output += fmt.Sprintf("- %s reverts %s. Both records remain visible; review the final behavior.\n", record.Commit.Hash, record.Reverts)
			found = true
		}
	}
	if !found {
		output += "No migration footer or explicit revert reference was supplied. Review breaking subjects manually.\n"
	}
	output += fmt.Sprintf("\nSource range: %s..%s\nExport SHA-256: %s\n", escape.Replace(snapshot.From), escape.Replace(snapshot.To), escape.Replace(snapshot.SHA256))
	return output, nil
}

package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"flag"
	"fmt"
	"os"
)

func main() {
	repo := flag.String("repo", "", "read-only repository path")
	from := flag.String("from", "", "exclusive starting revision")
	to := flag.String("to", "HEAD", "inclusive ending revision")
	input := flag.String("input", "", "NUL-delimited Git export")
	label := flag.String("label", "v0.2.0", "release label")
	output := flag.String("output", "", "Markdown output path; stdout if omitted")
	receipt := flag.String("receipt", "", "JSON source receipt path")
	flag.Parse()
	var snapshot GitSnapshot
	var err error
	if *repo != "" && *input != "" {
		err = ErrInvalid
	} else if *repo != "" {
		snapshot, err = ReadRepository(*repo, *from, *to)
	} else {
		raw := []byte("abc1234\x00feat(index): cache evidence\x00\x00\ndef5678\x00fix: preserve citation offsets\x00BREAKING CHANGE: Rebuild cached citation offsets before upgrading.\x00\n")
		if *input != "" {
			raw, err = os.ReadFile(*input)
		}
		if err == nil {
			snapshot.Records, err = ParseGitExport(raw)
			sum := sha256.Sum256(raw)
			snapshot.SHA256 = hex.EncodeToString(sum[:])
			snapshot.From = "export"
			snapshot.To = "export"
		}
	}
	var text string
	if err == nil {
		text, err = ReleaseSnapshot(*label, snapshot, 1000)
	}
	if err == nil && *output != "" {
		err = os.WriteFile(*output, []byte(text), 0600)
	} else if err == nil {
		fmt.Print(text)
	}
	if err == nil && *receipt != "" {
		var raw []byte
		raw, err = json.MarshalIndent(snapshot, "", "  ")
		if err == nil {
			err = os.WriteFile(*receipt, raw, 0600)
		}
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "changelog:", err)
		os.Exit(1)
	}
}

package main

import "strings"

func ParseLog(text string) ([]Commit, error) {
	out := []Commit{}
	seen := map[string]bool{}
	for _, line := range strings.Split(strings.TrimSpace(text), "\n") {
		if line == "" {
			continue
		}
		p := strings.SplitN(line, "\t", 2)
		if len(p) != 2 || len(p[0]) < 7 || len(p[0]) > 40 || strings.TrimSpace(p[1]) == "" {
			return nil, ErrInvalid
		}
		for _, c := range p[0] {
			if !strings.ContainsRune("0123456789abcdef", c) {
				return nil, ErrInvalid
			}
		}
		if seen[p[0]] {
			return nil, ErrConflict
		}
		seen[p[0]] = true
		out = append(out, Commit{Hash: p[0], Subject: p[1]})
	}
	return out, nil
}

package main

import (
	"regexp"
	"strings"
)

func Classify(c Commit) (Commit, error) {
	r := regexp.MustCompile(`^([a-z]+)(?:\(([a-z0-9_-]+)\))?(!)?: (.+)$`)
	m := r.FindStringSubmatch(c.Subject)
	if m == nil {
		if strings.TrimSpace(c.Subject) == "" {
			return c, ErrInvalid
		}
		c.Kind = "other"
		c.Description = c.Subject
		return c, nil
	}
	c.Kind = m[1]
	c.Scope = m[2]
	c.Breaking = c.Breaking || m[3] == "!"
	c.Description = m[4]
	return c, nil
}

package main

import "sort"

func Group(commits []Commit) (map[string][]Commit, error) {
	out := map[string][]Commit{}
	for _, raw := range commits {
		c, e := Classify(raw)
		if e != nil {
			return nil, e
		}
		group := "Other"
		if c.Breaking {
			group = "Breaking changes"
		} else if c.Kind == "feat" {
			group = "Features"
		} else if c.Kind == "fix" {
			group = "Fixes"
		}
		out[group] = append(out[group], c)
	}
	for key := range out {
		sort.Slice(out[key], func(i, j int) bool { return out[key][i].Hash < out[key][j].Hash })
	}
	return out, nil
}

package main

import (
	"fmt"
	"regexp"
	"strings"
)

func Release(label string, commits []Commit, max int) (string, error) {
	if !regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$`).MatchString(label) {
		return "", ErrInvalid
	}
	if max < 0 || len(commits) > max {
		return "", ErrLimit
	}
	groups, e := Group(commits)
	if e != nil {
		return "", e
	}
	escape := strings.NewReplacer("\\", "\\\\", "[", "\\[", "]", "\\]", "<", "&lt;", ">", "&gt;", "*", "\\*", "_", "\\_", "`", "\\`", "\n", " ", "\r", " ")
	out := "# " + label + "\n"
	for _, key := range []string{"Breaking changes", "Features", "Fixes", "Other"} {
		if len(groups[key]) == 0 {
			continue
		}
		out += "\n## " + key + "\n"
		for _, c := range groups[key] {
			out += fmt.Sprintf("- %s (%s)\n", escape.Replace(c.Description), c.Hash)
		}
	}
	return out, nil
}

