package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"reflect"
	"regexp"
	"sort"
	"strings"
)

type Layer struct {
	Name   string         `json:"name"`
	Values map[string]any `json:"values"`
}
type Input struct {
	Layers    []Layer        `json:"layers"`
	Observed  map[string]any `json:"observed"`
	Sensitive []string       `json:"sensitive"`
}
type Source struct {
	Layer string `json:"layer"`
	Value any    `json:"value"`
}
type Effective struct {
	Value   any
	History []Source
}
type Change struct {
	Key      string   `json:"key"`
	Kind     string   `json:"kind"`
	Expected any      `json:"expected"`
	Observed any      `json:"observed"`
	History  []Source `json:"history"`
	Redacted bool     `json:"redacted"`
}
type Report struct {
	SchemaVersion int      `json:"schemaVersion"`
	Drift         bool     `json:"drift"`
	Changes       []Change `json:"changes"`
}

func Load(data []byte) (Input, error) {
	var in Input
	if len(data) > 1<<20 {
		return in, errors.New("input exceeds one MiB")
	}
	d := json.NewDecoder(bytes.NewReader(data))
	d.DisallowUnknownFields()
	if err := d.Decode(&in); err != nil {
		return in, err
	}
	var tail any
	if d.Decode(&tail) != io.EOF {
		return in, errors.New("trailing JSON")
	}
	if in.Layers == nil || in.Observed == nil {
		return in, errors.New("layers and observed are required")
	}
	seen := map[string]bool{}
	for _, l := range in.Layers {
		if strings.TrimSpace(l.Name) == "" || seen[l.Name] || l.Values == nil {
			return in, errors.New("invalid or duplicate layer")
		}
		seen[l.Name] = true
		if err := validate(l.Values); err != nil {
			return in, err
		}
	}
	if err := validate(in.Observed); err != nil {
		return in, err
	}
	for _, k := range in.Sensitive {
		if strings.TrimSpace(k) == "" {
			return in, errors.New("blank sensitive key")
		}
	}
	return in, nil
}
func validate(values map[string]any) error {
	for k, v := range values {
		if strings.TrimSpace(k) == "" || strings.ContainsAny(k, "\r\n\x00") {
			return errors.New("invalid key")
		}
		switch v.(type) {
		case nil, string, bool, float64:
		default:
			return errors.New("values must be JSON scalars")
		}
	}
	return nil
}
func Resolve(layers []Layer) map[string]Effective {
	out := map[string]Effective{}
	for _, l := range layers {
		for k, v := range l.Values {
			e := out[k]
			e.Value = v
			e.History = append(e.History, Source{l.Name, v})
			out[k] = e
		}
	}
	return out
}

var secret = regexp.MustCompile(`(?i)(password|secret|token|api[_-]?key|credential)`)

func Compare(in Input) Report {
	effective := Resolve(in.Layers)
	keys := map[string]bool{}
	sensitive := map[string]bool{}
	for _, k := range in.Sensitive {
		sensitive[k] = true
	}
	for k := range effective {
		keys[k] = true
	}
	for k := range in.Observed {
		keys[k] = true
	}
	order := []string{}
	for k := range keys {
		order = append(order, k)
	}
	sort.Strings(order)
	out := Report{SchemaVersion: 1, Changes: []Change{}}
	for _, k := range order {
		e, expected := effective[k]
		actual, observed := in.Observed[k]
		kind := "equal"
		if !expected {
			kind = "unexpected"
		} else if !observed {
			kind = "missing"
		} else if !reflect.DeepEqual(e.Value, actual) {
			kind = "changed"
		}
		if kind != "equal" {
			out.Drift = true
		}
		c := Change{Key: k, Kind: kind, Expected: e.Value, Observed: actual, History: append([]Source{}, e.History...), Redacted: secret.MatchString(k) || sensitive[k]}
		if c.Redacted {
			if expected {
				c.Expected = "[REDACTED]"
			}
			if observed {
				c.Observed = "[REDACTED]"
			}
			for i := range c.History {
				c.History[i].Value = "[REDACTED]"
			}
		}
		out.Changes = append(out.Changes, c)
	}
	return out
}
func Export(in Input) ([]byte, error) { return json.MarshalIndent(Compare(in), "", "  ") }
func main() {
	input := flag.String("input", "fixtures/config.json", "configuration JSON")
	output := flag.String("out", "", "report path (stdout by default)")
	check := flag.Bool("check", false, "exit 2 when drift exists")
	flag.Parse()
	b, err := os.ReadFile(*input)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	in, err := Load(b)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	b, err = Export(in)
	if err == nil && *output != "" {
		err = os.WriteFile(*output, append(b, '\n'), 0600)
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Println(string(b))
	if *check && Compare(in).Drift {
		os.Exit(2)
	}
}

import csv, io, datetime, copy, hashlib, json


def profile(text):
    """Parse CSV text into {columns, rows, profile}; profile maps each column to {missing, unique}. Reject empty/duplicate headers and ragged rows. Preserve cells exactly."""
    try:
        data = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as error:
        raise ValueError("malformed CSV: " + str(error)) from error
    if (
        not data
        or not data[0]
        or any((not c.strip() for c in data[0]))
        or (len(set(data[0])) != len(data[0]))
    ):
        raise ValueError("unique nonempty headers required")
    cols = data[0]
    if any((len(r) != len(cols) for r in data[1:])):
        raise ValueError("ragged row")
    rows = [dict(zip(cols, r)) for r in data[1:]]
    return {
        "columns": cols,
        "rows": rows,
        "profile": {
            c: {
                "missing": sum((not r[c].strip() for r in rows)),
                "unique": len({r[c] for r in rows}),
            }
            for c in cols
        },
    }


def propose(table, aliases=None, date_columns=None):
    """Return schema_version=1 recipe with ordered trim, alias, date rules. aliases maps column to exact trimmed spelling->canonical spelling. Dates accept ISO or unambiguous DD/MM/YYYY; ambiguous dates await review."""
    aliases = aliases or {}
    date_columns = date_columns or []
    if any((c not in table["columns"] for c in [*aliases, *date_columns])):
        raise ValueError("unknown column")
    rules = []
    for c in table["columns"]:
        rules.append({"column": c, "operation": "trim"})
        if c in aliases:
            if not isinstance(aliases[c], dict) or any(
                (not isinstance(v, str) for v in aliases[c].values())
            ):
                raise ValueError("invalid alias map")
            rules.append({"column": c, "operation": "alias", "values": aliases[c]})
        if c in date_columns:
            rules.append({"column": c, "operation": "date"})
    return {"schema_version": 1, "rules": rules}


def preview(table, recipe):
    """Return {rows,changes,pending,fingerprint}; row numbers are CSV data rows starting at 1. Changes name row,column,before,after; ambiguous/invalid dates remain unchanged and appear in pending. Never mutate input."""
    if recipe.get("schema_version") != 1:
        raise ValueError("unsupported recipe")
    rows = copy.deepcopy(table["rows"])
    pending = []
    for rule in recipe["rules"]:
        col = rule.get("column")
        op = rule.get("operation")
        if col not in table["columns"] or op not in ("trim", "alias", "date"):
            raise ValueError("invalid rule")
        for n, row in enumerate(rows, 1):
            value = row[col]
            if op == "trim":
                row[col] = value.strip()
            elif op == "alias":
                row[col] = rule["values"].get(value, value)
            elif value:
                try:
                    if "/" in value:
                        a, b, y = map(int, value.split("/"))
                        if a <= 12 and b <= 12 and (a != b):
                            pending.append(
                                {
                                    "row": n,
                                    "column": col,
                                    "value": value,
                                    "reason": "ambiguous date",
                                }
                            )
                            continue
                        if a > 12:
                            parsed = datetime.date(y, b, a)
                        elif b > 12:
                            parsed = datetime.date(y, a, b)
                        else:
                            parsed = datetime.date(y, b, a)
                    else:
                        parsed = datetime.date.fromisoformat(value)
                    row[col] = parsed.isoformat()
                except (ValueError, TypeError):
                    pending.append(
                        {
                            "row": n,
                            "column": col,
                            "value": value,
                            "reason": "invalid date",
                        }
                    )
    changes = [
        {"row": n, "column": c, "before": old[c], "after": new[c]}
        for n, (old, new) in enumerate(zip(table["rows"], rows), 1)
        for c in table["columns"]
        if old[c] != new[c]
    ]
    digest = hashlib.sha256(
        json.dumps({"table": table, "recipe": recipe}, sort_keys=True).encode()
    ).hexdigest()
    return {"rows": rows, "changes": changes, "pending": pending, "fingerprint": digest}


def repair(table, recipe, decisions=None):
    """Return {csv,recipe,changes,pending,fingerprint}. Optional {fingerprint,cells:[{row,column,value}]} resolves pending cells only, rejecting stale fingerprints, duplicate edits and non-ISO replacement dates. Unresolved cells stay original."""
    result = preview(table, recipe)
    if decisions is not None:
        if decisions.get("fingerprint") != result["fingerprint"]:
            raise ValueError("stale review")
        allowed = {(p["row"], p["column"]) for p in result["pending"]}
        seen = set()
        for d in decisions.get("cells", []):
            key = (d["row"], d["column"])
            if key not in allowed or key in seen:
                raise ValueError("invalid review cell")
            datetime.date.fromisoformat(d["value"])
            seen.add(key)
            result["rows"][d["row"] - 1][d["column"]] = d["value"]
        result["pending"] = [
            p for p in result["pending"] if (p["row"], p["column"]) not in seen
        ]
        result["changes"] = [
            {"row": n, "column": c, "before": old[c], "after": new[c]}
            for n, (old, new) in enumerate(zip(table["rows"], result["rows"]), 1)
            for c in table["columns"]
            if old[c] != new[c]
        ]
    out = io.StringIO(newline="")
    writer = csv.DictWriter(out, fieldnames=table["columns"])
    writer.writeheader()
    writer.writerows(result["rows"])
    return {**result, "csv": out.getvalue(), "recipe": recipe}

