package main

import "hash/fnv"

func Partition(ids []string, shards int) ([][]string, error) {
	if shards < 1 || shards > 1024 {
		return nil, ErrInvalid
	}
	out := make([][]string, shards)
	seen := map[string]bool{}
	for _, id := range ids {
		if id == "" {
			return nil, ErrInvalid
		}
		if seen[id] {
			return nil, ErrConflict
		}
		seen[id] = true
		h := fnv.New32a()
		h.Write([]byte(id))
		index := int(h.Sum32() % uint32(shards))
		out[index] = append(out[index], id)
	}
	return out, nil
}

package main

import "math"

func Acquire(l *Lease, worker string, now, ttl int64) error {
	if l.Shard == "" || worker == "" || now < 0 || ttl <= 0 || now > math.MaxInt64-ttl {
		return ErrInvalid
	}
	if l.Done || (l.Worker != "" && now < l.Until) {
		return ErrConflict
	}
	l.Worker = worker
	l.Until = now + ttl
	l.Version++
	return nil
}

package main

func Submit(l *Lease, worker string, version int, now int64, result string) error {
	if result == "" || len(result) > 1024*1024 || now < 0 {
		return ErrInvalid
	}
	if l.Worker != worker || l.Version != version {
		return ErrConflict
	}
	if l.Done {
		if l.Result == result {
			return nil
		}
		return ErrConflict
	}
	if now >= l.Until {
		return ErrConflict
	}
	l.Result = result
	l.Done = true
	return nil
}

package main

import (
	"context"
	"sort"
	"sync"
)

func Parallel(ctx context.Context, ids []string, workers int, run func(context.Context, string) (string, error)) ([]Item, error) {
	if workers < 1 || workers > 64 || run == nil {
		return nil, ErrInvalid
	}
	if _, e := Partition(ids, 1); e != nil {
		return nil, e
	}
	type answer struct {
		item Item
		err  error
	}
	jobs := make(chan string)
	results := make(chan answer, len(ids))
	var group sync.WaitGroup
	for i := 0; i < workers; i++ {
		group.Add(1)
		go func() {
			defer group.Done()
			for id := range jobs {
				if e := ctx.Err(); e != nil {
					results <- answer{err: e}
					continue
				}
				value, e := run(ctx, id)
				results <- answer{Item{id, value}, e}
			}
		}()
	}
	go func() {
		defer close(jobs)
		for _, id := range ids {
			select {
			case <-ctx.Done():
				return
			case jobs <- id:
			}
		}
	}()
	go func() { group.Wait(); close(results) }()
	out := []Item{}
	var first error
	for answer := range results {
		if answer.err != nil {
			if first == nil {
				first = answer.err
			}
			continue
		}
		out = append(out, answer.item)
	}
	if e := ctx.Err(); e != nil {
		return out, e
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out, first
}

