package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"sort"
	"time"
)

type Metadata struct {
	UID             string            `json:"uid"`
	Name            string            `json:"name"`
	Namespace       string            `json:"namespace"`
	ResourceVersion string            `json:"resourceVersion"`
	Creation        string            `json:"creationTimestamp"`
	Annotations     map[string]string `json:"annotations"`
	Owners          []struct {
		UID string `json:"uid"`
	} `json:"ownerReferences"`
}
type ObjectRef struct {
	UID             string `json:"uid"`
	Kind            string `json:"kind"`
	Name            string `json:"name"`
	Namespace       string `json:"namespace"`
	ResourceVersion string `json:"resourceVersion"`
}
type Event struct {
	Metadata  Metadata  `json:"metadata"`
	Object    ObjectRef `json:"involvedObject"`
	Reason    string    `json:"reason"`
	Type      string    `json:"type"`
	Count     int       `json:"count"`
	First     string    `json:"firstTimestamp"`
	Last      string    `json:"lastTimestamp"`
	EventTime string    `json:"eventTime"`
	Series    *struct {
		Count int    `json:"count"`
		Last  string `json:"lastObservedTime"`
	} `json:"series"`
}
type Workload struct {
	Metadata Metadata `json:"metadata"`
	Kind     string   `json:"kind"`
}
type Bundle struct {
	ObservedAt string `json:"observedAt"`
	Events     struct {
		Items []Event `json:"items"`
	} `json:"events"`
	Workloads struct {
		Items []Workload `json:"items"`
	} `json:"workloads"`
}
type Row struct {
	Object        ObjectRef `json:"object"`
	Reason        string    `json:"reason"`
	Type          string    `json:"type"`
	Count         int       `json:"count"`
	First         string    `json:"firstOccurrence"`
	Last          string    `json:"lastOccurrence"`
	ObservedAt    string    `json:"observedAt"`
	EventUIDs     []string  `json:"eventUIDs"`
	Revision      string    `json:"revision,omitempty"`
	Investigation string    `json:"investigation"`
}
type Pack struct {
	SchemaVersion int      `json:"schemaVersion"`
	ObservedAt    string   `json:"observedAt"`
	Rows          []Row    `json:"rows"`
	Redactions    []string `json:"redactions"`
}

func stamp(s string) (time.Time, error) { return time.Parse(time.RFC3339Nano, s) }
func Parse(data []byte) (Bundle, error) {
	var b Bundle
	if len(data) > 1<<20 {
		return b, errors.New("bundle exceeds one MiB")
	}
	d := json.NewDecoder(bytes.NewReader(data))
	if err := d.Decode(&b); err != nil {
		return b, err
	}
	var tail any
	if d.Decode(&tail) != io.EOF {
		return b, errors.New("trailing JSON")
	}
	if _, err := stamp(b.ObservedAt); err != nil {
		return b, errors.New("observedAt must be RFC3339")
	}
	if b.Events.Items == nil || b.Workloads.Items == nil {
		return b, errors.New("both items arrays required")
	}
	for i := range b.Events.Items {
		e := &b.Events.Items[i]
		if e.Metadata.UID == "" || e.Object.UID == "" || e.Reason == "" || e.Object.Name == "" {
			return b, errors.New("event UID, object UID, name and reason required")
		}
		if e.First == "" {
			e.First = e.EventTime
		}
		if e.First == "" {
			e.First = e.Metadata.Creation
		}
		if e.Last == "" {
			e.Last = e.First
		}
		if e.Count == 0 {
			e.Count = 1
		}
		if e.Series != nil {
			e.Count = e.Series.Count
			e.Last = e.Series.Last
		}
		a, x := stamp(e.First)
		z, y := stamp(e.Last)
		if x != nil || y != nil || z.Before(a) || e.Count < 1 {
			return b, errors.New("invalid occurrence range or count")
		}
	}
	seen := map[string]bool{}
	for _, w := range b.Workloads.Items {
		if w.Metadata.UID == "" || seen[w.Metadata.UID] {
			return b, errors.New("invalid or duplicate workload UID")
		}
		seen[w.Metadata.UID] = true
	}
	return b, nil
}
func Group(b Bundle) ([]Row, error) {
	unique := map[string]Event{}
	for _, e := range b.Events.Items {
		if old, ok := unique[e.Metadata.UID]; ok {
			if old.Object.UID != e.Object.UID || old.Reason != e.Reason || old.Type != e.Type {
				return nil, errors.New("event UID changed identity")
			}
			if e.Count < old.Count {
				e.Count = old.Count
			}
			if before(old.First, e.First) {
				e.First = old.First
			}
			if before(e.Last, old.Last) {
				e.Last = old.Last
			}
		}
		unique[e.Metadata.UID] = e
	}
	groups := map[string]Row{}
	uids := make([]string, 0, len(unique))
	for uid := range unique {
		uids = append(uids, uid)
	}
	sort.Strings(uids)
	for _, uid := range uids {
		e := unique[uid]
		key := e.Object.UID + "\x00" + e.Reason + "\x00" + e.Type
		r, ok := groups[key]
		if !ok {
			r = Row{Object: e.Object, Reason: e.Reason, Type: e.Type, First: e.First, Last: e.Last, ObservedAt: b.ObservedAt, EventUIDs: []string{}}
		}
		r.Count += e.Count
		if before(e.First, r.First) {
			r.First = e.First
		}
		if before(r.Last, e.Last) {
			r.Last = e.Last
		}
		r.EventUIDs = append(r.EventUIDs, uid)
		groups[key] = r
	}
	out := []Row{}
	for _, r := range groups {
		sort.Strings(r.EventUIDs)
		out = append(out, r)
	}
	sort.Slice(out, func(i, j int) bool {
		if before(out[i].First, out[j].First) {
			return true
		}
		if before(out[j].First, out[i].First) {
			return false
		}
		return out[i].Object.UID+"\x00"+out[i].Reason+"\x00"+out[i].Type < out[j].Object.UID+"\x00"+out[j].Reason+"\x00"+out[j].Type
	})
	return out, nil
}
func before(a, b string) bool { x, _ := stamp(a); y, _ := stamp(b); return x.Before(y) }
func Connect(rows []Row, workloads []Workload) []Row {
	byUID := map[string]Workload{}
	for _, w := range workloads {
		byUID[w.Metadata.UID] = w
	}
	out := append([]Row{}, rows...)
	for i := range out {
		r := &out[i]
		queue := []string{r.Object.UID}
		seen := map[string]bool{}
		revisions := map[string]bool{}
		for len(queue) > 0 {
			uid := queue[0]
			queue = queue[1:]
			if seen[uid] {
				continue
			}
			seen[uid] = true
			if w, ok := byUID[uid]; ok {
				if rev := w.Metadata.Annotations["deployment.kubernetes.io/revision"]; rev != "" {
					revisions[rev] = true
				}
				for _, o := range w.Metadata.Owners {
					queue = append(queue, o.UID)
				}
			}
		}
		if len(revisions) == 1 {
			for rev := range revisions {
				r.Revision = rev
			}
		}
		r.Investigation = "Inspect the referenced object and its controller events"
		if r.Reason == "Failed" || r.Reason == "BackOff" {
			r.Investigation = "Inspect image references, pull credentials and container state; event reason alone does not prove cause"
		}
	}
	return out
}
func Export(b Bundle) (Pack, error) {
	rows, e := Group(b)
	if e != nil {
		return Pack{}, e
	}
	return Pack{1, b.ObservedAt, Connect(rows, b.Workloads.Items), []string{"event messages omitted", "workload spec, status, labels and unrelated annotations omitted"}}, nil
}
func main() {
	input := flag.String("input", "fixtures/rollout.json", "exported snapshot bundle")
	out := flag.String("out", "/tmp/aiefs-kubernetes-context.json", "context pack")
	flag.Parse()
	data, e := os.ReadFile(*input)
	if e != nil {
		fmt.Fprintln(os.Stderr, e)
		os.Exit(1)
	}
	b, e := Parse(data)
	if e != nil {
		fmt.Fprintln(os.Stderr, e)
		os.Exit(1)
	}
	pack, e := Export(b)
	if e != nil {
		fmt.Fprintln(os.Stderr, e)
		os.Exit(1)
	}
	data, e = json.MarshalIndent(pack, "", "  ")
	if e == nil {
		e = os.WriteFile(*out, append(data, '\n'), 0600)
	}
	if e != nil {
		fmt.Fprintln(os.Stderr, e)
		os.Exit(1)
	}
	fmt.Println(string(data))
}

export function parsePack(text: string) {
  if (Buffer.byteLength(text) > 1_048_576) throw Error("pack too large");
  const p = JSON.parse(text);
  if (
    p.schemaVersion !== 1 ||
    !Array.isArray(p.rows) ||
    !Array.isArray(p.redactions) ||
    !Number.isFinite(Date.parse(p.observedAt))
  )
    throw Error("invalid context pack");
  for (const r of p.rows) {
    if (
      !r.object?.uid ||
      typeof r.reason !== "string" ||
      typeof r.type !== "string" ||
      !Number.isInteger(r.count) ||
      r.count < 1 ||
      !Array.isArray(r.eventUIDs) ||
      !r.eventUIDs.length ||
      r.eventUIDs.some((x) => typeof x !== "string" || !x) ||
      !Number.isFinite(Date.parse(r.firstOccurrence)) ||
      !Number.isFinite(Date.parse(r.lastOccurrence)) ||
      Date.parse(r.firstOccurrence) > Date.parse(r.lastOccurrence)
    )
      throw Error("invalid timeline row");
  }
  return p;
}
const escape = (s: any) =>
  String(s ?? "").replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ]!,
  );
export function timeline(p: any) {
  const rows = p.rows
    .map(
      (r: any) =>
        `<tr data-type="${escape(r.type)}"><td>${escape(r.firstOccurrence)}<small>last ${escape(r.lastOccurrence)}</small></td><td>${escape(r.object.namespace)}/${escape(r.object.name)}<small>UID ${escape(r.object.uid)} / revision ${escape(r.revision ?? "unknown")}</small></td><td>${escape(r.reason)} (${r.count})<small>${escape(r.investigation)}</small></td><td>${r.eventUIDs.map(escape).join(", ")}</td></tr>`,
    )
    .join("");
  const payload = JSON.stringify(p).replaceAll("<", "\\u003c");
  return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kubernetes event storyboard</title><style>body{font:16px system-ui;background:#f4f7fc;color:#173047;max-width:1100px;margin:40px auto;padding:0 20px}small{display:block;margin-top:8px;color:#597086}td,th{padding:16px;border-bottom:1px solid #b7c7d5;text-align:left;vertical-align:top}table{width:100%;min-width:760px;border-collapse:collapse}.scroll{overflow:auto}button{padding:12px;margin:16px 0} @media(prefers-color-scheme:dark){body{background:#10212f;color:#e7f1fa}small{color:#aabfce}}</style><h1>Kubernetes event storyboard</h1><p>Observed ${escape(p.observedAt)}. Occurrence time is shown separately.</p><label><input id="warnings" type="checkbox"> Show Warning events only</label><div class="scroll"><table><thead><tr><th>Occurrence</th><th>Object identity</th><th>Evidence</th><th>Event UIDs</th></tr></thead><tbody>${rows}</tbody></table></div><button id="download">Download redacted context</button><p>${p.redactions.map(escape).join("; ")}. Event reasons suggest investigations, not proven causes.</p><script>const pack=${payload};document.querySelector('#warnings').onchange=e=>{for(const row of document.querySelectorAll('tbody tr'))row.hidden=e.target.checked&&row.dataset.type!=='Warning'};document.querySelector('#download').onclick=()=>{const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(pack,null,2)],{type:'application/json'}));a.href=u;a.download='context-pack.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};</script></html>`;
}

package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"regexp"
	"strconv"
	"time"
)

var providerNamePattern = regexp.MustCompile(`^[a-zA-Z0-9_-]{1,64}$`)
var environmentNamePattern = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)

type Provider struct {
	Name   string `json:"name"`
	URL    string `json:"url"`
	KeyEnv string `json:"key_env,omitempty"`
	Model  string `json:"model,omitempty"`
}
type Config struct {
	Providers   []Provider `json:"providers"`
	MaxAttempts int        `json:"max_attempts"`
	MaxBytes    int64      `json:"max_response_bytes"`
	TimeoutMS   int        `json:"timeout_ms"`
}

func ReadBounded(path string) ([]byte, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	data, err := io.ReadAll(io.LimitReader(f, MaxRequestBytes+1))
	if len(data) > MaxRequestBytes {
		return nil, ErrLimit
	}
	return data, err
}
func ParseConfig(data []byte) (Config, error) {
	var config Config
	if len(data) > MaxRequestBytes {
		return config, ErrLimit
	}
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&config); err != nil {
		return config, err
	}
	var extra any
	if decoder.Decode(&extra) != io.EOF {
		return config, ErrInvalid
	}
	return config, config.Validate()
}
func (c Config) Validate() error {
	if len(c.Providers) < 1 || len(c.Providers) > 16 || c.MaxAttempts < 1 || c.MaxAttempts > 16 || c.MaxBytes < 1 || c.MaxBytes > 16*1024*1024 || c.TimeoutMS < 1 || c.TimeoutMS > 5000 {
		return ErrInvalid
	}
	names := map[string]bool{}
	urls := map[string]bool{}
	for _, p := range c.Providers {
		if !providerNamePattern.MatchString(p.Name) || names[p.Name] || urls[p.URL] {
			return ErrConflict
		}
		if _, err := Endpoints([]string{p.URL}); err != nil {
			return err
		}
		if p.KeyEnv != "" && !environmentNamePattern.MatchString(p.KeyEnv) {
			return ErrInvalid
		}
		names[p.Name] = true
		urls[p.URL] = true
	}
	return nil
}

type providerTransport struct {
	base      http.RoundTripper
	providers map[string]Provider
	keys      map[string]string
}

func (t providerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	provider, ok := t.providers[req.URL.String()]
	if !ok {
		return nil, ErrInvalid
	}
	outbound := req.Clone(req.Context())
	outbound.Header = req.Header.Clone()
	outbound.Header.Del("Authorization")
	if key := t.keys[provider.URL]; key != "" {
		outbound.Header.Set("Authorization", "Bearer "+key)
	}
	if provider.Model != "" {
		data, err := io.ReadAll(io.LimitReader(req.Body, MaxRequestBytes+1))
		req.Body.Close()
		if err != nil || len(data) > MaxRequestBytes {
			return nil, ErrInvalid
		}
		var payload map[string]any
		decoder := json.NewDecoder(bytes.NewReader(data))
		decoder.UseNumber()
		if decoder.Decode(&payload) != nil || payload == nil {
			return nil, ErrInvalid
		}
		payload["model"] = provider.Model
		data, err = json.Marshal(payload)
		if err != nil {
			return nil, err
		}
		outbound.Body = io.NopCloser(bytes.NewReader(data))
		outbound.GetBody = func() (io.ReadCloser, error) { return io.NopCloser(bytes.NewReader(data)), nil }
		outbound.ContentLength = int64(len(data))
	}
	return t.base.RoundTrip(outbound)
}
func RouteConfigured(ctx context.Context, client *http.Client, config Config, payload string) (Outcome, error) {
	if err := config.Validate(); err != nil {
		return Outcome{}, err
	}
	if client == nil {
		return Outcome{}, ErrInvalid
	}
	if !validPayload([]byte(payload)) {
		return Outcome{}, ErrInvalid
	}
	endpoints := []string{}
	providers := map[string]Provider{}
	keys := map[string]string{}
	for _, p := range config.Providers {
		endpoints = append(endpoints, p.URL)
		providers[p.URL] = p
		if p.KeyEnv != "" {
			key := os.Getenv(p.KeyEnv)
			if key == "" {
				return Outcome{}, fmt.Errorf("missing credential environment variable %s", p.KeyEnv)
			}
			keys[p.URL] = key
		}
	}
	configured := *client
	base := client.Transport
	if base == nil {
		base = http.DefaultTransport
	}
	configured.Transport = providerTransport{base: base, providers: providers, keys: keys}
	ctx, cancel := context.WithTimeout(ctx, time.Duration(config.TimeoutMS)*time.Millisecond)
	defer cancel()
	return Route(ctx, &configured, endpoints, payload, config.MaxAttempts, config.MaxBytes)
}
func validPayload(data []byte) bool {
	if len(data) > MaxRequestBytes {
		return false
	}
	var body map[string]any
	if json.Unmarshal(data, &body) != nil || body == nil {
		return false
	}
	if stream, exists := body["stream"]; exists && stream != false {
		return false
	}
	return true
}
func writeGatewayError(w http.ResponseWriter, status int, message, state string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(struct {
		Error string `json:"error"`
		State string `json:"state,omitempty"`
	}{message, state})
}

func GatewayHandler(config Config, client *http.Client) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.URL.Path != "/v1/chat/completions" {
			writeGatewayError(w, 404, "not-found", "")
			return
		}
		if r.Method != http.MethodPost {
			w.Header().Set("Allow", "POST")
			writeGatewayError(w, 405, "method", "")
			return
		}
		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, MaxRequestBytes))
		if err != nil {
			writeGatewayError(w, 413, "request-limit", "")
			return
		}
		if !validPayload(body) {
			writeGatewayError(w, 400, "expected non-streaming JSON object", "")
			return
		}
		result, err := RouteConfigured(r.Context(), client, config, string(body))
		w.Header().Set("X-Gateway-Attempts", strconv.Itoa(result.Attempts))
		if err != nil {
			status := 502
			if result.State == "cancelled" {
				status = 504
			}
			writeGatewayError(w, status, "gateway-failed", result.State)
			return
		}
		for _, p := range config.Providers {
			if p.URL == result.Reply.Endpoint {
				w.Header().Set("X-Gateway-Provider", p.Name)
			}
		}
		w.WriteHeader(result.Reply.Status)
		io.WriteString(w, result.Reply.Body)
	})
}

