	"flag"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"time"
)

func demo() error {
	primary := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(503)
		fmt.Fprint(w, `{"error":"orchard-primary-busy"}`)
	}))
	defer primary.Close()
	backup := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var body map[string]any
		json.NewDecoder(r.Body).Decode(&body)
		json.NewEncoder(w).Encode(map[string]any{"model": body["model"], "choices": []any{map[string]any{"message": map[string]string{"role": "assistant", "content": "Orchard export links last 15 minutes."}}}})
	}))
	defer backup.Close()
	config := Config{Providers: []Provider{{Name: "primary", URL: primary.URL, Model: "orchard-primary"}, {Name: "backup", URL: backup.URL, Model: "orchard-backup"}}, MaxAttempts: 2, MaxBytes: 4096, TimeoutMS: 1000}
	proxy := httptest.NewServer(GatewayHandler(config, http.DefaultClient))
	defer proxy.Close()
	response, err := http.Post(proxy.URL+"/v1/chat/completions", "application/json", strings.NewReader(`{"model":"caller-default","messages":[{"role":"user","content":"How long do Orchard links last?"}]}`))
	if err != nil {
		return err
	}
	defer response.Body.Close()
	body, err := io.ReadAll(response.Body)
	if err != nil {
		return err
	}
	fmt.Printf("MODE actual loopback HTTP, authored provider responses\nHTTP %d\nATTEMPTS %s\nPROVIDER %s\nBODY %s", response.StatusCode, response.Header.Get("X-Gateway-Attempts"), response.Header.Get("X-Gateway-Provider"), body)
	if response.StatusCode != 200 {
		return ErrInvalid
	}
	return nil
}
func run() error {
	configPath := flag.String("config", "", "provider JSON configuration")
	requestPath := flag.String("request", "", "non-streaming JSON request file")
	listen := flag.String("listen", "", "loopback bind address, for example 127.0.0.1:8088")
	flag.Parse()
	if *configPath == "" {
		if *requestPath != "" || *listen != "" {
			return ErrInvalid
		}
		return demo()
	}
	data, err := ReadBounded(*configPath)
	if err != nil {
		return err
	}
	config, err := ParseConfig(data)
	if err != nil {
		return err
	}
	if *listen != "" {
		if *requestPath != "" {
			return ErrInvalid
		}
		host, _, err := net.SplitHostPort(*listen)
		if err != nil {
			return err
		}
		ip := net.ParseIP(host)
		if host != "localhost" && (ip == nil || !ip.IsLoopback()) {
			return fmt.Errorf("gateway bind must be loopback")
		}
		server := &http.Server{Addr: *listen, Handler: GatewayHandler(config, http.DefaultClient), ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 10 * time.Second, WriteTimeout: time.Duration(config.TimeoutMS)*time.Millisecond + 2*time.Second, IdleTimeout: 30 * time.Second, MaxHeaderBytes: 16 * 1024}
		fmt.Printf("Listening on http://%s/v1/chat/completions\n", *listen)
		return server.ListenAndServe()
	}
	if *requestPath == "" {
		return fmt.Errorf("provide --request or --listen")
	}
	data, err = ReadBounded(*requestPath)
	if err != nil {
		return err
	}
	result, routeErr := RouteConfigured(context.Background(), http.DefaultClient, config, string(data))
	if err := json.NewEncoder(os.Stdout).Encode(result); err != nil {
		return err
	}
	return routeErr
}
func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "gateway:", err)
		os.Exit(1)
	}
}

package main

import (
	"net/url"
	"strings"
)

func Endpoints(values []string) ([]string, error) {
	out := []string{}
	seen := map[string]bool{}
	for _, raw := range values {
		u, e := url.Parse(raw)
		if e != nil || u.Hostname() == "" || u.User != nil || u.Fragment != "" || u.RawQuery != "" {
			return nil, ErrInvalid
		}
		local := u.Hostname() == "localhost" || u.Hostname() == "127.0.0.1" || u.Hostname() == "::1"
		if u.Scheme != "https" && !(u.Scheme == "http" && local) {
			return nil, ErrInvalid
		}
		if strings.ContainsAny(raw, "\r\n") {
			return nil, ErrInvalid
		}
		if !seen[raw] {
			seen[raw] = true
			out = append(out, raw)
		}
	}
	if len(out) == 0 {
		return nil, ErrInvalid
	}
	return out, nil
}

package main

func ClassifyStatus(status int) (string, error) {
	if status < 100 || status > 599 {
		return "", ErrInvalid
	}
	if status >= 200 && status < 300 {
		return "success", nil
	}
	if status == 429 || status >= 500 {
		return "retry", nil
	}
	return "terminal", nil
}

package main

import (
	"context"
	"io"
	"net/http"
	"strings"
)

func Attempt(ctx context.Context, client *http.Client, endpoint, payload string, maxBytes int64) (Reply, error) {
	if client == nil || maxBytes < 1 || maxBytes > 16*1024*1024 || len(payload) > MaxRequestBytes {
		return Reply{}, ErrInvalid
	}
	if _, e := Endpoints([]string{endpoint}); e != nil {
		return Reply{}, e
	}
	ctx, cancel := context.WithTimeout(ctx, DefaultTimeout)
	defer cancel()
	req, e := http.NewRequestWithContext(ctx, "POST", endpoint, strings.NewReader(payload))
	if e != nil {
		return Reply{}, e
	}
	req.Header.Set("Content-Type", "application/json")
	boundedClient := *client
	boundedClient.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	response, e := boundedClient.Do(req)
	if e != nil {
		return Reply{}, e
	}
	defer response.Body.Close()
	body, e := io.ReadAll(io.LimitReader(response.Body, maxBytes+1))
	if e != nil {
		return Reply{}, e
	}
	if int64(len(body)) > maxBytes {
		return Reply{}, ErrLimit
	}
	return Reply{response.StatusCode, string(body), endpoint}, nil
}

package main

import (
	"context"
	"errors"
	"net/http"
	"time"
)

func Route(ctx context.Context, client *http.Client, providers []string, payload string, maxAttempts int, maxBytes int64) (Outcome, error) {
	endpoints, err := Endpoints(providers)
	if err != nil {
		return Outcome{}, err
	}
	if maxAttempts < 1 {
		return Outcome{}, ErrLimit
	}
	if client == nil || maxBytes < 1 || maxBytes > 16*1024*1024 || len(payload) > MaxRequestBytes {
		return Outcome{}, ErrInvalid
	}
	ctx, cancel := context.WithTimeout(ctx, DefaultTimeout)
	defer cancel()
	out := Outcome{State: "exhausted"}
	for _, endpoint := range endpoints {
		if err := ctx.Err(); err != nil {
			out.State = "cancelled"
			return out, err
		}
		if out.Attempts >= maxAttempts {
			return out, ErrLimit
		}
		out.Attempts++
		started := time.Now()
		reply, err := Attempt(ctx, client, endpoint, payload, maxBytes)
		trace := AttemptTrace{Endpoint: endpoint, Status: reply.Status, ElapsedMS: time.Since(started).Milliseconds()}
		if err != nil {
			trace.Kind = "transport-error"
			if errors.Is(err, ErrLimit) {
				trace.Kind = "response-limit"
			}
			if ctx.Err() != nil {
				trace.Kind = "cancelled"
			}
			out.Trace = append(out.Trace, trace)
			if ctx.Err() != nil {
				out.State = "cancelled"
				return out, ctx.Err()
			}
			if errors.Is(err, ErrLimit) {
				out.State = "response-limit"
				return out, err
			}
			continue
		}
		out.Reply = reply
		kind, err := ClassifyStatus(reply.Status)
		trace.Kind = kind
		out.Trace = append(out.Trace, trace)
		if err != nil {
			return out, err
		}
		if kind == "success" {
			out.State = "completed"
			return out, nil
		}
		if kind == "terminal" {
			out.State = "terminal-error"
			return out, ErrInvalid
		}
	}
	return out, ErrLimit
}

