import argparse
import json
import re
from collections import Counter
from pathlib import Path

def coverage(source: str, compact: str, rare_max: int = 2) -> dict:
    if rare_max < 1:
        raise ValueError('rare_max must be positive')
    expected = Counter()
    for line in source.splitlines():
        level, message = line.split('\t', 1)
        if level not in {'DEBUG', 'INFO', 'WARN', 'ERROR'} or not message.strip():
            raise ValueError('invalid source record')
        expected[(level, re.sub(r'[0-9]+', '#', message))] += 1
    retained = set()
    represented = 0
    for line in compact.splitlines():
        row = json.loads(line)
        key = (row['level'], row['template'])
        if row.get('schemaVersion') != 1 or key not in expected or key in retained:
            raise ValueError('unknown or duplicate context group')
        if type(row['count']) is not int or row['count'] != expected[key]:
            raise ValueError('group count mismatch')
        if type(row['firstLine']) is not int or type(row['lastLine']) is not int or not 1 <= row['firstLine'] <= row['lastLine'] <= sum(expected.values()):
            raise ValueError('invalid locator')
        retained.add(key)
        represented += row['count']
    rare = {key for key, count in expected.items() if count <= rare_max}
    lost = sorted(rare - retained)
    return {'schemaVersion': 1, 'records': sum(expected.values()), 'templates': len(expected),
            'retainedTemplates': len(retained), 'representedRecords': represented,
            'rareTemplates': len(rare), 'retainedRareTemplates': len(rare & retained),
            'rareCoverage': len(rare & retained) / len(rare) if rare else 1.0,
            'lostRare': [{'level': x[0], 'template': x[1]} for x in lost]}

def main():
    p = argparse.ArgumentParser()
    p.add_argument('source'); p.add_argument('context'); p.add_argument('--out')
    a = p.parse_args()
    report = coverage(Path(a.source).read_text(), Path(a.context).read_text())
    text = json.dumps(report, indent=2)
    if a.out: Path(a.out).write_text(text + '\n')
    print(text)
if __name__ == '__main__': main()

use std::collections::{BTreeMap, BTreeSet};
#[derive(Clone, Debug, PartialEq)]
pub struct Record {
    pub line: usize,
    pub level: String,
    pub message: String,
    pub template: String,
}
#[derive(Clone, Debug, PartialEq)]
pub struct Group {
    pub level: String,
    pub template: String,
    pub count: usize,
    pub first: usize,
    pub last: usize,
    pub example: String,
}
pub fn template(s: &str) -> String {
    let mut out = String::new();
    let mut digit = false;
    for c in s.chars() {
        if c.is_ascii_digit() {
            if !digit {
                out.push('#')
            };
            digit = true
        } else {
            out.push(c);
            digit = false
        }
    }
    out
}
pub fn parse_logs(s: &str) -> Result<Vec<Record>, String> {
    if s.len() > 1_048_576 {
        return Err("input exceeds one MiB".into());
    };
    let mut out = Vec::new();
    for (i, line) in s.lines().enumerate() {
        if i >= 10_000 {
            return Err("too many records".into());
        };
        if line.len() > 4096 {
            return Err("record too long".into());
        };
        let (level, message) = line.split_once('\t').ok_or("expected LEVEL<TAB>message")?;
        if !["DEBUG", "INFO", "WARN", "ERROR"].contains(&level)
            || message.trim().is_empty()
            || message.chars().any(|c| c.is_control())
        {
            return Err("invalid level or message".into());
        };
        out.push(Record {
            line: i + 1,
            level: level.into(),
            message: message.into(),
            template: template(message),
        })
    }
    Ok(out)
}
pub fn group(records: &[Record]) -> Vec<Group> {
    let mut groups: BTreeMap<(String, String), Group> = BTreeMap::new();
    for r in records {
        let g = groups
            .entry((r.level.clone(), r.template.clone()))
            .or_insert(Group {
                level: r.level.clone(),
                template: r.template.clone(),
                count: 0,
                first: r.line,
                last: r.line,
                example: r.message.clone(),
            });
        g.count += 1;
        g.first = g.first.min(r.line);
        g.last = g.last.max(r.line)
    }
    groups.into_values().collect()
}
pub fn sample(records: &[Record], budget: usize, policy: &str) -> Result<Vec<Record>, String> {
    if policy != "uniform" && policy != "rarity" {
        return Err("unknown policy".into());
    };
    if budget == 0 || records.is_empty() {
        return Ok(vec![]);
    };
    let n = budget.min(records.len());
    if policy == "uniform" {
        return Ok((0..n)
            .map(|i| records[i * records.len() / n].clone())
            .collect());
    }
    let groups = group(records);
    let counts: BTreeMap<_, _> = groups
        .iter()
        .map(|g| ((g.level.clone(), g.template.clone()), g.count))
        .collect();
    let mut order: Vec<_> = records.iter().collect();
    order.sort_by_key(|r| (counts[&(r.level.clone(), r.template.clone())], r.line));
    let mut selected = Vec::new();
    let mut seen = BTreeSet::new();
    for r in &order {
        if seen.insert((r.level.clone(), r.template.clone())) {
            selected.push((*r).clone());
            if selected.len() == n {
                return Ok(selected);
            }
        }
    }
    for r in order {
        if !selected.iter().any(|x| x.line == r.line) {
            selected.push(r.clone());
            if selected.len() == n {
                break;
            }
        }
    }
    Ok(selected)
}
pub fn quote(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 32 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
pub fn compact(records: &[Record], selected: &[Record]) -> String {
    let keys: BTreeSet<_> = selected
        .iter()
        .map(|r| (r.level.clone(), r.template.clone()))
        .collect();
    let mut out = String::new();
    for g in group(records) {
        if keys.contains(&(g.level.clone(), g.template.clone())) {
            out.push_str(&format!("{{\"schemaVersion\":1,\"level\":{},\"template\":{},\"count\":{},\"firstLine\":{},\"lastLine\":{},\"example\":{}}}\n",quote(&g.level),quote(&g.template),g.count,g.first,g.last,quote(&g.example)))
        }
    }
    out
}
fn main() {
    let a: Vec<_> = std::env::args().collect();
    let run = || -> Result<(), String> {
        if a.len() != 5 {
            return Err("usage: log-context INPUT BUDGET uniform|rarity OUTPUT".into());
        };
        let s = std::fs::read_to_string(&a[1]).map_err(|e| e.to_string())?;
        let records = parse_logs(&s)?;
        let budget = a[2].parse::<usize>().map_err(|e| e.to_string())?;
        let selected = sample(&records, budget, &a[3])?;
        let text = compact(&records, &selected);
        std::fs::write(&a[4], &text).map_err(|e| e.to_string())?;
        println!(
            "records={} selected={} retained_templates={} output={}",
            records.len(),
            selected.len(),
            text.lines().count(),
            a[4]
        );
        Ok(())
    };
    if let Err(e) = run() {
        eprintln!("{}", e);
        std::process::exit(1)
    }
}

"""Serve a scoped MCP inventory or print a context-budgeted tool selection."""

import argparse
import json
import sys
from pathlib import Path
from registry import catalog
from discovery import discover
from protocol import serve
from rest_adapter import import_openapi

SEARCH = {
    "name": "catalog_search",
    "description": "Find tools for this inventory within an explicit serialized array budget",
    "inputSchema": {
        "type": "object",
        "properties": {
            "query": {"type": "string"},
            "max_chars": {"type": "integer", "minimum": 0},
            "k": {"type": "integer", "minimum": 0},
        },
        "required": ["query"],
        "additionalProperties": False,
    },
}


def configured_catalog(inventory):
    if not isinstance(inventory, dict):
        raise ValueError("inventory object required")
    for resource, items in inventory.items():
        if not isinstance(items, list) or any(
            not isinstance(item, dict) or not isinstance(item.get("name"), str)
            for item in items
        ):
            raise ValueError("each resource requires named records")
    tools = [tool for tool in catalog() if tool["resource"] in inventory]
    if set(inventory) - {tool["resource"] for tool in tools}:
        raise ValueError("unknown resource family")
    return [SEARCH, *tools]


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("inventory", type=Path)
    parser.add_argument("--serve", action="store_true")
    parser.add_argument("--openapi", type=Path)
    parser.add_argument(
        "--base-url", help="opt-in loopback HTTP origin; omitted means recordings only"
    )
    parser.add_argument("--query", default="pods count")
    parser.add_argument("--max-chars", type=int, default=1500)
    parser.add_argument("--limit", type=int, default=5)
    args = parser.parse_args()
    inventory = json.loads(args.inventory.read_text())
    tools = (
        [SEARCH, *import_openapi(json.loads(args.openapi.read_text()))]
        if args.openapi
        else configured_catalog(inventory)
    )
    if args.base_url:
        if not args.openapi:
            parser.error("base-url requires openapi")
        inventory["base_url"] = args.base_url
    if args.serve:
        serve(sys.stdin, sys.stdout, inventory, tools)
    else:
        result = discover(tools[1:], args.query, args.max_chars, args.limit)
        result.update(
            schema_version=1,
            full_characters=len(
                json.dumps(
                    [
                        {k: t[k] for k in ("name", "description", "inputSchema")}
                        for t in tools[1:]
                    ],
                    separators=(",", ":"),
                )
            ),
        )
        print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

// Typed stdio client for the local MCP fixture server.
// Lesson: projects/mcp-at-scale/stages/05-typed-client/docs/en.md
// Each request has a correlated response; notifications do not.
// Child process output and time are bounded independently of the server.
import { spawn } from 'node:child_process';
import { resolve, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
export interface Request { jsonrpc: '2.0'; id?: number; method: string; params?: Record<string, unknown> }
export interface Response { jsonrpc: '2.0'; id: number | null; result?: Record<string, unknown>; error?: {code: number; message: string} }
export function exchange(server: string, requests: Request[], timeout = 3000): Promise<Response[]> {
  const ids = requests.filter(r => r.id !== undefined).map(r => r.id);
  if (new Set(ids).size !== ids.length) return Promise.reject(new Error('duplicate request id'));
  return new Promise((accept, reject) => {
    const child = spawn('python3', [server], {stdio: ['pipe','pipe','pipe']});
    let output = '', error = ''; let settled = false;
    const finish = (failure?: Error, value?: Response[]) => { if (settled) return; settled=true; clearTimeout(timer); if (failure) {child.kill(); reject(failure);} else accept(value!); };
    const timer = setTimeout(() => finish(new Error('server timeout')), timeout);
    child.on('error', e => finish(e));
    child.stdin.on('error', e => finish(e));
    child.stdout.on('data', chunk => {output += chunk; if (output.length > 1_000_000) finish(new Error('response budget exceeded'));});
    child.stderr.on('data', chunk => {error=(error+chunk).slice(-4000);});
    child.on('close', code => {
      if (code) return finish(new Error(`server failed: ${error}`));
      try {
        const rows = output.trim() ? output.trim().split('\n').map(line => JSON.parse(line) as Response) : [];
        if (rows.length !== ids.length || rows.some(row => row.jsonrpc !== '2.0' || !ids.includes(row.id as number) || !('result' in row || 'error' in row)) || new Set(rows.map(row=>row.id)).size !== ids.length) throw new Error('response correlation failed');
        finish(undefined, rows);
      } catch (e) {finish(e instanceof Error ? e : new Error(String(e)));}
    });
    child.stdin.end(requests.map(request => JSON.stringify(request)).join('\n')+'\n');
  });
}
export const initialize: Request[] = [{jsonrpc:'2.0',id:1,method:'initialize',params:{protocolVersion:'2025-06-18'}},{jsonrpc:'2.0',method:'notifications/initialized'}];
if (process.argv[1] && import.meta.url===pathToFileURL(resolve(process.argv[1])).href) {
  console.log(JSON.stringify(await exchange(resolve(dirname(fileURLToPath(import.meta.url)),'protocol.py'),[...initialize,{jsonrpc:'2.0',id:2,method:'tools/call',params:{name:'pods_count',arguments:{}}}]),null,2));
}

"""Select tools under an explicit context budget.

Lesson: projects/mcp-at-scale/stages/02-discovery/docs/en.md
The implementation is original and uses explicit local data contracts.
Run its tests through scripts/project_test.py.
"""

import json
import re


def discover(tools, query, max_chars=1500, k=5):
    if max_chars < 0 or k < 0:
        raise ValueError("nonnegative limits required")
    tokens = lambda s: set(re.findall(r"[a-z0-9]+", s.lower()))
    terms = tokens(query)
    ranked = []
    for tool in tools:
        score = len(
            terms & tokens(tool["name"].replace("_", " ") + " " + tool["description"])
        )
        if score:
            ranked.append((score, tool["name"], tool))
    selected = []
    used = 0
    for score, name, tool in sorted(ranked, key=lambda r: (-r[0], r[1])):
        public = {key: tool[key] for key in ["name", "description", "inputSchema"]}
        size = len(json.dumps(selected + [public], separators=(",", ":")))
        if size > max_chars:
            continue
        selected.append(public)
        used = size
        if len(selected) >= k:
            break
    return {
        "tools": selected if k else [],
        "characters": used if k else 0,
        "catalog_size": len(tools),
    }

"""Implement initialized JSON-RPC over stdio.

Lesson: projects/mcp-at-scale/stages/03-protocol/docs/en.md
The implementation is original and uses explicit local data contracts.
Run its tests through scripts/project_test.py.
"""

import json
import sys
from registry import catalog, execute
from discovery import discover
from rest_adapter import execute_rest


def handle(request, state, inventory):
    if (
        not isinstance(request, dict)
        or request.get("jsonrpc") != "2.0"
        or not isinstance(request.get("method"), str)
    ):
        return {
            "jsonrpc": "2.0",
            "id": request.get("id") if isinstance(request, dict) else None,
            "error": {"code": -32600, "message": "Invalid Request"},
        }
    id = request.get("id")
    method = request["method"]
    params = request.get("params", {})

    def result(value):
        return {"jsonrpc": "2.0", "id": id, "result": value}

    def error(code, message):
        return {"jsonrpc": "2.0", "id": id, "error": {"code": code, "message": message}}

    if "id" not in request:
        if method == "notifications/initialized" and state.get("negotiated"):
            state["initialized"] = True
        return None
    if not isinstance(params, dict):
        return error(-32602, "Invalid params")
    if method == "initialize":
        if params.get("protocolVersion") not in ["2025-06-18", "2025-11-25"]:
            return error(-32602, "Unsupported protocol version")
        state["negotiated"] = True
        return result(
            {
                "protocolVersion": params["protocolVersion"],
                "capabilities": {"tools": {}},
                "serverInfo": {"name": "local-inventory", "version": "1.0"},
            }
        )
    if not state.get("initialized"):
        return error(-32002, "Initialize before using tools")
    tools = state.get("catalog", catalog())
    if method == "tools/list":
        try:
            offset = int(params.get("cursor", "0"))
        except (ValueError, TypeError):
            return error(-32602, "Invalid cursor")
        if offset < 0 or offset > len(tools):
            return error(-32602, "Invalid cursor")
        page = [
            {key: t[key] for key in ["name", "description", "inputSchema"]}
            for t in tools[offset : offset + 32]
        ]
        payload = {"tools": page}
        if offset + 32 < len(tools):
            payload["nextCursor"] = str(offset + 32)
        return result(payload)
    if method == "tools/call":
        tool = next((t for t in tools if t["name"] == params.get("name")), None)
        if tool is None:
            return error(-32602, "Unknown tool")
        try:
            if tool["name"] == "catalog_search":
                args = params.get("arguments", {})
                if (
                    not isinstance(args, dict)
                    or set(args) - {"query", "max_chars", "k"}
                    or not isinstance(args.get("query"), str)
                    or any(
                        type(args.get(key, default)) is not int
                        for key, default in [("max_chars", 1500), ("k", 5)]
                    )
                ):
                    raise ValueError("invalid discovery arguments")
                value = discover(
                    [t for t in tools if t["name"] != "catalog_search"],
                    args["query"],
                    args.get("max_chars", 1500),
                    args.get("k", 5),
                )
            elif "rest" in tool:
                value = execute_rest(
                    tool,
                    params.get("arguments", {}),
                    inventory.get("recordings"),
                    inventory.get("base_url"),
                )
            else:
                value = execute(tool, params.get("arguments", {}), inventory)
        except ValueError as exc:
            return result(
                {"content": [{"type": "text", "text": str(exc)}], "isError": True}
            )
        return result(
            {"content": [{"type": "text", "text": json.dumps(value)}], "isError": False}
        )
    return error(-32601, "Method not found")


def serve(lines, output, inventory, tools=None):
    state = {} if tools is None else {"catalog": tools}
    for line in lines:
        try:
            request = json.loads(line)
        except json.JSONDecodeError:
            response = {
                "jsonrpc": "2.0",
                "id": None,
                "error": {"code": -32700, "message": "Parse error"},
            }
        else:
            response = handle(request, state, inventory)
        if response is not None:
            output.write(json.dumps(response) + "\n")
            output.flush()


if __name__ == "__main__":
    serve(
        sys.stdin,
        sys.stdout,
        {
            "pods": [
                {"name": "worker-1", "phase": "Running"},
                {"name": "worker-2", "phase": "Pending"},
            ]
        },
    )

"""Build a catalog of 250 read-only tools.

Lesson: projects/mcp-at-scale/stages/01-registry/docs/en.md
The implementation is original and uses explicit local data contracts.
Run its tests through scripts/project_test.py.
"""

RESOURCES = (
    "pods jobs nodes services routes volumes events queues topics messages buckets objects files directories users groups roles policies tokens sessions agents tasks runs spans traces metrics logs alerts dashboards reports notes documents chunks embeddings indexes models prompts skills hooks workflows schedules workers functions triggers deployments releases images artifacts registries clusters"
).split()
OPERATIONS = ("list", "get", "count", "search", "describe")


def catalog():
    rows = []
    for resource in RESOURCES:
        for operation in OPERATIONS:
            properties = (
                {"name": {"type": "string"}}
                if operation == "get"
                else {"query": {"type": "string"}}
                if operation == "search"
                else {}
            )
            rows.append(
                {
                    "name": resource + "_" + operation,
                    "description": f"{operation} {resource} in the local fixture inventory",
                    "inputSchema": {
                        "type": "object",
                        "properties": properties,
                        "required": list(properties),
                        "additionalProperties": False,
                    },
                    "resource": resource,
                    "operation": operation,
                }
            )
    return rows


def execute(tool, arguments, inventory):
    schema = tool["inputSchema"]
    required = schema["required"]
    if (
        not isinstance(arguments, dict)
        or set(arguments) != set(required)
        or any(not isinstance(v, str) for v in arguments.values())
    ):
        raise ValueError("arguments do not match schema")
    items = inventory.get(tool["resource"], [])
    op = tool["operation"]
    if op == "list":
        return items
    if op == "count":
        return len(items)
    if op == "describe":
        return {"resource": tool["resource"], "operations": list(OPERATIONS)}
    if op == "search":
        return [
            item
            for item in items
            if arguments["query"].casefold() in item["name"].casefold()
        ]
    if op == "get":
        return next((item for item in items if item["name"] == arguments["name"]), None)
    raise ValueError("unknown operation")

"""Import a narrow OpenAPI GET surface; preserve schema provenance and explicit recordings."""

import hashlib
import json
import re
import urllib.parse
import urllib.request


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise ValueError("REST redirects are not permitted")


def import_openapi(spec):
    if not isinstance(spec, dict) or not str(spec.get("openapi", "")).startswith("3."):
        raise ValueError("OpenAPI3 object required")
    fingerprint = hashlib.sha256(
        json.dumps(spec, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    tools, names = [], set()
    for path, item in spec.get("paths", {}).items():
        if not path.startswith("/") or path.startswith("//") or ".." in path.split("/"):
            raise ValueError("unsafe API path")
        operation = item.get("get")
        if operation is None:
            continue
        name = operation.get("operationId")
        if (
            not isinstance(name, str)
            or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]{0,63}", name)
            or name in names
        ):
            raise ValueError("unique safe operationId required")
        names.add(name)
        properties, required, parameters = {}, [], []
        for parameter in item.get("parameters", []) + operation.get("parameters", []):
            key = parameter.get("name")
            kind = parameter.get("schema", {}).get("type")
            if (
                parameter.get("in") not in ["path", "query"]
                or kind not in ["string", "integer", "boolean"]
                or not isinstance(key, str)
                or key in properties
            ):
                raise ValueError(
                    "only unique primitive path/query parameters supported"
                )
            properties[key] = {"type": kind}
            parameters.append({"name": key, "in": parameter["in"]})
            if parameter.get("required") or parameter["in"] == "path":
                required.append(key)
        if set(re.findall(r"{([^}]+)}", path)) != {
            p["name"] for p in parameters if p["in"] == "path"
        }:
            raise ValueError("path parameters must match placeholders")
        tools.append(
            {
                "name": name,
                "description": operation.get("summary", "Read " + path),
                "inputSchema": {
                    "type": "object",
                    "properties": properties,
                    "required": required,
                    "additionalProperties": False,
                },
                "rest": {
                    "path": path,
                    "parameters": parameters,
                    "source_sha256": fingerprint,
                },
            }
        )
    return tools


def execute_rest(tool, arguments, recordings=None, base_url=None):
    schema = tool["inputSchema"]
    if (
        not isinstance(arguments, dict)
        or set(arguments) - set(schema["properties"])
        or set(schema["required"]) - set(arguments)
    ):
        raise ValueError("arguments do not match imported schema")
    for key, value in arguments.items():
        kind = schema["properties"][key]["type"]
        if (
            (kind == "string" and not isinstance(value, str))
            or (kind == "integer" and type(value) is not int)
            or (kind == "boolean" and type(value) is not bool)
        ):
            raise ValueError("argument type mismatch")
    if base_url is None:
        if recordings is None or tool["name"] not in recordings:
            raise ValueError("recording missing for operation")
        recording = recordings[tool["name"]]
        if recording.get("arguments") != arguments:
            raise ValueError("no matching recording for arguments")
        return {
            "mode": "recording",
            "source_sha256": tool["rest"]["source_sha256"],
            "value": recording["value"],
        }
    base = urllib.parse.urlparse(base_url)
    if (
        base.scheme != "http"
        or base.hostname not in ["127.0.0.1", "localhost", "::1"]
        or base.username
        or base.password
        or base.query
        or base.fragment
    ):
        raise ValueError("live REST lab requires a loopback HTTP origin")
    path = tool["rest"]["path"]
    query = {}
    for parameter in tool["rest"]["parameters"]:
        key = parameter["name"]
        if key not in arguments:
            continue
        if parameter["in"] == "path":
            path = path.replace(
                "{" + key + "}", urllib.parse.quote(str(arguments[key]), safe="")
            )
        else:
            query[key] = (
                str(arguments[key]).lower()
                if type(arguments[key]) is bool
                else str(arguments[key])
            )
    url = (
        base_url.rstrip("/")
        + path
        + ("?" + urllib.parse.urlencode(query) if query else "")
    )
    with urllib.request.build_opener(NoRedirect).open(
        urllib.request.Request(
            url, method="GET", headers={"Accept": "application/json"}
        ),
        timeout=5,
    ) as response:
        content = response.read(1000001)
        if len(content) > 1000000:
            raise ValueError("REST response too large")
        value = json.loads(content)
    return {
        "mode": "live-loopback-get",
        "source_sha256": tool["rest"]["source_sha256"],
        "value": value,
    }

