def family(name: str) -> str:
    for table in (REG64, REG32, REG16, REG8):
        if name in table:
            return REG64[table.index(name)]
    return name


def local_name(disp: int) -> str:
    return f"local_{-disp:x}" if disp < 0 else f"arg_{disp:x}"


@dataclass
class LiftContext:
    elf: ElfObject
    tables: dict[int, JumpTable] = field(default_factory=dict)
    signatures: dict[str, tuple[tuple[int, ...], int]] = field(default_factory=dict)
    frame: bool = False
    section: str = ".text"
    signedness: dict[str, list[str]] = field(default_factory=dict)
    notes: list[str] = field(default_factory=list)

    def evidence(self, kind: str, insn: Instruction) -> None:
        self.signedness.setdefault(kind, []).append(f"0x{insn.address:x} {insn.text.replace(chr(9), ' ')}")


def lift_instruction(insn: Instruction, ctx: LiftContext) -> list[Any]:
    op, ops = insn.op, insn.operands

    def address_of(mem: Mem) -> Any:
        if mem.rip:
            relocation = ctx.elf.relocation_at(ctx.section, insn.address + (mem.disp_offset or 0))
            if relocation is None:
                return Const(insn.end + mem.disp, 64)
            target = relocation_target(relocation, insn.end)
            return Symbolic(target.section, target.offset)
        expr: Any = Var(mem.base, 64) if mem.base else None
        if mem.index:
            scaled: Any = Var(mem.index, 64)
            if mem.scale != 1:
                scaled = Bin("*", scaled, Const(mem.scale, 64), 64)
            expr = scaled if expr is None else Bin("+", expr, scaled, 64)
        if mem.disp or expr is None:
            disp = Const(mem.disp, 64)
            expr = disp if expr is None else Bin("+", expr, disp, 64)
        return expr

    def is_slot(mem: Mem) -> bool:
        return ctx.frame and mem.base == "rbp" and mem.index is None and not mem.rip

    def read(operand: Any, width: int | None = None) -> Any:
        if isinstance(operand, IndirectOperand):
            operand = operand.inner
        w = width or operand.width
        if isinstance(operand, Reg):
            return Var(family(operand.name), w)
        if isinstance(operand, Imm):
            return Const(operand.value, w)
        if isinstance(operand, Mem):
            if is_slot(operand):
                return Var(local_name(operand.disp), w)
            return Load(address_of(operand), w)
        raise LiftError(f"0x{insn.address:x}: cannot read operand {operand!r}")

    def write(operand: Any, expr: Any) -> Any:
        if isinstance(operand, Reg):
            return Assign(Var(family(operand.name), operand.width), expr)
        if isinstance(operand, Mem):
            if is_slot(operand):
                return Assign(Var(local_name(operand.disp), operand.width), expr)
            return Store(address_of(operand), expr, operand.width)
        raise LiftError(f"0x{insn.address:x}: cannot write operand {operand!r}")

    def same_register(a: Any, b: Any) -> bool:
        return isinstance(a, Reg) and isinstance(b, Reg) and family(a.name) == family(b.name)

    def is_rsp(operand: Any) -> bool:
        return isinstance(operand, Reg) and operand.name == "rsp"

    if op in ("push", "pop", "nop"):
        return []
    if op == "mov" and same_register(ops[1], Reg("rbp", 64)) and same_register(ops[0], Reg("rsp", 64)):
        ctx.frame = True
        return []
    if op in ("add", "sub") and is_rsp(ops[1]):
        return []
    captured: list[Any] = []
    for table in ctx.tables.values():
        if table.load_instruction == insn.address and table.is_jump_table:
            captured.append(Assign(Var("switch_index", 64), Var(table.index_register, 64)))
    if op == "mov":
        return captured + [write(ops[1], read(ops[0]))]
    if op == "movsxd":
        ctx.evidence("signed", insn)
        return captured + [write(ops[1], Cast("sext", read(ops[0], 32), 64))]
    if op == "movsx":
        ctx.evidence("signed", insn)
        return [write(ops[1], Cast("sext", read(ops[0], insn.source_width or 8), insn.width))]
    if op == "movzx":
        ctx.evidence("unsigned", insn)
        return [write(ops[1], Cast("zext", read(ops[0], insn.source_width or 8), insn.width))]
    if op == "lea":
        expr = address_of(ops[0])
        if ops[1].width == 32:
            expr = Cast("trunc", expr, 32)
        return [write(ops[1], expr)]
    if op in ("add", "sub", "and", "or", "xor"):
        if op in ("sub", "xor") and same_register(ops[0], ops[1]):
            return [write(ops[1], Const(0, ops[1].width))]
        source, destination = read(ops[0]), read(ops[1])
        symbol = {"add": "+", "sub": "-", "and": "&", "or": "|", "xor": "^"}[op]
        kind = "cmp" if op == "sub" else op
        return [Assign(FLAGS, Flags(kind, destination, source, insn.width)), write(ops[1], Bin(symbol, destination, source, insn.width))]
    if op in ("inc", "dec"):
        value = read(ops[0])
        one = Const(1, insn.width)
        return [Assign(FLAGS, Flags(op, value, one, insn.width)), write(ops[0], Bin("+" if op == "inc" else "-", value, one, insn.width))]
    if op == "neg":
        value = read(ops[0])
        return [Assign(FLAGS, Flags("cmp", Const(0, insn.width), value, insn.width)), write(ops[0], Bin("-", Const(0, insn.width), value, insn.width))]
    if op == "not":
        return [write(ops[0], Bin("^", read(ops[0]), Const(-1, insn.width), insn.width))]
    if op in ("cmp", "test"):
        return [Assign(FLAGS, Flags(op, read(ops[1]), read(ops[0]), insn.width))]
    if op == "imul":
        if len(ops) == 3:
            return [write(ops[2], Bin("*", read(ops[1]), read(ops[0]), insn.width))]
        return [write(ops[1], Bin("*", read(ops[1]), read(ops[0]), insn.width))]
    if op in ("shl", "shr", "sar"):
        symbol = {"shl": "<<", "shr": ">>u", "sar": ">>s"}[op]
        if op != "shl":
            ctx.evidence("signed" if op == "sar" else "unsigned", insn)
        return [write(ops[1], Bin(symbol, read(ops[1]), Const(ops[0].value, 8), insn.width))]
    if op == "cdq":
        ctx.evidence("signed", insn)
        return [Assign(Var("rdx", insn.width), SignFill(Var("rax", insn.width), insn.width))]
    if op in ("idiv", "div"):
        w = insn.width
        signed = op == "idiv"
        ctx.evidence("signed" if signed else "unsigned", insn)
        dividend = Var("dividend", 2 * w)
        divisor = read(ops[0])
        quotient, remainder = ("/", "%") if signed else ("/u", "%u")
        return [
            Assign(dividend, Concat(Var("rdx", w), Var("rax", w), 2 * w)),
            Assign(Var("rax", w), Bin(quotient, dividend, divisor, w)),
            Assign(Var("rdx", w), Bin(remainder, dividend, divisor, w)),
        ]
    if op == "jcc":
        if insn.cc in SIGNED_CONDITIONS:
            ctx.evidence("signed", insn)
        elif insn.cc in UNSIGNED_CONDITIONS:
            ctx.evidence("unsigned", insn)
        if insn.cc not in COND_OPS:
            raise LiftError(f"0x{insn.address:x}: no lifting rule for condition {insn.cc}")
        return [Branch(Cond(insn.cc, FLAGS), insn.target, insn.end)]
    if op == "jmp":
        if insn.flow == "jump":
            return [Jump(insn.target)]
        table = ctx.tables.get(insn.address)
        index = Var("switch_index", 64) if table else None
        return [IndirectJump(read(ops[0], 64), table, index)]
    if op == "call":
        relocation = ctx.elf.relocation_at(ctx.section, insn.address + (insn.immediate_offset or 1))
        if insn.flow == "indirect-call":
            name = "indirect_call"
        else:
            name = relocation.symbol_name if relocation else f"sub_{insn.target:x}"
        param_widths, result_width = ctx.signatures.get(name, ((), 32))
        if name not in ctx.signatures:
            ctx.notes.append(f"call to {name} at 0x{insn.address:x} has no recovered signature; arguments are unknown")
        args = tuple(Var(ARG_REGISTERS[i], w) for i, w in enumerate(param_widths))
        return [Assign(Var("rax", result_width), CallExpr(name, args, result_width))]
    if op == "ret":
        return [Return(Var("rax", 0))]
    raise LiftError(f"0x{insn.address:x}: no lifting rule for {insn.text}")


def children(expr: Any) -> list[Any]:
    if isinstance(expr, (Bin, Flags)):
        return [expr.left, expr.right]
    if isinstance(expr, (Cast, SignFill)):
        return [expr.expr]
    if isinstance(expr, Load):
        return [expr.addr]
    if isinstance(expr, Index):
        return [expr.base, expr.index]
    if isinstance(expr, Field):
        return [expr.base]
    if isinstance(expr, Cond):
        return [expr.flags]
    if isinstance(expr, Concat):
        return [expr.high, expr.low]
    if isinstance(expr, CallExpr):
        return list(expr.args)
    return []


def rebuild(expr: Any, kids: list[Any]) -> Any:
    if isinstance(expr, (Bin, Flags)):
        return replace(expr, left=kids[0], right=kids[1])
    if isinstance(expr, (Cast, SignFill)):
        return replace(expr, expr=kids[0])
    if isinstance(expr, Load):
        return replace(expr, addr=kids[0])
    if isinstance(expr, Index):
        return replace(expr, base=kids[0], index=kids[1])
    if isinstance(expr, Field):
        return replace(expr, base=kids[0])
    if isinstance(expr, Cond):
        return replace(expr, flags=kids[0])
    if isinstance(expr, Concat):
        return replace(expr, high=kids[0], low=kids[1])
    if isinstance(expr, CallExpr):
        return replace(expr, args=tuple(kids))
    return expr


def rewrite(expr: Any, fn) -> Any:
    kids = [rewrite(k, fn) for k in children(expr)]
    return fn(rebuild(expr, kids))


def iter_nodes(expr: Any):
    yield expr
    for kid in children(expr):
        yield from iter_nodes(kid)


def variables(expr: Any) -> list[Var]:
    return [node for node in iter_nodes(expr) if isinstance(node, Var)]


def stmt_exprs(stmt: Any) -> list[Any]:
    if isinstance(stmt, Assign):
        return [stmt.src]
    if isinstance(stmt, Store):
        return [stmt.addr, stmt.value]
    if isinstance(stmt, Branch):
        return [stmt.cond]
    if isinstance(stmt, IndirectJump):
        return [stmt.index] if stmt.table is not None and stmt.index is not None else [stmt.target]
    if isinstance(stmt, Return):
        return [stmt.value]
    return []


def map_stmt(stmt: Any, fn) -> Any:
    if isinstance(stmt, Assign):
        stmt.src = fn(stmt.src)
    elif isinstance(stmt, Store):
        stmt.addr, stmt.value = fn(stmt.addr), fn(stmt.value)
        if stmt.place is not None:
            stmt.place = fn(stmt.place)
    elif isinstance(stmt, Branch):
        stmt.cond = fn(stmt.cond)
    elif isinstance(stmt, IndirectJump):
        stmt.target = fn(stmt.target)
        if stmt.index is not None:
            stmt.index = fn(stmt.index)
    elif isinstance(stmt, Return):
        stmt.value = fn(stmt.value)
    return stmt


def width_of(expr: Any) -> int:
    return getattr(expr, "width", 32)


def lift_function(elf: ElfObject, graph: FunctionGraph, signatures: dict[str, tuple[tuple[int, ...], int]] | None = None) -> Function:
    cfg = graph.cfg
    reachable = cfg.reachable()
    blocks: dict[int, IRBlock] = {}
    for start in sorted(cfg.blocks):
        if start in reachable:
            block = cfg.blocks[start]
            blocks[start] = IRBlock(start, list(block.instructions), [], [t for t in cfg.successors(start) if t in reachable], [p for p in cfg.predecessors(start) if p in reachable])
    fn = Function(graph.name, graph.start, blocks, graph)
    ctx = LiftContext(elf, dict(graph.descent.tables), signatures or {})
    for block in fn.ordered_blocks():
        for insn in block.instructions:
            block.stmts.extend(lift_instruction(insn, ctx))
    fn.frame_pointer = ctx.frame
    fn.signedness = ctx.signedness
    fn.notes.extend(ctx.notes)
    dropped = sorted(b for b in cfg.blocks if b not in reachable)
    if dropped:
        fn.notes.append(f"{len(dropped)} block(s) at {', '.join(f'0x{b:x}' for b in dropped)} are unreachable from the entry and were not lifted")
    for address in cfg.unresolved:
        fn.notes.append(f"indirect jump at 0x{address:x} has no recovered table; its targets are unknown")
    fn.idom = cfg.dominators()
    return fn


def const_text(value: int) -> str:
    if abs(value) >= 0x10000:
        return f"-0x{-value:x}" if value < 0 else f"0x{value:x}"
    return str(value)


class IrPrinter:

    def __init__(self, fn: Function, versions: bool) -> None:
        self.fn = fn
        self.versions = versions

    def var(self, v: Var) -> str:
        if v.name in REG64:
            width = v.width or self.fn.def_width.get((v.name, v.version), 64)
            index = REG64.index(v.name)
            name = {64: REG64, 32: REG32, 16: REG16, 8: REG8}.get(width, REG64)[index]
        else:
            name = v.name
        return f"{name}_{v.version}" if self.versions and v.version >= 0 else name

    def expr(self, e: Any) -> str:
        if isinstance(e, Const):
            return const_text(e.value)
        if isinstance(e, Var):
            return self.var(e)
        if isinstance(e, Bin):
            return f"{self.expr(e.left)} {e.op} {self.expr(e.right)}"
        if isinstance(e, Cast):
            return f"{e.kind}{e.width}({self.expr(e.expr)})"
        if isinstance(e, Load):
            return f"load{e.width}({self.expr(e.addr)})"
        if isinstance(e, Index):
            return f"{self.expr(e.base)}[{self.expr(e.index)}]"
        if isinstance(e, Field):
            return f"{self.expr(e.base)}->field_{e.offset:x}"
        if isinstance(e, Flags):
            return f"{e.kind}({self.expr(e.left)}, {self.expr(e.right)})"
        if isinstance(e, Cond):
            return f"j{e.cc}({self.expr(e.flags)})"
        if isinstance(e, Concat):
            return f"{self.expr(e.high)}:{self.expr(e.low)}"
        if isinstance(e, SignFill):
            return f"signfill({self.expr(e.expr)})"
        if isinstance(e, Symbolic):
            return f"&{e.section}+0x{e.offset:x}"
        if isinstance(e, CallExpr):
            return f"call {e.name}({', '.join(self.expr(a) for a in e.args)})"
        raise TypeError(type(e))

    def stmt(self, s: Any) -> str:
        if isinstance(s, Assign):
            return f"{self.var(s.dst)} = {self.expr(s.src)}"
        if isinstance(s, Phi):
            inner = ", ".join(f"0x{p:x}: {self.var(v)}" for p, v in sorted(s.sources.items()))
            return f"{self.var(s.dst)} = phi({inner})"
        if isinstance(s, Store):
            return f"store{s.width}({self.expr(s.addr)}) = {self.expr(s.value)}"
        if isinstance(s, Branch):
            return f"if {self.expr(s.cond)} goto 0x{s.target:x} else goto 0x{s.fallthrough:x}"
        if isinstance(s, Jump):
            return f"goto 0x{s.target:x}"
        if isinstance(s, IndirectJump):
            if s.table is not None:
                return f"switch {self.expr(s.index)} via {s.table.section}+0x{s.table.offset:x}"
            return f"goto *{self.expr(s.target)}"
        if isinstance(s, Return):
            return f"return {self.expr(s.value)}"
        raise TypeError(type(s))

    def dump(self) -> str:
        lines = []
        for block in self.fn.ordered_blocks():
            succs = ", ".join(f"0x{s:x}" for s in block.succs) or "exit"
            lines.append(f"block 0x{block.start:x} -> {succs}")
            for stmt in block.stmts:
                lines.append(f"  {self.stmt(stmt)}")
        return "\n".join(lines)

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from .ir import (
    COND_OPS,
    Assign,
    Bin,
    CallExpr,
    Cast,
    Concat,
    Cond,
    Const,
    Field,
    Flags,
    Function,
    Index,
    Load,
    Phi,
    SignFill,
    Store,
    Symbolic,
    Var,
    iter_nodes,
    map_stmt,
    rewrite,
    stmt_exprs,
    variables,
)

INT_MIN = -(2**31)
INT_MAX = 2**31 - 1


def c_div(dividend: int, divisor: int) -> int:
    quotient = abs(dividend) // abs(divisor)
    return -quotient if (dividend < 0) != (divisor < 0) else quotient


def truncate(value: int, width: int) -> int:
    value &= (1 << width) - 1
    return value - (1 << width) if width and value >> (width - 1) else value


def magic_divisor(multiplier: int, shift: int) -> int | None:
    if multiplier <= 0 or shift < 32 or shift > 63:
        return None
    power = 1 << shift
    for d in (power // multiplier, power // multiplier + 1):
        if d > 1 and multiplier == -(-power // d) and multiplier * d - power <= power >> 31:
            return d
    return None


def division_identity_holds(multiplier: int, shift: int, divisor: int, samples: list[int] | None = None) -> bool:
    values = samples or list(range(-40, 41)) + [INT_MIN, INT_MIN + 1, INT_MAX - 1, INT_MAX, 2**30, -(2**30), 123456789, -123456789]
    for x in values:
        product = truncate(x * multiplier, 64)
        quotient = truncate(product >> shift, 32) + ((product >> 63) & 1)
        if truncate(quotient, 32) != c_div(x, divisor):
            return False
    return True


@dataclass
class OptimizeReport:
    rounds: int = 0
    removed: int = 0
    substituted: int = 0
    copies: int = 0
    merged_phis: int = 0
    divisions: list[dict[str, int]] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {"rounds": self.rounds, "removed": self.removed, "substituted": self.substituted, "copies": self.copies, "mergedPhis": self.merged_phis, "divisions": list(self.divisions)}


def place_of(addr: Any, width: int) -> Any:
    if isinstance(addr, Bin) and addr.op == "+":
        for base, offset in ((addr.left, addr.right), (addr.right, addr.left)):
            scaled = isinstance(offset, Bin) and offset.op == "*" and isinstance(offset.right, Const)
            if scaled and offset.right.value * 8 == width and isinstance(base, (Var, Symbolic)):
                return Index(base, offset.left, width)
        if isinstance(addr.left, Var) and isinstance(addr.right, Const) and addr.left.width == 64 and 0 <= addr.right.value < 4096:
            return Field(addr.left, addr.right.value, width)
    if isinstance(addr, Var) and addr.width == 64:
        return Field(addr, 0, width)
    return None


COMMUTATIVE = {"+", "*", "&", "|", "^"}


def definition_order(fn: Function) -> dict[tuple[str, int], int]:
    from .ir import ARG_REGISTERS

    order: dict[tuple[str, int], int] = {}
    for position, stmt in enumerate(fn.statements()):
        if isinstance(stmt, (Assign, Phi)):
            order[stmt.dst.key] = position
        for expr in stmt_exprs(stmt):
            for var in variables(expr):
                if var.version == 0 and var.key not in order:
                    order[var.key] = -100 + (ARG_REGISTERS.index(var.name) if var.name in ARG_REGISTERS else 50)
    return order


def make_simplifier(defs: dict[tuple[str, int], Any], recognize_division: bool, report: OptimizeReport | None = None, order: dict[tuple[str, int], int] | None = None):
    order = order or {}

    def resolve(expr: Any) -> Any:
        seen = 0
        while isinstance(expr, Var) and expr.key in defs and seen < 64:
            expr = defs[expr.key]
            seen += 1
        return expr

    def strip_trunc(expr: Any) -> Any:
        return expr.expr if isinstance(expr, Cast) and expr.kind == "trunc" else expr

    def division_pattern(expr: Any) -> Any:
        if not recognize_division or not isinstance(expr, Bin) or expr.op != "+" or expr.width != 32:
            return None
        parts = [resolve(strip_trunc(expr.left)), resolve(strip_trunc(expr.right))]
        for quotient, sign in (parts, parts[::-1]):
            if not (isinstance(quotient, Bin) and quotient.op in (">>s", ">>u") and isinstance(quotient.right, Const)):
                continue
            shift = quotient.right.value
            if quotient.op == ">>u" and shift != 32:
                continue
            if not (isinstance(sign, Bin) and sign.op == ">>u" and isinstance(sign.right, Const) and sign.right.value == 63):
                continue
            product_a, product_b = resolve(quotient.left), resolve(sign.left)
            if product_a != product_b or not (isinstance(product_a, Bin) and product_a.op == "*"):
                continue
            operand, multiplier = product_a.left, product_a.right
            if isinstance(operand, Const):
                operand, multiplier = multiplier, operand
            if not (isinstance(multiplier, Const) and isinstance(operand, Cast) and operand.kind == "sext"):
                continue
            divisor = magic_divisor(multiplier.value, shift)
            if divisor is None or not division_identity_holds(multiplier.value, shift, divisor):
                continue
            if report is not None:
                record = {"multiplier": multiplier.value, "shift": shift, "divisor": divisor}
                if record not in report.divisions:
                    report.divisions.append(record)
            return Bin("/", operand.expr, Const(divisor, 32), 32)
        return None

    def fold_constants(expr: Bin) -> Any:
        left, right = expr.left, expr.right
        if isinstance(left, Const) and isinstance(right, Const):
            a, b = left.value, right.value
            table = {"+": a + b, "-": a - b, "*": a * b, "&": a & b, "|": a | b, "^": a ^ b, "<<": a << b}
            if expr.op in table:
                return Const(truncate(table[expr.op], expr.width), expr.width)
        if expr.op in ("+", "-") and isinstance(right, Const) and right.value == 0:
            return left
        if expr.op == "*" and isinstance(right, Const) and right.value == 1:
            return left
        return expr

    def simplify(expr: Any) -> Any:
        if isinstance(expr, Cond) and isinstance(expr.flags, Flags):
            flags, op = expr.flags, COND_OPS[expr.cc]
            if flags.kind == "cmp":
                return Bin(op, flags.left, flags.right, 32)
            if flags.kind == "test":
                if flags.left == flags.right:
                    return Bin(op, flags.left, Const(0, flags.width), 32)
                return Bin(op, Bin("&", flags.left, flags.right, flags.width), Const(0, flags.width), 32)
            if flags.kind in ("add", "inc", "dec", "and", "or", "xor") and expr.cc in ("e", "ne", "s", "ns", "l", "ge", "le", "g"):
                symbol = {"add": "+", "inc": "+", "dec": "-", "and": "&", "or": "|", "xor": "^"}[flags.kind]
                return Bin(op, Bin(symbol, flags.left, flags.right, flags.width), Const(0, flags.width), 32)
        if isinstance(expr, Bin):
            expr = fold_constants(expr)
        if isinstance(expr, Bin) and expr.op in COMMUTATIVE and isinstance(expr.left, Var) and isinstance(expr.right, Var):
            if order.get(expr.right.key, 0) < order.get(expr.left.key, 0):
                expr = Bin(expr.op, expr.right, expr.left, expr.width)
        if isinstance(expr, Bin) and expr.op == "+" and isinstance(expr.right, Const) and expr.right.value < 0:
            return Bin("-", expr.left, Const(-expr.right.value, expr.right.width), expr.width)
        if isinstance(expr, Cast) and isinstance(expr.expr, Const):
            value = expr.expr.value
            if expr.kind == "zext":
                return Const(value & ((1 << expr.expr.width) - 1), expr.width)
            return Const(truncate(value, expr.width), expr.width)
        if isinstance(expr, Cast) and expr.kind == "trunc":
            inner = expr.expr
            if isinstance(inner, Cast) and inner.kind in ("zext", "sext") and inner.expr.width == expr.width:
                return inner.expr
            if isinstance(inner, Bin) and inner.op in ("+", "-", "*") and inner.width > expr.width:
                left = simplify(Cast("trunc", inner.left, expr.width))
                right = simplify(Cast("trunc", inner.right, expr.width))
                return simplify(Bin(inner.op, left, right, expr.width))
        if isinstance(expr, Concat) and isinstance(expr.high, SignFill) and expr.high.expr == expr.low:
            return expr.low
        if isinstance(expr, Load):
            place = place_of(expr.addr, expr.width)
            if place is not None:
                return place
        folded = division_pattern(expr)
        if folded is not None:
            return folded
        return expr

    return simplify


def count_uses(fn: Function) -> dict[tuple[str, int], list[tuple[int, Any]]]:
    uses: dict[tuple[str, int], list[tuple[int, Any]]] = {}
    for block in fn.blocks.values():
        for stmt in block.stmts:
            if isinstance(stmt, Phi):
                for src in stmt.sources.values():
                    uses.setdefault(src.key, []).append((block.start, stmt))
                continue
            for expr in stmt_exprs(stmt):
                for var in variables(expr):
                    uses.setdefault(var.key, []).append((block.start, stmt))
    return uses


def has_call(expr: Any) -> bool:
    return any(isinstance(node, CallExpr) for node in iter_nodes(expr))


def contains_load(expr: Any) -> bool:
    return any(isinstance(node, (Load, Index, Field)) for node in iter_nodes(expr))


def stmt_has_side_effect(stmt: Any) -> bool:
    return isinstance(stmt, Store) or any(has_call(e) for e in stmt_exprs(stmt))


def remove_dead_code(fn: Function, uses: dict[tuple[str, int], list[tuple[int, Any]]]) -> int:
    removed = 0
    for block in fn.blocks.values():
        kept = []
        for stmt in block.stmts:
            dead = isinstance(stmt, (Assign, Phi)) and stmt.dst.key not in uses
            if dead and not (isinstance(stmt, Assign) and has_call(stmt.src)):
                removed += 1
                continue
            kept.append(stmt)
        block.stmts = kept
    return removed


def propagate_copies(fn: Function) -> int:
    replacements: dict[tuple[str, int], Any] = {}
    for stmt in fn.statements():
        if isinstance(stmt, Assign):
            if isinstance(stmt.src, Const) or (isinstance(stmt.src, Var) and stmt.src.width == stmt.dst.width and stmt.src.key not in replacements):
                replacements[stmt.dst.key] = stmt.src
    if not replacements:
        return 0
    for key, value in list(replacements.items()):
        seen = {key}
        while isinstance(value, Var) and value.key in replacements and value.key not in seen:
            seen.add(value.key)
            value = replacements[value.key]
        replacements[key] = value
    changed = 0

    def swap(expr: Any) -> Any:
        nonlocal changed
        if isinstance(expr, Var) and expr.key in replacements:
            changed += 1
            return replacements[expr.key]
        return expr

    for stmt in fn.statements():
        if not isinstance(stmt, Phi):
            map_stmt(stmt, lambda e: rewrite(e, swap))
    return changed


def substitute_once(fn: Function, uses: dict[tuple[str, int], list[tuple[int, Any]]]) -> bool:
    for block in fn.blocks.values():
        for position, stmt in enumerate(block.stmts):
            if not isinstance(stmt, Assign) or has_call(stmt.src):
                continue
            users = uses.get(stmt.dst.key, [])
            if len(users) != 1 or isinstance(users[0][1], Phi):
                continue
            user_block, user = users[0]
            later = block.stmts[position + 1 :]
            same_block = user_block == block.start and any(user is s for s in later)
            if not (same_block or isinstance(stmt.src, Symbolic)):
                continue
            if contains_load(stmt.src):
                between = later[: next(i for i, s in enumerate(later) if s is user)]
                if any(stmt_has_side_effect(s) for s in between):
                    continue
            target = stmt.dst
            map_stmt(user, lambda e: rewrite(e, lambda x: stmt.src if x == target else x))
            block.stmts.remove(stmt)
            return True
    return False


def merge_congruent_phis(fn: Function) -> int:
    defs = {s.dst.key: s.src for s in fn.statements() if isinstance(s, Assign)}

    def value(var: Var) -> Any:
        seen: set[tuple[str, int]] = set()
        current: Any = var
        while isinstance(current, Var) and current.key in defs and current.key not in seen:
            seen.add(current.key)
            following = defs[current.key]
            if isinstance(following, (Var, Const)):
                current = following
            else:
                break
        return current.value if isinstance(current, Const) else current.key if isinstance(current, Var) else None

    merged = 0
    replacements: dict[tuple[str, int], Var] = {}
    for block in fn.blocks.values():
        phis = [s for s in block.stmts if isinstance(s, Phi)]
        for position, later in enumerate(phis):
            for earlier in phis[:position]:
                if earlier.dst.key in replacements or later.dst.key in replacements:
                    continue
                if set(earlier.sources) != set(later.sources):
                    continue
                same = all(value(earlier.sources[p]) is not None and value(earlier.sources[p]) == value(later.sources[p]) for p in earlier.sources)
                widths_match = fn.def_width.get(earlier.dst.key) == fn.def_width.get(later.dst.key)
                if same and widths_match:
                    replacements[later.dst.key] = earlier.dst
                    break
    if not replacements:
        return 0

    def swap(expr: Any) -> Any:
        if isinstance(expr, Var) and expr.key in replacements:
            return Var(replacements[expr.key].name, expr.width, replacements[expr.key].version)
        return expr

    for block in fn.blocks.values():
        kept = []
        for stmt in block.stmts:
            if isinstance(stmt, Phi):
                if stmt.dst.key in replacements:
                    merged += 1
                    continue
                stmt.sources = {p: swap(v) for p, v in stmt.sources.items()}
            else:
                map_stmt(stmt, lambda e: rewrite(e, swap))
            kept.append(stmt)
        block.stmts = kept
    return merged


def simplify_function(fn: Function, recognize_division: bool, report: OptimizeReport | None = None) -> None:
    defs = {s.dst.key: s.src for s in fn.statements() if isinstance(s, Assign)}
    simplify = make_simplifier(defs, recognize_division, report, definition_order(fn))
    for stmt in fn.statements():
        map_stmt(stmt, lambda e: rewrite(e, simplify))
        if isinstance(stmt, Store):
            stmt.place = place_of(stmt.addr, stmt.width)


def optimize(fn: Function, recognize_division: bool = True, rounds: int = 400) -> OptimizeReport:
    report = OptimizeReport()
    for _ in range(rounds):
        report.rounds += 1
        simplify_function(fn, recognize_division, report)
        uses = count_uses(fn)
        removed = remove_dead_code(fn, uses)
        if removed:
            report.removed += removed
            continue
        copies = propagate_copies(fn)
        if copies:
            report.copies += copies
            continue
        merged = merge_congruent_phis(fn)
        if merged:
            report.merged_phis += merged
            continue
        if substitute_once(fn, uses):
            report.substituted += 1
            continue
        break
    fn.divisions = list(report.divisions)
    return report

from __future__ import annotations

from .cfg import dominance_frontiers
from .ir import EXIT, Assign, Cast, Function, Phi, Var, map_stmt, rewrite


def insert_phis(fn: Function) -> int:
    frontier = dominance_frontiers(fn.idom, lambda node: fn.blocks[node].preds)
    defsites: dict[str, set[int]] = {}
    for block in fn.blocks.values():
        for stmt in block.stmts:
            if isinstance(stmt, Assign):
                defsites.setdefault(stmt.dst.name, set()).add(block.start)
    placed = 0
    for name, sites in sorted(defsites.items()):
        has_phi: set[int] = set()
        work = sorted(sites)
        while work:
            node = work.pop()
            for join in sorted(frontier.get(node, ())):
                if join in has_phi:
                    continue
                has_phi.add(join)
                sources = {p: Var(name, 0) for p in fn.blocks[join].preds}
                if join == fn.entry:
                    sources[EXIT] = Var(name, 0, 0)
                phi = Phi(Var(name, 0), sources)
                fn.blocks[join].stmts.insert(0, phi)
                placed += 1
                if join not in sites:
                    work.append(join)
    return placed


def rename(fn: Function) -> None:
    counters: dict[str, int] = {}
    stacks: dict[str, list[int]] = {}
    children_of: dict[int, list[int]] = {b: [] for b in fn.blocks}
    for node, parent in fn.idom.items():
        if node != parent and parent in children_of:
            children_of[parent].append(node)

    def fresh(name: str, width: int) -> Var:
        counters[name] = counters.get(name, 0) + 1
        version = counters[name]
        stacks.setdefault(name, []).append(version)
        fn.def_width[(name, version)] = width
        return Var(name, width, version)

    def use(var: Var) -> Var:
        stack = stacks.get(var.name)
        if not stack:
            fn.def_width[(var.name, 0)] = max(fn.def_width.get((var.name, 0), 0), var.width)
            return Var(var.name, var.width, 0)
        return Var(var.name, var.width, stack[-1])

    def rename_uses(expr):
        return rewrite(expr, lambda e: use(e) if isinstance(e, Var) else e)

    def visit(block_id: int) -> None:
        block = fn.blocks[block_id]
        pushed: list[str] = []
        for stmt in block.stmts:
            if isinstance(stmt, Phi):
                stmt.dst = fresh(stmt.dst.name, 0)
                pushed.append(stmt.dst.name)
                continue
            map_stmt(stmt, rename_uses)
            if isinstance(stmt, Assign):
                stmt.dst = fresh(stmt.dst.name, stmt.dst.width)
                pushed.append(stmt.dst.name)
        for succ in block.succs:
            for stmt in fn.blocks[succ].stmts:
                if isinstance(stmt, Phi):
                    stmt.sources[block_id] = use(Var(stmt.dst.name, 0))
        for child in sorted(children_of[block_id]):
            visit(child)
        for name in pushed:
            stacks[name].pop()

    visit(fn.entry)
    changed = True
    while changed:
        changed = False
        for stmt in fn.statements():
            if isinstance(stmt, Phi):
                width = max(fn.def_width.get(s.key, 0) for s in stmt.sources.values())
                if width > fn.def_width[stmt.dst.key]:
                    fn.def_width[stmt.dst.key] = width
                    changed = True
    for stmt in fn.statements():
        if isinstance(stmt, Phi):
            for source in stmt.sources.values():
                if source.version == 0:
                    fn.def_width[source.key] = max(fn.def_width.get(source.key, 0), fn.def_width[stmt.dst.key])
            stmt.dst = Var(stmt.dst.name, fn.def_width[stmt.dst.key], stmt.dst.version)
            stmt.sources = {p: Var(s.name, fn.def_width[s.key], s.version) for p, s in stmt.sources.items()}

    def cast_use(expr):
        if not isinstance(expr, Var):
            return expr
        def_width = fn.def_width.get(expr.key, expr.width)
        if def_width == 0 or expr.width == 0:
            return Var(expr.name, def_width or expr.width, expr.version)
        if expr.width == def_width:
            return expr
        definition = Var(expr.name, def_width, expr.version)
        return Cast("zext" if expr.width > def_width else "trunc", definition, expr.width)

    for stmt in fn.statements():
        if not isinstance(stmt, Phi):
            map_stmt(stmt, lambda e: rewrite(e, cast_use))


def to_ssa(fn: Function) -> int:
    placed = insert_phis(fn)
    rename(fn)
    return placed


def check_single_assignment(fn: Function) -> list[str]:
    seen: dict[tuple[str, int], int] = {}
    for stmt in fn.statements():
        if isinstance(stmt, (Assign, Phi)):
            seen[stmt.dst.key] = seen.get(stmt.dst.key, 0) + 1
    return [f"{name}_{version}" for (name, version), count in sorted(seen.items()) if count > 1]

from __future__ import annotations

from typing import Any, Callable

from .cfg import EXIT, dominates
from .ir import Bin, Branch, Const, Function, IRBlock, IndirectJump, Jump, Phi, Return, TERMINATORS

NEGATE = {
    "==": "!=", "!=": "==", "<": ">=", ">=": "<", "<=": ">", ">": "<=",
    "<u": ">=u", ">=u": "<u", "<=u": ">u", ">u": "<=u",
}


def negate(cond: Any) -> Any:
    if isinstance(cond, Bin) and cond.op in NEGATE:
        return Bin(NEGATE[cond.op], cond.left, cond.right, cond.width)
    return Bin("==", cond, Const(0, 32), 32)


def natural_loops(fn: Function) -> dict[int, set[int]]:
    preds = fn.preds()
    loops: dict[int, set[int]] = {}
    for block in fn.blocks.values():
        for succ in block.succs:
            if dominates(fn.idom, succ, block.start):
                body = {succ}
                stack = [block.start]
                while stack:
                    node = stack.pop()
                    if node in body:
                        continue
                    body.add(node)
                    stack.extend(preds[node])
                loops.setdefault(succ, set()).update(body)
    return loops


def post_dominators(fn: Function) -> dict[int, int]:
    from .cfg import immediate_dominators

    succs, preds = fn.succs(), fn.preds()
    exits = [b for b, s in succs.items() if not s]
    reverse_succs = {b: list(p) for b, p in preds.items()}
    reverse_succs[EXIT] = exits
    reverse_preds = {b: list(s) + ([EXIT] if b in exits else []) for b, s in succs.items()}
    reverse_preds[EXIT] = []
    seen: set[int] = set()
    postorder: list[int] = []

    def visit(node: int) -> None:
        seen.add(node)
        for target in reverse_succs.get(node, []):
            if target not in seen:
                visit(target)
        postorder.append(node)

    visit(EXIT)
    order = list(reversed(postorder))
    return immediate_dominators(EXIT, order, lambda node: reverse_preds.get(node, []))


class Structurer:

    def __init__(self, fn: Function, statement: Callable[[Any], str | None], condition: Callable[[Any], str]) -> None:
        self.fn = fn
        self.statement = statement
        self.condition = condition
        self.succs = fn.succs()
        fn.ipdom = post_dominators(fn)
        self.loops = natural_loops(fn)
        self.lines: list[str] = []
        self.emitted: set[int] = set()
        self.gotos = 0

    def emit(self, text: str, depth: int) -> None:
        self.lines.append("  " * depth + text)

    @staticmethod
    def terminator(block: IRBlock) -> Any:
        return block.stmts[-1] if block.stmts and isinstance(block.stmts[-1], TERMINATORS) else None

    def body(self, block: IRBlock, depth: int) -> None:
        for stmt in block.stmts:
            if isinstance(stmt, (Phi, Branch, Jump, IndirectJump)):
                continue
            text = self.statement(stmt)
            if text is not None:
                self.emit(text, depth)

    def region_size(self, start: int, stop: int) -> int:
        seen: set[int] = set()
        stack = [start]
        while stack:
            node = stack.pop()
            if node in seen or node == stop or node == EXIT:
                continue
            seen.add(node)
            stack.extend(self.succs[node])
        return len(seen)

    def walk(self, block_id: int, stop: int, depth: int) -> None:
        if block_id in (stop, EXIT):
            return
        if block_id in self.emitted:
            self.gotos += 1
            self.emit(f"goto block_{block_id:x};", depth)
            return
        block = self.fn.blocks[block_id]
        if block_id in self.loops:
            self.emit_loop(block, stop, depth)
            return
        self.emitted.add(block_id)
        term = self.terminator(block)
        self.body(block, depth)
        if isinstance(term, Branch):
            self.emit_branch(block, term, stop, depth)
        elif isinstance(term, IndirectJump) and term.table is not None:
            self.emit_switch(block, term, None, stop, depth)
        elif isinstance(term, Jump):
            self.walk(term.target, stop, depth)
        elif term is None and block.succs:
            self.walk(block.succs[0], stop, depth)

    def switch_head(self, block_id: int, other: int) -> IndirectJump | None:
        if block_id in (EXIT,) or block_id not in self.fn.blocks:
            return None
        term = self.terminator(self.fn.blocks[block_id])
        if isinstance(term, IndirectJump) and term.table is not None and other not in term.table.targets:
            return term
        return None

    def emit_branch(self, block: IRBlock, term: Branch, stop: int, depth: int) -> None:
        join = self.fn.ipdom.get(block.start, EXIT)
        taken, fall = term.target, term.fallthrough
        head = self.switch_head(fall, taken)
        if head is not None and self.fn.blocks[fall].preds == [block.start]:
            self.emitted.add(fall)
            self.body(self.fn.blocks[fall], depth)
            self.emit_switch(self.fn.blocks[fall], head, taken, join, depth)
            self.walk(join, stop, depth)
            return
        if join == taken:
            self.emit(f"if ({self.condition(negate(term.cond))}) {{", depth)
            self.walk(fall, join, depth + 1)
            self.emit("}", depth)
            self.walk(join, stop, depth)
        elif join == fall:
            self.emit(f"if ({self.condition(term.cond)}) {{", depth)
            self.walk(taken, join, depth + 1)
            self.emit("}", depth)
            self.walk(join, stop, depth)
        elif join in (EXIT, stop):
            first, second, cond = taken, fall, term.cond
            if self.region_size(fall, join) < self.region_size(taken, join):
                first, second, cond = fall, taken, negate(term.cond)
            self.emit(f"if ({self.condition(cond)}) {{", depth)
            self.walk(first, join, depth + 1)
            self.emit("}", depth)
            self.walk(second, join, depth)
        else:
            self.emit(f"if ({self.condition(term.cond)}) {{", depth)
            self.walk(taken, join, depth + 1)
            self.emit("} else {", depth)
            self.walk(fall, join, depth + 1)
            self.emit("}", depth)
            self.walk(join, stop, depth)

    def emit_switch(self, block: IRBlock, term: IndirectJump, default: int | None, join: int, depth: int) -> None:
        table = term.table
        assert table is not None
        self.emit(f"switch ({self.condition(term.index)}) {{", depth)
        by_target: dict[int, list[int]] = {}
        for case, target in enumerate(table.targets):
            by_target.setdefault(target, []).append(case)
        for target, cases in sorted(by_target.items(), key=lambda item: item[1][0]):
            for case in cases:
                self.emit(f"case {case}:", depth)
            self.walk(target, join, depth + 1)
            self.emit("break;", depth + 1)
        if default is not None:
            self.emit("default:", depth)
            self.walk(default, join, depth + 1)
            self.emit("break;", depth + 1)
        self.emit("}", depth)

    def emit_loop(self, header: IRBlock, stop: int, depth: int) -> None:
        members = self.loops[header.start]
        exits = sorted({s for b in members for s in self.succs[b] if s not in members})
        exit_block = exits[0] if exits else EXIT
        term = self.terminator(header)
        self.emitted.add(header.start)
        self_loop = header.start in self.succs[header.start]
        header_exits = isinstance(term, Branch) and (term.target not in members or term.fallthrough not in members)
        if header_exits and not self_loop:
            cond = term.cond if term.fallthrough not in members else negate(term.cond)
            inner = term.target if term.target in members else term.fallthrough
            self.body(header, depth)
            self.emit(f"while ({self.condition(cond)}) {{", depth)
            self.walk(inner, header.start, depth + 1)
            self.emit("}", depth)
        else:
            latch = header if self_loop else self.fn.blocks[[b for b in members if header.start in self.succs[b]][0]]
            latch_term = self.terminator(latch)
            self.emit("do {", depth)
            self.body(header, depth + 1)
            if latch is not header:
                for succ in header.succs:
                    self.walk(succ, latch.start, depth + 1)
                self.emitted.add(latch.start)
                self.body(latch, depth + 1)
            if isinstance(latch_term, Branch):
                cond = latch_term.cond if latch_term.target == header.start else negate(latch_term.cond)
                self.emit(f"}} while ({self.condition(cond)});", depth)
            else:
                self.emit("} while (1);", depth)
        self.walk(exit_block, stop, depth)

    def run(self) -> list[str]:
        self.walk(self.fn.entry, EXIT, 1)
        return self.lines


def structure(fn: Function, statement: Callable[[Any], str | None], condition: Callable[[Any], str]) -> tuple[list[str], int]:
    structurer = Structurer(fn, statement, condition)
    lines = structurer.run()
    return lines, structurer.gotos

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from .ir import ARG_REGISTERS, REG32, REG64, Assign, Bin, Cast, Field, Function, Index, Phi, Return, Store, Var, iter_nodes, stmt_exprs, variables

SIGNED_OPS = {">>s", "/", "%", "<", "<=", ">", ">="}
UNSIGNED_OPS = {">>u", "/u", "%u", "<u", "<=u", ">u", ">=u"}


@dataclass
class Param:
    name: str
    register: str
    width: int
    ctype: str
    signedness: str
    evidence: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {"name": self.name, "register": self.register, "width": self.width, "ctype": self.ctype, "signedness": self.signedness, "evidence": list(self.evidence)}


@dataclass
class Signature:
    name: str
    params: list[Param]
    return_type: str
    return_width: int
    structs: dict[str, dict[int, int]]
    undefined_reads: list[str]
    evidence: list[str] = field(default_factory=list)

    def declaration(self) -> str:
        params = ", ".join(declaration(p.ctype, p.name) for p in self.params) or "void"
        return f"{self.return_type} {self.name}({params})"

    def to_dict(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "declaration": self.declaration(),
            "params": [p.to_dict() for p in self.params],
            "returnType": self.return_type,
            "returnWidth": self.return_width,
            "structs": {name: {f"0x{offset:x}": width for offset, width in sorted(fields.items())} for name, fields in self.structs.items()},
            "undefinedReads": list(self.undefined_reads),
            "evidence": list(self.evidence),
        }


def ctype(width: int) -> str:
    return {8: "char", 16: "short", 32: "int", 64: "long"}[width]


def utype(width: int) -> str:
    return "unsigned " + ctype(width)


def declaration(type_name: str, label: str) -> str:
    return f"{type_name}{label}" if type_name.endswith("*") else f"{type_name} {label}"


def live_keys(fn: Function) -> set[tuple[str, int]]:
    keys: set[tuple[str, int]] = set()
    for stmt in fn.statements():
        if isinstance(stmt, (Assign, Phi)):
            keys.add(stmt.dst.key)
        if isinstance(stmt, Phi):
            keys.update(s.key for s in stmt.sources.values())
        for expr in stmt_exprs(stmt):
            keys.update(v.key for v in variables(expr))
    return keys


def collect_params(fn: Function) -> None:
    entry_reads = {key for key in live_keys(fn) if key[1] == 0 and key[0] != "flags"}
    used = [name for name, _ in entry_reads if name in ARG_REGISTERS]
    count = max((ARG_REGISTERS.index(name) for name in used), default=-1) + 1
    fn.params = ARG_REGISTERS[:count]
    fn.param_widths = {name: fn.def_width.get((name, 0), 64) for name in fn.params}
    fn.undefined_reads = sorted(name for name, _ in entry_reads if name not in ARG_REGISTERS and name != "rax")


def coalesce_webs(fn: Function) -> None:
    parent: dict[tuple[str, int], tuple[str, int]] = {}

    def find(key):
        parent.setdefault(key, key)
        while parent[key] != key:
            parent[key] = parent[parent[key]]
            key = parent[key]
        return key

    for key in live_keys(fn):
        find(key)
    for stmt in fn.statements():
        if isinstance(stmt, Phi):
            for src in stmt.sources.values():
                root_a, root_b = find(stmt.dst.key), find(src.key)
                if root_a != root_b:
                    parent[root_a] = root_b
    webs: dict[tuple[str, int], list[tuple[str, int]]] = {}
    for key in list(parent):
        webs.setdefault(find(key), []).append(key)
    counters: dict[str, int] = {}
    fn.web_names = {}
    fn.web_types = {}
    for members in sorted(webs.values(), key=min):
        members.sort()
        width = max(fn.def_width.get(m, 0) for m in members) or 32
        name, version = members[0]
        if name in fn.params and version == 0:
            label = f"param_{fn.params.index(name) + 1}"
        elif name.startswith("local_") or name.startswith("arg_"):
            label = name
        elif version == 0:
            label = f"undefined_{name}"
        else:
            register = name if width == 64 or name not in REG64 else REG32[REG64.index(name)]
            counters[register] = counters.get(register, 0) + 1
            label = f"{register}_{counters[register]}"
        for member in members:
            fn.web_names[member] = label
        fn.web_types[label] = ctype(width)


def signedness_by_web(fn: Function) -> dict[str, set[str]]:
    evidence: dict[str, set[str]] = {}

    def web(var: Var) -> str:
        return fn.web_names.get(var.key, var.name)

    def note(expr: Any, kind: str) -> None:
        if isinstance(expr, Var):
            evidence.setdefault(web(expr), set()).add(kind)
        elif isinstance(expr, Cast) and expr.kind == "zext" and isinstance(expr.expr, Var):
            evidence.setdefault(web(expr.expr), set()).add(kind)

    for stmt in fn.statements():
        for expr in stmt_exprs(stmt):
            for node in iter_nodes(expr):
                if isinstance(node, Bin):
                    if node.op in SIGNED_OPS:
                        note(node.left, "signed")
                        if node.op in ("<", "<=", ">", ">="):
                            note(node.right, "signed")
                    elif node.op in (">>u", "/u", "%u"):
                        note(node.left, "unsigned-arithmetic")
                    elif node.op in UNSIGNED_OPS:
                        note(node.left, "unsigned-compare")
                        note(node.right, "unsigned-compare")
                elif isinstance(node, Cast) and node.kind == "sext" and isinstance(node.expr, Var):
                    evidence.setdefault(web(node.expr), set()).add("signed")
    return evidence


def signedness_label(kinds: set[str]) -> str:
    if not kinds:
        return "none"
    if "signed" in kinds and len(kinds) > 1:
        return "mixed"
    if kinds == {"signed"}:
        return "signed"
    if "unsigned-arithmetic" in kinds:
        return "unsigned"
    return "unsigned-compare"


def infer_types(fn: Function) -> None:
    aliases: dict[str, set[str]] = {}

    def link(a: str, b: str) -> None:
        group = aliases.setdefault(a, {a}) | aliases.setdefault(b, {b})
        for member in group:
            aliases[member] = group

    def web(var: Var) -> str:
        return fn.web_names.get(var.key, var.name)

    element_evidence: dict[str, int] = {}
    struct_evidence: dict[str, dict[int, int]] = {}
    returned: list[int] = []
    undefined_return = False
    for stmt in fn.statements():
        if isinstance(stmt, Assign) and isinstance(stmt.src, Var):
            link(web(stmt.dst), web(stmt.src))
        if isinstance(stmt, Phi):
            for src in stmt.sources.values():
                link(web(stmt.dst), web(src))
        if isinstance(stmt, Return):
            if isinstance(stmt.value, Var) and stmt.value.version == 0:
                undefined_return = True
            else:
                returned.append(getattr(stmt.value, "width", 32))
        places = list(stmt_exprs(stmt)) + ([stmt.place] if isinstance(stmt, Store) and stmt.place is not None else [])
        for expr in places:
            for node in iter_nodes(expr):
                if isinstance(node, Index) and isinstance(node.base, Var):
                    element_evidence[web(node.base)] = node.width
                if isinstance(node, Field) and isinstance(node.base, Var):
                    struct_evidence.setdefault(web(node.base), {})[node.offset] = node.width
    fn.structs = {}
    for label, fields in struct_evidence.items():
        group = aliases.get(label, {label})
        param_labels = sorted(member for member in group if member.startswith("param_"))
        struct_name = f"{fn.name}_{param_labels[0] if param_labels else label}"
        merged = fn.structs.setdefault(struct_name, {})
        for other in group:
            merged.update(struct_evidence.get(other, {}))
        for member in group:
            fn.web_types[member] = f"struct {struct_name} *"
    for label, width in element_evidence.items():
        for member in aliases.get(label, {label}):
            if not fn.web_types.get(member, "").startswith("struct"):
                fn.web_types[member] = f"{ctype(width)} *"
    for label, kinds in signedness_by_web(fn).items():
        if signedness_label(kinds) == "unsigned" and label in fn.web_types and not fn.web_types[label].endswith("*"):
            fn.web_types[label] = "unsigned " + fn.web_types[label]
    if undefined_return and not returned:
        fn.return_type = "void"
    elif not returned:
        fn.return_type = "void"
    else:
        fn.return_type = ctype(max(returned))


def recover_signature(fn: Function) -> Signature:
    collect_params(fn)
    coalesce_webs(fn)
    infer_types(fn)
    kinds = signedness_by_web(fn)
    params: list[Param] = []
    for position, register in enumerate(fn.params):
        label = f"param_{position + 1}"
        width = fn.param_widths.get(register, 64)
        type_name = fn.web_types.get(label, ctype(width))
        evidence = [f"%{register if width == 64 else REG32[REG64.index(register)]} is read before any write"]
        if type_name.endswith("*"):
            if type_name.startswith("struct"):
                struct_name = type_name[len("struct ") : -2].strip()
                offsets = ", ".join(f"0x{o:x}" for o in sorted(fn.structs.get(struct_name, {})))
                evidence.append(f"accessed through constant offsets {offsets}")
            else:
                evidence.append("base register of a scaled element access")
        touched = kinds.get(label, set())
        signedness = "pointer" if type_name.endswith("*") else signedness_label(touched)
        if touched:
            evidence.append("touched by " + " and ".join(sorted(touched)) + " instructions")
        params.append(Param(label, register, width, type_name, signedness, evidence))
    return_width = {"void": 0, "int": 32, "long": 64}.get(fn.return_type, 32)
    evidence = [f"{len(fn.params)} argument register(s) read before write", f"return value width {return_width} from the value in %rax at every return"]
    for kind, lines in sorted(fn.signedness.items()):
        evidence.append(f"{kind} instructions: " + "; ".join(lines[:6]))
    return Signature(fn.name, params, fn.return_type, return_width, dict(fn.structs), list(fn.undefined_reads), evidence)

