"""Parse ordinary textual Git unified diffs; retain physical new-file line numbers."""

import ast
import json
import re
import sys


def decode_path(raw):
    if raw.startswith('"'):
        try:
            value = ast.literal_eval(raw)
            if not isinstance(value, str):
                raise ValueError("bad quoted path")
            if re.search(r"\\[0-7]{3}", raw):
                value = value.encode("latin1").decode("utf-8")
        except (ValueError, SyntaxError, UnicodeError) as error:
            raise ValueError("bad quoted path") from error
    else:
        value = raw.split("\t", 1)[0]
    if value == "/dev/null":
        return None
    if value.startswith("b/"):
        value = value[2:]
    if (
        not value
        or value.startswith("/")
        or ".." in value.split("/")
        or any(ord(c) < 32 for c in value)
    ):
        raise ValueError("unsafe file")
    return value


def parse(raw):
    out, file, line, old_left, new_left = [], None, 0, 0, 0
    for text in raw.splitlines():
        if old_left or new_left:
            if text.startswith("\\"):
                continue
            if text.startswith("+"):
                out.append({"file": file, "line": line, "text": text[1:]})
                line += 1
                new_left -= 1
            elif text.startswith("-"):
                old_left -= 1
            elif text.startswith(" "):
                line += 1
                old_left -= 1
                new_left -= 1
            else:
                raise ValueError("bad or truncated hunk")
            if min(old_left, new_left) < 0:
                raise ValueError("hunk count mismatch")
        elif text.startswith("diff --git "):
            file = None
        elif text.startswith("+++ "):
            file = decode_path(text[4:])
        elif text.startswith("@@ "):
            match = re.match(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@", text)
            if not match or file is None:
                raise ValueError("bad hunk")
            old_left = int(match[2]) if match[2] is not None else 1
            line = int(match[3])
            new_left = int(match[4]) if match[4] is not None else 1
    if old_left or new_left:
        raise ValueError("truncated hunk")
    return out


if __name__ == "__main__":
    try:
        print(json.dumps(parse(sys.stdin.read())))
    except ValueError as error:
        print(str(error), file=sys.stderr)
        sys.exit(1)

/*
 * PR Review Reporter reference implementation.
 * Follow stages in projects/pr-review-reporter/stages/.
 * The demo is deterministic and requires no provider credentials.
 * Protocol references are listed in the project README.
 */
import { pathToFileURL } from "node:url";
import path from "node:path";

import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { writeFileSync } from "node:fs";
export type AddedLine = { file: string; line: number; text: string };
export type Finding = {
  file: string;
  line: number;
  quote: string;
  rule: string;
  severity: "high" | "medium" | "low";
  message: string;
};
export function parseDiff(raw: string): AddedLine[] {
  return JSON.parse(
    execFileSync(
      "python3",
      [fileURLToPath(new URL("./diff_parser.py", import.meta.url))],
      { input: raw, encoding: "utf8", maxBuffer: 1_000_000 },
    ),
  );
}
export function inspect(lines: AddedLine[]): Finding[] {
  const rules: [RegExp, string, Finding["severity"], string][] = [
    [
      /\beval\s*\(/,
      "dynamic-eval",
      "high",
      "Untrusted input can execute code.",
    ],
    [
      /\bexec\s*\(/,
      "shell-exec",
      "high",
      "Use an argument array instead of shell interpolation.",
    ],
    [
      /rejectUnauthorized\s*:\s*false/,
      "tls-disabled",
      "high",
      "TLS certificate verification is disabled.",
    ],
    [
      /\.catch\s*\(\s*\(\)\s*=>\s*\{\s*\}/,
      "empty-catch",
      "medium",
      "An empty catch hides failures.",
    ],
  ];
  return lines.flatMap((line) =>
    rules
      .filter(
        ([pattern]) =>
          !/^\s*(?:\/\/|\*|#)/.test(line.text) && pattern.test(line.text),
      )
      .map(([, rule, severity, message]) => ({
        ...line,
        quote: line.text,
        rule,
        severity,
        message,
      })),
  );
}
export function verify(
  findings: unknown[],
  lines: AddedLine[],
): { accepted: Finding[]; rejected: unknown[] } {
  if (!Array.isArray(findings)) throw new Error("candidates must be an array");
  const accepted: Finding[] = [];
  const rejected: unknown[] = [];
  for (const candidate of findings) {
    if (!candidate || typeof candidate !== "object" || Array.isArray(candidate)) {
      rejected.push(candidate);
      continue;
    }
    const f = candidate as Finding;
    if (
      ![f.file, f.quote, f.rule, f.message].every((value) => typeof value === "string") ||
      !Number.isSafeInteger(f.line) || f.line < 1
    ) {
      rejected.push(candidate);
      continue;
    }
    const line = lines.find((l) => l.file === f.file && l.line === f.line);
    if (
      !line ||
      !f.quote.trim() ||
      !line.text.includes(f.quote) ||
      !["high", "medium", "low"].includes(f.severity) ||
      !f.rule.trim() ||
      !f.message.trim()
    )
      rejected.push(f);
    else accepted.push(f);
  }
  return { accepted, rejected };
}
export function merge(findings: Finding[]): Finding[] {
  const ranks = { high: 3, medium: 2, low: 1 };
  const unique = new Map<string, Finding>();
  for (const f of findings) {
    const key = JSON.stringify([f.file, f.line, f.rule]);
    const prev = unique.get(key);
    if (!prev || ranks[f.severity] > ranks[prev.severity]) unique.set(key, f);
  }
  return [...unique.values()].sort(
    (a, b) =>
      ranks[b.severity] - ranks[a.severity] ||
      a.file.localeCompare(b.file) ||
      a.line - b.line,
  );
}
export function escapeHTML(value: string): string {
  return value.replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ]!,
  );
}
export function render(findings: Finding[], rejected = 0): string {
  return (
    '<!doctype html><meta charset="utf-8"><title>PR Review</title><h1>Anchored review</h1><p>' +
    findings.length +
    " findings; " +
    rejected +
    " rejected</p><ol>" +
    findings
      .map(
        (f) =>
          `<li><strong>${escapeHTML(f.severity)} ${escapeHTML(f.file)}:${f.line}</strong><p>${escapeHTML(f.message)}</p><pre>${escapeHTML(f.quote)}</pre><small>${escapeHTML(f.rule)}</small></li>`,
      )
      .join("") +
    "</ol>"
  );
}
export const fixture =
  "diff --git a/src/run.ts b/src/run.ts\n--- a/src/run.ts\n+++ b/src/run.ts\n@@ -1,1 +1,2 @@\n const input = request.body;\n+eval(input);\n";
if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href
) {
  const lines = parseDiff(fixture);
  const result = verify(inspect(lines), lines);
  const findings = merge(result.accepted);
  writeFileSync("review.html", render(findings, result.rejected.length));
  console.log(
    JSON.stringify(
      { addedLines: lines.length, findings, report: "review.html" },
      null,
      2,
    ),
  );
}

"""Compare provenance-bound recorded prompt runs and return a CI exit status."""

import argparse, hashlib, json
from pathlib import Path
from main import compare, release_gate, validate_cases


def case_digest(cases):
    return hashlib.sha256(
        json.dumps(cases, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()


def load_run(raw, cases):
    if raw.get("schema_version") != 1 or raw.get("case_sha256") != case_digest(cases):
        raise ValueError("recording does not match cases")
    if (
        not isinstance(raw.get("model"), str)
        or not raw["model"]
        or not isinstance(raw.get("settings"), dict)
        or not isinstance(raw.get("revision"), str)
    ):
        raise ValueError("recording provenance required")
    template = raw.get("prompt_template")
    if (
        not isinstance(template, str)
        or not template
        or raw.get("template_sha256") != hashlib.sha256(template.encode()).hexdigest()
    ):
        raise ValueError("recorded prompt template and matching digest required")
    if not isinstance(raw.get("responses"), dict):
        raise ValueError("recorded response mapping required")
    return raw


def run(cases, baseline, candidate, allow_configuration_change=False):
    validate_cases(cases)
    old = load_run(baseline, cases)
    new = load_run(candidate, cases)
    changed = old["model"] != new["model"] or old["settings"] != new["settings"]
    if changed and not allow_configuration_change:
        raise ValueError("model/settings changed; explicitly allow this experiment")
    comparison = compare(cases, old["responses"], new["responses"])
    return {
        "schema_version": 1,
        "case_sha256": case_digest(cases),
        "revisions": [old["revision"], new["revision"]],
        "configuration_changed": changed,
        "prompt_templates": [
            {
                "revision": item["revision"],
                "text": item["prompt_template"],
                "sha256": item["template_sha256"],
            }
            for item in (old, new)
        ],
        "comparison": comparison,
        "gate": release_gate(comparison),
    }


def main():
    p = argparse.ArgumentParser(description=__doc__)
    for key in ["cases", "baseline", "candidate"]:
        p.add_argument(key)
    p.add_argument("--allow-configuration-change", action="store_true")
    p.add_argument("--out")
    p.add_argument("--markdown")
    a = p.parse_args()
    result = run(
        *(
            json.loads(Path(getattr(a, k)).read_text())
            for k in ["cases", "baseline", "candidate"]
        ),
        a.allow_configuration_change,
    )
    text = json.dumps(result, indent=2)
    if a.out:
        Path(a.out).write_text(text + "\n")
    if a.markdown:
        lines = [
            "# Prompt revision comparison",
            "",
            "| Case | Change |",
            "|---|---|",
        ] + [
            "| " + row["id"].replace("|", "\\|") + " | " + row["state"] + " |"
            for row in result["comparison"]["cases"]
        ]
        Path(a.markdown).write_text("\n".join(lines) + "\n")
    print(text)
    return 0 if result["gate"]["decision"] == "ship" else 1


if __name__ == "__main__":
    raise SystemExit(main())

import json
import math


def validate_cases(cases):
    seen = set()
    for c in cases:
        if (
            not isinstance(c, dict)
            or not isinstance(c.get("id"), str)
            or (not c["id"])
            or (c["id"] in seen)
        ):
            raise ValueError("unique case id required")
        seen.add(c["id"])
        if (
            not isinstance(c.get("prompt"), str)
            or not isinstance(c.get("checks"), list)
            or (not c["checks"])
        ):
            raise ValueError("prompt and checks required")
        for check in c["checks"]:
            if check.get("kind") not in ("contains", "excludes", "json"):
                raise ValueError("unknown check")
            if check["kind"] != "json" and (not isinstance(check.get("value"), str)):
                raise ValueError("check text required")
    return cases


def reject_json_constant(value):
    raise ValueError(value)


def score_response(response, checks):
    evidence = []
    for check in checks:
        passed = False
        if isinstance(response, str):
            if check["kind"] == "contains":
                passed = check["value"] in response
            elif check["kind"] == "excludes":
                passed = check["value"] not in response
            elif check["kind"] == "json":
                try:
                    json.loads(
                        response,
                        parse_constant=reject_json_constant,
                    )
                    passed = True
                except (ValueError, TypeError):
                    pass
            else:
                raise ValueError("unknown check")
        evidence.append({"kind": check["kind"], "passed": passed})
    return {
        "passed": bool(checks) and all((e["passed"] for e in evidence)),
        "checks": evidence,
    }


def compare(cases, baseline, candidate):
    validate_cases(cases)
    rows = []
    for c in cases:
        old = score_response(baseline.get(c["id"]), c["checks"])["passed"]
        new = score_response(candidate.get(c["id"]), c["checks"])["passed"]
        if old and new:
            state = "stable_pass"
        elif not old and not new:
            state = "stable_fail"
        elif old:
            state = "regressed"
        else:
            state = "improved"
        rows.append({"id": c["id"], "state": state, "passed": new})
    return {
        "cases": rows,
        "regressions": sum((r["state"] == "regressed" for r in rows)),
        "improvements": sum((r["state"] == "improved" for r in rows)),
        "pass_rate": sum((r["passed"] for r in rows)) / len(rows) if rows else 0,
    }


def release_gate(report, min_pass=1.0, max_regressions=0):
    if (
        not isinstance(min_pass, (int, float))
        or not math.isfinite(min_pass)
        or (not 0 <= min_pass <= 1)
    ):
        raise ValueError("pass threshold in [0,1] required")
    if not isinstance(max_regressions, int) or max_regressions < 0:
        raise ValueError("nonnegative regression budget required")
    ship = (
        bool(report["cases"])
        and report["pass_rate"] >= min_pass
        and (report["regressions"] <= max_regressions)
    )
    return {
        "decision": "ship" if ship else "block",
        "pass_rate": report["pass_rate"],
        "regressions": report["regressions"],
    }

"""Exclude expired evidence at query time.

Lesson: projects/rag-freshness-pipeline/stages/04-retrieve/docs/en.md
The implementation is original and uses explicit local data contracts.
Run its tests through scripts/project_test.py.
"""

import re


def retrieve(documents, query, now, max_age=3600, k=3):
    if max_age < 0 or k < 0:
        raise ValueError("nonnegative age and k required")
    terms = set(re.findall(r"\w+", query.casefold()))
    rows = []
    for doc in documents.values():
        age = now - doc["updated"]
        if age < 0 or age > max_age:
            continue
        found = terms & set(re.findall(r"\w+", doc["text"].casefold()))
        if found:
            rows.append(
                {
                    "id": doc["id"],
                    "score": len(found) / len(terms),
                    "age": age,
                    "hash": doc["hash"],
                }
            )
    return sorted(rows, key=lambda r: (-r["score"], r["age"], r["id"]))[:k]

"""Parse claims and citation references.

Lesson: projects/report-judge/stages/01-claims/docs/en.md
The implementation is original and uses explicit local data contracts.
Run its tests through scripts/project_test.py.
"""

import re


def parse_claims(text):
    rows = []
    for line in text.splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        for sentence in re.split(r"(?<=\.)\s+", line.strip()):
            cites = re.findall(r"\[([A-Za-z][A-Za-z0-9_-]*)\]", sentence)
            claim = (
                re.sub(r"\[[A-Za-z][A-Za-z0-9_-]*\]", "", sentence).strip().rstrip(".")
            )
            if claim:
                rows.append({"text": claim, "cites": list(dict.fromkeys(cites))})
    return rows

"""Check evidence before averaging scores.

Lesson: projects/report-judge/stages/02-support/docs/en.md
The implementation is original and uses explicit local data contracts.
Run its tests through scripts/project_test.py.
"""

import re


def support(claim, source):
    tokens = lambda s: (
        set(re.findall(r"\b\w+\b", s.lower())) - {"a", "an", "the", "is", "of", "and"}
    )
    c, s = tokens(claim), tokens(source)
    if not c:
        return {"score": 0.0, "reason": "empty"}
    if (c & {"no", "not", "never", "cannot"}) != (s & {"no", "not", "never", "cannot"}):
        return {"score": 0.0, "reason": "negation"}
    if set(re.findall(r"\d+(?:\.\d+)?", claim)) - set(
        re.findall(r"\d+(?:\.\d+)?", source)
    ):
        return {"score": 0.0, "reason": "number"}
    stop = {"a", "an", "the", "is", "of", "and"}
    claim_order = [w for w in re.findall(r"\b\w+\b", claim.casefold()) if w not in stop]
    source_order = [
        w for w in re.findall(r"\b\w+\b", source.casefold()) if w not in stop
    ]
    if c <= s:
        remaining = iter(source_order)
        if not all(
            any(word == candidate for candidate in remaining) for word in claim_order
        ):
            return {"score": 0.0, "reason": "order_requires_review"}
    return {"score": len(c & s) / len(c), "reason": "lexical_overlap"}


def judge_claim(claim, evidence, threshold=0.8):
    if not 0 <= threshold <= 1:
        raise ValueError("threshold must be between zero and one")
    if not claim["cites"]:
        return {"supported": False, "reason": "uncited", "score": 0.0}
    if any(c not in evidence for c in claim["cites"]):
        return {"supported": False, "reason": "dangling", "score": 0.0}
    best = max(
        (support(claim["text"], evidence[c]) for c in claim["cites"]),
        key=lambda r: r["score"],
    )
    return {**best, "supported": best["score"] >= threshold}

"""Compare published claims and their exact evidence across local corpus revisions."""

import hashlib


def compare_reports(previous, current):
    if previous.get("schema_version") != 1 or current.get("schema_version") != 1:
        raise ValueError("report schema_version1 required")
    if previous["question"] != current["question"]:
        raise ValueError("compare the same research question")

    def claims(payload):
        result = {}
        for section in payload["sections"]:
            for sentence in section["sentences"]:
                evidence = []
                for key in sentence["cites"]:
                    snippet = payload["snippets"][key]
                    evidence.append(
                        {
                            "doc_id": snippet["doc_id"],
                            "start": snippet["start"],
                            "end": snippet["end"],
                            "text_sha256": hashlib.sha256(
                                snippet["text"].encode()
                            ).hexdigest(),
                        }
                    )
                result.setdefault(sentence["text"], []).extend(evidence)
        return result

    old, new = claims(previous), claims(current)
    return {
        "schema_version": 1,
        "question": current["question"],
        "removed_claims": sorted(old.keys() - new.keys()),
        "added_claims": sorted(new.keys() - old.keys()),
        "changed_evidence": [
            {"claim": text, "before": old[text], "after": new[text]}
            for text in sorted(old.keys() & new.keys())
            if old[text] != new[text]
        ],
        "unchanged_claims": len(
            [text for text in old.keys() & new.keys() if old[text] == new[text]]
        ),
    }

"""Citation format and validation.

Lesson: projects/research-report-agent/stages/04-write-with-citations/docs/en.md
A cited sentence ends with one or more markers such as [S3] or [S3][S7],
then a period. Stdlib only.
"""

import re
from dataclasses import dataclass

CITE_RE = re.compile(r"\[(S\d+)\]")
TRAILING_CITES_RE = re.compile(r"((?:\s*\[S\d+\])+)\s*[.!?]?\s*$")
SENTENCE_BOUNDARY_RE = re.compile(r"(?<=\][.!?])\s+|(?<=[.!?])\s+(?=[A-Z0-9\[])")


@dataclass(frozen=True)
class CitationError:
    sentence: str
    reason: str


def cites_of(sentence):
    match = TRAILING_CITES_RE.search(sentence)
    return CITE_RE.findall(match.group(1)) if match else []


def strip_cites(sentence):
    text = TRAILING_CITES_RE.sub("", sentence).strip()
    return CITE_RE.sub("", text).strip()


def report_sentences(markdown):
    sentences = []
    for line in markdown.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        sentences.extend(
            part.strip()
            for part in SENTENCE_BOUNDARY_RE.split(stripped)
            if part.strip()
        )
    return sentences


def validate_citations(markdown, snippet_ids):
    known = set(snippet_ids)
    errors = []
    for sentence in report_sentences(markdown):
        cites = cites_of(sentence)
        if not cites:
            errors.append(CitationError(sentence, "uncited"))
            continue
        for cite in cites:
            if cite not in known:
                errors.append(CitationError(sentence, f"dangling:{cite}"))
    return errors

"""Critic: check every sentence against the snippet it cites, under a budget.

Lesson: projects/research-report-agent/stages/05-verify-every-claim/docs/en.md
Support is lexical: content overlap plus strict rules for names, numbers and
negation. The harness, not the writer, decides the terminal state.
"""

import re
from dataclasses import dataclass, replace

from report_agent.citations import cites_of, report_sentences, strip_cites
from report_agent.search import tokenize

NEGATIONS = frozenset({"not", "no", "never", "cannot", "without", "nothing"})
WORD_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9./-]*")
TERMINAL_STATES = ("completed", "needs_review", "failed")


class BudgetExceeded(RuntimeError):
    pass


@dataclass(frozen=True)
class Verdict:
    sentence: str
    cites: tuple
    score: float
    supported: bool
    reason: str


class Budget:
    def __init__(self, max_steps=50, max_tokens=20000):
        self.max_steps = max_steps
        self.max_tokens = max_tokens
        self.used_steps = 0
        self.used_tokens = 0

    def charge(self, step, tokens=0):
        if self.used_steps + 1 > self.max_steps:
            raise BudgetExceeded(f"step budget exhausted at {step!r}")
        if self.used_tokens + tokens > self.max_tokens:
            raise BudgetExceeded(f"token budget exhausted at {step!r}")
        self.used_steps += 1
        self.used_tokens += tokens

    def to_dict(self):
        return {
            "max_steps": self.max_steps,
            "used_steps": self.used_steps,
            "max_tokens": self.max_tokens,
            "used_tokens": self.used_tokens,
        }


def estimate_tokens(text):
    return max(1, len(text) // 4)


def strict_terms(sentence):
    terms = set()
    for position, word in enumerate(WORD_RE.findall(sentence)):
        cleaned = word.strip(".").lower()
        if not cleaned:
            continue
        has_digit = any(char.isdigit() for char in word)
        inner_capital = any(char.isupper() for char in word[1:])
        proper_mid_sentence = word[0].isupper() and position > 0
        if has_digit or inner_capital or proper_mid_sentence:
            terms.add(cleaned)
    return terms


def support_score(sentence, snippet_text):
    claim = strip_cites(sentence)
    claim_tokens = set(tokenize(claim))
    source_tokens = set(tokenize(snippet_text))
    source_lower = snippet_text.lower()
    missing = [term for term in strict_terms(claim) if term not in source_lower]
    if missing:
        return 0.0, f"names or numbers not in source: {', '.join(sorted(missing))}"
    claim_neg = set(re.findall(r"[a-z]+", claim.lower())) & NEGATIONS
    source_neg = set(re.findall(r"[a-z]+", source_lower)) & NEGATIONS
    if claim_neg != source_neg:
        return 0.0, "negation differs from source"
    if not claim_tokens:
        return 0.0, "no content words"
    overlap = len(claim_tokens & source_tokens) / len(claim_tokens)
    return round(overlap, 4), "overlap"


def snippet_text(snippet):
    return snippet if isinstance(snippet, str) else snippet.text


def review(markdown, snippets, threshold=0.6):
    verdicts = []
    for sentence in report_sentences(markdown):
        cites = tuple(cites_of(sentence))
        if not cites:
            verdicts.append(Verdict(sentence, cites, 0.0, False, "uncited"))
            continue
        dangling = [cite for cite in cites if cite not in snippets]
        if dangling:
            verdicts.append(
                Verdict(sentence, cites, 0.0, False, f"dangling:{','.join(dangling)}")
            )
            continue
        best_score, best_reason = -1.0, ""
        for cite in cites:
            score, reason = support_score(sentence, snippet_text(snippets[cite]))
            if score > best_score:
                best_score, best_reason = score, reason
        supported = best_score >= threshold
        if supported:
            reason = "supported"
        elif best_reason == "overlap":
            reason = f"low overlap {best_score:.2f}"
        else:
            reason = best_reason
        verdicts.append(Verdict(sentence, cites, best_score, supported, reason))
    return verdicts


def decide_state(verdicts, budget_exceeded=False):
    if budget_exceeded:
        return "failed"
    if not verdicts or not any(verdict.supported for verdict in verdicts):
        return "failed"
    if all(verdict.supported for verdict in verdicts):
        return "completed"
    return "needs_review"


def apply_verdicts(report, verdicts):
    keep = {verdict.sentence for verdict in verdicts if verdict.supported}
    sections = []
    for section in report.sections:
        sentences = [
            sentence for sentence in section.sentences if sentence.render() in keep
        ]
        if sentences:
            sections.append(replace(section, sentences=sentences))
    used = {
        cite
        for section in sections
        for sentence in section.sentences
        for cite in sentence.cites
    }
    return replace(
        report,
        sections=sections,
        snippets={key: value for key, value in report.snippets.items() if key in used},
    )

"""Score reports on checked-in public evaluation fixtures.

Lesson: projects/research-report-agent/stages/07-score-the-report/docs/en.md
Metrics follow the spirit of citation support with
simple, inspectable definitions. Stdlib only.
"""

import json
from dataclasses import dataclass, field
from pathlib import Path

from report_agent.critic import support_score
from report_agent.pipeline import run_pipeline

WEIGHTS = {"citation_precision": 0.4, "source_recall": 0.3, "fact_coverage": 0.3}


@dataclass
class QuestionScore:
    id: str
    question: str
    citation_precision: float
    source_recall: float
    fact_coverage: float
    terminal_state: str


@dataclass
class Scorecard:
    questions: list = field(default_factory=list)

    def mean(self, metric):
        if not self.questions:
            return 0.0
        return round(
            sum(getattr(q, metric) for q in self.questions) / len(self.questions), 4
        )

    def score(self):
        return round(
            100 * sum(weight * self.mean(metric) for metric, weight in WEIGHTS.items()),
            1,
        )


def citation_precision(report, threshold=0.8):
    checked = 0
    supported = 0
    for section in report.sections:
        for sentence in section.sentences:
            checked += 1
            best = max(
                support_score(sentence.render(), report.snippets[cite].text)[0]
                for cite in sentence.cites
            )
            supported += best >= threshold
    return round(supported / checked, 4) if checked else 0.0


def source_recall(report, expected_docs):
    if not expected_docs:
        return 1.0
    cited = {snippet.doc_id for snippet in report.snippets.values()}
    return round(len(cited & set(expected_docs)) / len(set(expected_docs)), 4)


def fact_coverage(report, key_facts):
    if not key_facts:
        return 1.0
    sentences = [
        s.text.lower() for section in report.sections for s in section.sentences
    ]
    hits = sum(
        1
        for terms in key_facts
        if any(all(term.lower() in text for term in terms) for text in sentences)
    )
    return round(hits / len(key_facts), 4)


def evaluate(questions_path, corpus_dir, model=None):
    questions = json.loads(Path(questions_path).read_text(encoding="utf-8"))[
        "questions"
    ]
    card = Scorecard()
    for item in questions:
        report, trace, _ = run_pipeline(item["question"], corpus_dir, model=model)
        card.questions.append(
            QuestionScore(
                id=item["id"],
                question=item["question"],
                citation_precision=citation_precision(report),
                source_recall=source_recall(report, item.get("expected_docs", [])),
                fact_coverage=fact_coverage(report, item.get("key_facts", [])),
                terminal_state=trace["terminal_state"],
            )
        )
    return card


def format_scorecard(card):
    lines = [f"{'id':<6}{'precision':>11}{'recall':>9}{'facts':>8}  state", "-" * 46]
    for q in card.questions:
        lines.append(
            f"{q.id:<6}{q.citation_precision:>11.2f}{q.source_recall:>9.2f}{q.fact_coverage:>8.2f}  {q.terminal_state}"
        )
    lines.append("-" * 46)
    lines.append(
        f"{'mean':<6}{card.mean('citation_precision'):>11.2f}{card.mean('source_recall'):>9.2f}"
        f"{card.mean('fact_coverage'):>8.2f}"
    )
    lines.append(f"score {card.score()} / 100")
    return "\n".join(lines)

"""Model interface with a replay cassette and an optional live client.

Lesson: projects/research-report-agent/stages/03-plan-the-research/docs/en.md
Tests use ReplayModel only. LiveModel talks to any chat-completions-compatible
/chat/completions endpoint and is never required. Stdlib only.
"""

import hashlib
import json
import os
import urllib.request
from pathlib import Path
from typing import Protocol


class CassetteMiss(KeyError):
    pass


class Model(Protocol):
    def complete(self, prompt: str, *, purpose: str) -> str: ...


def prompt_key(purpose, prompt):
    digest = hashlib.sha256(prompt.encode("utf-8")).hexdigest()
    return f"{purpose}:{digest}"


class ReplayModel:
    def __init__(self, cassette_path):
        data = json.loads(Path(cassette_path).read_text(encoding="utf-8"))
        self.entries = {
            prompt_key(entry["purpose"], entry["prompt"]): entry["response"]
            for entry in data["entries"]
        }
        self.calls = []

    def complete(self, prompt, *, purpose):
        key = prompt_key(purpose, prompt)
        self.calls.append(key)
        if key not in self.entries:
            raise CassetteMiss(f"no recorded response for purpose={purpose!r}")
        return self.entries[key]


class LiveModel:
    def __init__(self, base_url=None, api_key=None, model=None, timeout=60):
        self.base_url = (base_url or os.environ.get("RRA_LLM_BASE_URL", "")).rstrip("/")
        self.api_key = api_key or os.environ.get("RRA_LLM_API_KEY", "")
        self.model = model or os.environ.get("RRA_LLM_MODEL", "")
        self.timeout = timeout
        if not (self.base_url and self.model):
            raise ValueError("set RRA_LLM_BASE_URL and RRA_LLM_MODEL to use LiveModel")

    def complete(self, prompt, *, purpose):
        body = json.dumps(
            {
                "model": self.model,
                "messages": [{"role": "user", "content": prompt}],
                "temperature": 0,
            }
        ).encode("utf-8")
        request = urllib.request.Request(
            self.base_url + "/chat/completions",
            data=body,
            headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {self.api_key}",
            },
        )
        with urllib.request.urlopen(request, timeout=self.timeout) as response:
            payload = json.loads(response.read().decode("utf-8"))
        return payload["choices"][0]["message"]["content"]

"""Research planning: turn one question into facets to search for.

Lesson: projects/research-report-agent/stages/03-plan-the-research/docs/en.md
A deterministic rule planner is the default. A Model can replace it, and any
bad model output falls back to the rules. Stdlib only.
"""

import json
import re
from dataclasses import dataclass, field

from report_agent.search import tokenize

LEADING_WORDS = frozenset(
    "what how why when which who where do does did is are was were should can could would "
    "the a an".split()
)

FACET_TEMPLATES = (
    ("Overview", "What is {subject}?", ()),
    ("How it works", "How does {subject} work?", ("works", "uses", "runs")),
    (
        "Risks and limits",
        "What are the risks and limits of {subject}?",
        ("risk", "attack", "escape", "weakness", "cost"),
    ),
    (
        "When to use it",
        "When should teams use {subject}?",
        ("use", "teams", "tradeoff", "overhead"),
    ),
)


@dataclass(frozen=True)
class Facet:
    id: str
    sub_question: str
    keywords: tuple
    label: str = ""

    def query(self):
        return self.sub_question + " " + " ".join(self.keywords)


@dataclass
class Plan:
    question: str
    facets: list
    source: str = "rules"
    notes: list = field(default_factory=list)


def subject_of(question):
    words = re.sub(r"[?!.]+$", "", question.strip()).split()
    while words and words[0].lower() in LEADING_WORDS:
        words.pop(0)
    return " ".join(words) or question.strip()


def rule_plan(question, max_facets=4):
    subject = subject_of(question)
    base = tuple(tokenize(question))
    facets = []
    for position, (label, template, extra) in enumerate(
        FACET_TEMPLATES[:max_facets], start=1
    ):
        keywords = tuple(dict.fromkeys(base + extra))
        facets.append(
            Facet(
                id=f"F{position}",
                sub_question=template.format(subject=subject),
                keywords=keywords,
                label=label,
            )
        )
    return facets


def build_planner_prompt(question, max_facets=4):
    return (
        "You plan research for a cited report.\n"
        f"Split the question into at most {max_facets} facets.\n"
        'Reply with JSON only: {"facets": [{"sub_question": "...", "keywords": ["..."]}]}\n'
        f"Question: {question}"
    )


def parse_model_facets(raw, max_facets):
    data = json.loads(raw)
    items = data.get("facets") if isinstance(data, dict) else None
    if not isinstance(items, list) or not items:
        raise ValueError("model reply has no facets list")
    facets = []
    for position, item in enumerate(items[:max_facets], start=1):
        sub_question = item.get("sub_question") if isinstance(item, dict) else None
        keywords = item.get("keywords") if isinstance(item, dict) else None
        if not isinstance(sub_question, str) or not sub_question.strip():
            raise ValueError(f"facet {position} has no sub_question")
        if not isinstance(keywords, list) or not all(
            isinstance(word, str) for word in keywords
        ):
            raise ValueError(f"facet {position} keywords must be a list of strings")
        label = item.get("label") if isinstance(item.get("label"), str) else ""
        facets.append(
            Facet(
                id=f"F{position}",
                sub_question=sub_question.strip(),
                keywords=tuple(keywords),
                label=label,
            )
        )
    return facets


def plan_research(question, model=None, max_facets=4):
    if not question or not question.strip():
        raise ValueError("question must not be empty")
    if model is None:
        return Plan(question=question, facets=rule_plan(question, max_facets))
    try:
        raw = model.complete(build_planner_prompt(question, max_facets), purpose="plan")
        return Plan(
            question=question,
            facets=parse_model_facets(raw, max_facets),
            source="model",
        )
    except (KeyError, ValueError, TypeError, AttributeError) as error:
        return Plan(
            question=question,
            facets=rule_plan(question, max_facets),
            source="rules-fallback",
            notes=[f"model plan rejected: {error}"],
        )

"""Serialize verified evidence and render it with the typed Node viewer.

Lesson: projects/research-report-agent/stages/06-publish-the-report/docs/en.md
Python owns the report and trace; TypeScript validates source spans and escapes
HTML. Node 22.18+ runs erasable types without a third-party transpiler.
"""

import json
import subprocess
import time
import uuid
from contextlib import contextmanager
from dataclasses import asdict
from datetime import datetime, timezone
from pathlib import Path


class Tracer:
    def __init__(self, question, run_id=None):
        self.run_id = run_id or uuid.uuid4().hex[:12]
        self.question = question
        self.started_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
        self.steps = []
        self.counts = {}
        self.budget = {}
        self.terminal_state = None

    @contextmanager
    def step(self, name, **detail):
        start = time.perf_counter()
        record = {"name": name, "detail": dict(detail)}
        try:
            yield record["detail"]
        finally:
            record["ms"] = round((time.perf_counter() - start) * 1000, 3)
            self.steps.append(record)

    def to_dict(self):
        return {
            "run_id": self.run_id,
            "question": self.question,
            "started_at": self.started_at,
            "steps": self.steps,
            "counts": self.counts,
            "budget": self.budget,
            "terminal_state": self.terminal_state,
        }


def footnote_numbers(report):
    numbers = {}
    for section in report.sections:
        for sentence in section.sentences:
            for cite in sentence.cites:
                numbers.setdefault(cite, len(numbers) + 1)
    return numbers


def report_payload(report, documents, trace=None):
    return {
        "schema_version": 1,
        **asdict(report),
        "documents": [asdict(doc) for doc in documents],
        "trace": trace,
    }


def render_html(report, documents, trace=None):
    renderer = Path(__file__).resolve().parents[1] / "viewer" / "render.ts"
    result = subprocess.run(
        ["node", str(renderer)],
        input=json.dumps(report_payload(report, documents, trace)),
        capture_output=True,
        text=True,
        timeout=20,
    )
    if result.returncode:
        raise RuntimeError("TypeScript viewer failed: " + result.stderr.strip())
    return result.stdout


def write_outputs(out_dir, html_text, trace_dict, report_data=None):
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    (out / "report.html").write_text(html_text, encoding="utf-8")
    (out / "trace.json").write_text(json.dumps(trace_dict, indent=2), encoding="utf-8")
    if report_data is not None:
        (out / "report.json").write_text(
            json.dumps(report_data, indent=2), encoding="utf-8"
        )
    return out / "report.html", out / "trace.json"

"""Snippet extraction with exact source offsets.

Lesson: projects/research-report-agent/stages/02-extract-snippets/docs/en.md
Every snippet keeps (start, end) so its text equals document.text[start:end],
which is what makes a citation checkable later. Stdlib only.
"""

import re
from dataclasses import dataclass

from report_agent.search import tokenize

SENTENCE_END_RE = re.compile(r"[.!?](?=\s+[A-Za-z0-9\"(]|\s*$)")


@dataclass(frozen=True)
class Snippet:
    id: str
    doc_id: str
    start: int
    end: int
    text: str
    score: float


def split_sentences(text):
    spans = []
    cursor = 0
    for match in SENTENCE_END_RE.finditer(text):
        end = match.end()
        start = cursor
        while start < end and text[start].isspace():
            start += 1
        if start < end:
            spans.append((start, end))
        cursor = end
    start = cursor
    while start < len(text) and text[start].isspace():
        start += 1
    if start < len(text):
        end = len(text)
        while end > start and text[end - 1].isspace():
            end -= 1
        spans.append((start, end))
    return spans


CONTEXT_DEPENDENT_STARTS = frozenset(
    {"it", "its", "this", "that", "these", "those", "they", "their", "he", "she"}
)


def score_sentence(sentence, query_tokens, idf, min_words=6):
    words = sentence.split()
    if len(words) < min_words:
        return 0.0
    sentence_tokens = set(tokenize(sentence))
    score = sum(
        idf.get(token, 0.0) for token in set(query_tokens) if token in sentence_tokens
    )
    if words[0].lower().strip(",") in CONTEXT_DEPENDENT_STARTS:
        score *= 0.5
    return score


def extract_snippets(
    query, index, k_docs=4, per_doc=3, start_id=1, min_score=0.0, doc_ids=None
):
    query_tokens = tokenize(query)
    by_id = {doc.id: doc for doc in index.documents}
    candidates = []
    ranked = (
        list(doc_ids)
        if doc_ids is not None
        else [doc_id for doc_id, _ in index.search(query, k=k_docs)]
    )
    for doc_id in ranked:
        doc = by_id[doc_id]
        scored = []
        for start, end in split_sentences(doc.text):
            value = score_sentence(doc.text[start:end], query_tokens, index.idf)
            if value > min_score:
                scored.append((value, start, end))
        scored.sort(key=lambda item: (-item[0], item[1]))
        for value, start, end in scored[:per_doc]:
            candidates.append((value, doc_id, start, end, doc.text[start:end]))
    candidates.sort(key=lambda item: (-item[0], item[1], item[2]))
    return [
        Snippet(
            id=f"S{start_id + offset}",
            doc_id=doc_id,
            start=start,
            end=end,
            text=text,
            score=round(value, 4),
        )
        for offset, (value, doc_id, start, end, text) in enumerate(candidates)
    ]

import math


def validate(ranking, judgments, k):
    if not isinstance(k, int) or isinstance(k, bool) or k < 1:
        raise ValueError("positive integer cutoff required")
    if any((not isinstance(x, str) or not x for x in ranking)) or len(
        set(ranking)
    ) != len(ranking):
        raise ValueError("unique document ids required")
    if any(
        (
            not isinstance(v, int) or isinstance(v, bool) or (not 0 <= v <= 3)
            for v in judgments.values()
        )
    ):
        raise ValueError("integer relevance grades 0..3 required")
    return True


def precision_recall(ranking, judgments, k):
    validate(ranking, judgments, k)
    relevant = {key for key, value in judgments.items() if value > 0}
    hits = len(set(ranking[:k]) & relevant)
    return {"precision": hits / k, "recall": hits / len(relevant) if relevant else 0.0}


def rank_metrics(ranking, judgments, k):
    validate(ranking, judgments, k)
    rr = next(
        (1 / (i + 1) for i, key in enumerate(ranking[:k]) if judgments.get(key, 0) > 0),
        0.0,
    )
    dcg = sum(
        (
            (2 ** judgments.get(key, 0) - 1) / math.log2(i + 2)
            for i, key in enumerate(ranking[:k])
        )
    )
    ideal = sum(
        (
            (2**grade - 1) / math.log2(i + 2)
            for i, grade in enumerate(sorted(judgments.values(), reverse=True)[:k])
        )
    )
    return {"rr": rr, "ndcg": dcg / ideal if ideal else 0.0}


def compare_systems(systems, judgments, k):
    result = {}
    for name, queries in systems.items():
        if set(queries) != set(judgments):
            raise ValueError("systems must cover identical judged queries")
        rows = {
            q: {
                **precision_recall(queries[q], j, k),
                **rank_metrics(queries[q], j, k),
                "unjudged": sum((doc not in j for doc in queries[q][:k])),
            }
            for q, j in judgments.items()
        }
        means = {
            metric: sum((row[metric] for row in rows.values())) / len(rows)
            if rows
            else 0
            for metric in ("precision", "recall", "rr", "ndcg")
        }
        result[name] = {"queries": rows, "mean": means}
    return result

