package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"sort"
	"strconv"
	"sync"
	"time"
)

type Policy struct {
	BaseMS   int  `json:"baseMs"`
	MaxMS    int  `json:"maxMs"`
	Attempts int  `json:"attempts"`
	Jitter   bool `json:"jitter"`
	Seed     int  `json:"seed"`
}
type Attempt struct {
	Client int `json:"client"`
	Number int `json:"attempt"`
	AtMS   int `json:"atMs"`
	Status int `json:"status"`
}
type Report struct {
	SchemaVersion int       `json:"schemaVersion"`
	Mode          string    `json:"mode"`
	Clients       int       `json:"clients"`
	Calls         int       `json:"calls"`
	Successes     int       `json:"successes"`
	Retries       int       `json:"retries"`
	Timeline      []Attempt `json:"timeline"`
}

func Validate(p Policy) error {
	if p.BaseMS < 1 || p.MaxMS < p.BaseMS || p.MaxMS > 60000 || p.Attempts < 1 || p.Attempts > 10 {
		return errors.New("invalid bounded policy")
	}
	return nil
}
func Delay(p Policy, client, attempt int) int {
	cap := p.BaseMS
	for i := 1; i < attempt && cap < p.MaxMS; i++ {
		cap *= 2
		if cap > p.MaxMS {
			cap = p.MaxMS
		}
	}
	if p.Jitter {
		x := uint64(client+1)*1103515245 + uint64(attempt)*12345 + uint64(p.Seed)
		x ^= x >> 16
		x *= 2246822519
		x ^= x >> 13
		return int(x % uint64(cap+1))
	}
	return cap
}
func Replay(clients, failUntil, capacity int, p Policy, budget int) (Report, error) {
	r := Report{1, "deterministic-simulation", clients, 0, 0, 0, []Attempt{}}
	if Validate(p) != nil || clients < 0 || clients > 1000 || failUntil < 0 || capacity < 1 || budget < 0 {
		return r, errors.New("invalid replay inputs")
	}
	pending := []Attempt{}
	for i := 0; i < clients; i++ {
		pending = append(pending, Attempt{Client: i, Number: 1})
	}
	loads := map[int]int{}
	for len(pending) > 0 {
		sort.Slice(pending, func(i, j int) bool {
			if pending[i].AtMS != pending[j].AtMS {
				return pending[i].AtMS < pending[j].AtMS
			}
			return pending[i].Client < pending[j].Client
		})
		a := pending[0]
		pending = pending[1:]
		loads[a.AtMS]++
		a.Status = 503
		if a.AtMS >= failUntil && loads[a.AtMS] <= capacity {
			a.Status = 200
			r.Successes++
		}
		r.Calls++
		r.Timeline = append(r.Timeline, a)
		if a.Status != 200 && a.Number < p.Attempts && r.Retries < budget {
			r.Retries++
			pending = append(pending, Attempt{Client: a.Client, Number: a.Number + 1, AtMS: a.AtMS + Delay(p, a.Client, a.Number)})
		}
	}
	return r, nil
}

type Budget struct {
	mu        sync.Mutex
	remaining int
}

func NewBudget(n int) *Budget {
	if n < 0 {
		n = 0
	}
	return &Budget{remaining: n}
}
func (b *Budget) Take() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.remaining <= 0 {
		return false
	}
	b.remaining--
	return true
}
func ServerDelay(value string, now time.Time) (time.Duration, error) {
	if value == "" {
		return 0, nil
	}
	if n, e := strconv.ParseInt(value, 10, 32); e == nil {
		if n < 0 {
			return 0, errors.New("negative Retry-After")
		}
		return time.Duration(n) * time.Second, nil
	}
	t, e := http.ParseTime(value)
	if e != nil {
		return 0, e
	}
	if t.Before(now) {
		return 0, nil
	}
	return t.Sub(now), nil
}
func Fetch(ctx context.Context, client *http.Client, url string, id int, p Policy, budget *Budget) ([]Attempt, error) {
	if e := Validate(p); e != nil {
		return nil, e
	}
	if budget == nil {
		return nil, errors.New("shared budget required")
	}
	start := time.Now()
	out := []Attempt{}
	for n := 1; n <= p.Attempts; n++ {
		req, e := http.NewRequestWithContext(ctx, "GET", url, nil)
		if e != nil {
			return out, e
		}
		req.Header.Set("X-Client-ID", strconv.Itoa(id))
		resp, e := client.Do(req)
		a := Attempt{id, n, int(time.Since(start).Milliseconds()), 0}
		delay := time.Duration(Delay(p, id, n)) * time.Millisecond
		if e != nil {
			out = append(out, a)
			return out, e
		}
		a.Status = resp.StatusCode
		received, readErr := io.Copy(io.Discard, io.LimitReader(resp.Body, 65537))
		resp.Body.Close()
		out = append(out, a)
		if readErr != nil {
			return out, readErr
		}
		if received > 65536 {
			return out, errors.New("response exceeds 64 KiB")
		}
		if a.Status >= 200 && a.Status < 300 {
			return out, nil
		}
		if a.Status != 429 && a.Status != 502 && a.Status != 503 && a.Status != 504 {
			return out, errors.New("non-retryable HTTP status")
		}
		server, e := ServerDelay(resp.Header.Get("Retry-After"), time.Now())
		if e != nil {
			return out, e
		}
		if server > time.Duration(p.MaxMS)*time.Millisecond {
			return out, errors.New("server delay exceeds policy cap")
		}
		if server > delay {
			delay = server
		}
		if n == p.Attempts || !budget.Take() {
			break
		}
		timer := time.NewTimer(delay)
		select {
		case <-ctx.Done():
			timer.Stop()
			return out, ctx.Err()
		case <-timer.C:
		}
	}
	return out, errors.New("retry attempts or shared budget exhausted")
}
func Local(p Policy, clients, budget int) (Report, error) {
	if Validate(p) != nil || clients < 1 || clients > 1000 || budget < 0 {
		return Report{}, errors.New("invalid local policy or client budget")
	}
	var mu sync.Mutex
	seen := map[string]int{}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		seen[r.Header.Get("X-Client-ID")]++
		n := seen[r.Header.Get("X-Client-ID")]
		mu.Unlock()
		if n == 1 {
			w.Header().Set("Retry-After", "0")
			w.WriteHeader(503)
			fmt.Fprint(w, "busy")
			return
		}
		fmt.Fprint(w, "ready")
	}))
	defer server.Close()
	shared := NewBudget(budget)
	report := Report{1, "local-http-fixture", clients, 0, 0, 0, []Attempt{}}
	var wg sync.WaitGroup
	for i := 0; i < clients; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
			defer cancel()
			trace, e := Fetch(ctx, server.Client(), server.URL, id, p, shared)
			mu.Lock()
			report.Timeline = append(report.Timeline, trace...)
			report.Calls += len(trace)
			report.Retries += max(0, len(trace)-1)
			if e == nil {
				report.Successes++
			}
			mu.Unlock()
		}(i)
	}
	wg.Wait()
	sort.Slice(report.Timeline, func(i, j int) bool {
		a, b := report.Timeline[i], report.Timeline[j]
		if a.AtMS != b.AtMS {
			return a.AtMS < b.AtMS
		}
		return a.Client < b.Client
	})
	return report, nil
}
func main() {
	clients := flag.Int("clients", 20, "concurrent clients")
	budget := flag.Int("budget", 12, "shared retry attempts")
	seed := flag.Int("seed", 7, "jitter seed")
	jitter := flag.Bool("jitter", true, "spread retry delays")
	base := flag.Int("base-ms", 10, "initial backoff")
	cap := flag.Int("max-ms", 80, "maximum retry wait")
	attempts := flag.Int("attempts", 4, "maximum attempts per client")
	failure := flag.Int("fail-until-ms", 12, "simulated failure window")
	capacity := flag.Int("capacity", 5, "simulated capacity per exact millisecond")
	out := flag.String("out", "/tmp/aiefs-retry-report.json", "receipt path")
	live := flag.Bool("local-http", false, "run finite loopback fixture")
	flag.Parse()
	p := Policy{*base, *cap, *attempts, *jitter, *seed}
	var r Report
	var e error
	if *live {
		if *clients < 1 || *clients > 1000 || *budget < 0 {
			e = errors.New("invalid client or budget limit")
		} else {
			r, e = Local(p, *clients, *budget)
		}
	} else {
		r, e = Replay(*clients, *failure, *capacity, p, *budget)
	}
	if e != nil {
		fmt.Fprintln(os.Stderr, e)
		os.Exit(1)
	}
	data, _ := json.MarshalIndent(r, "", "  ")
	if e = os.WriteFile(*out, append(data, '\n'), 0600); e != nil {
		fmt.Fprintln(os.Stderr, e)
		os.Exit(1)
	}
	fmt.Println(string(data))
}

export function analyze(text: string) {
  const r = JSON.parse(text);
  if (
    r.schemaVersion !== 1 ||
    !["deterministic-simulation", "local-http-fixture"].includes(r.mode) ||
    !Number.isInteger(r.clients) ||
    r.clients < 0 ||
    !Array.isArray(r.timeline)
  )
    throw Error("invalid receipt");
  const per = new Map<number, number>(),
    bins = new Map<number, number>();
  let success = 0;
  const complete = new Set<number>();
  for (const a of r.timeline) {
    if (
      !Number.isInteger(a.client) ||
      a.client < 0 ||
      a.client >= r.clients ||
      !Number.isInteger(a.attempt) ||
      a.attempt !== (per.get(a.client) ?? 0) + 1 ||
      !Number.isInteger(a.atMs) ||
      a.atMs < 0 ||
      !Number.isInteger(a.status) ||
      a.status < 0 ||
      a.status > 599 ||
      complete.has(a.client)
    )
      throw Error("invalid attempt");
    per.set(a.client, a.attempt);
    bins.set(a.atMs, (bins.get(a.atMs) ?? 0) + 1);
    if (a.status >= 200 && a.status < 300) {
      success++;
      complete.add(a.client);
    }
  }
  const calls = r.timeline.length,
    retries = calls - per.size;
  if (
    r.calls !== calls ||
    r.successes !== success ||
    r.retries !== retries ||
    per.size !== r.clients
  )
    throw Error("counter mismatch");
  return {
    schemaVersion: 1,
    mode: r.mode,
    clients: r.clients,
    calls,
    retries,
    successes: success,
    amplification: r.clients ? calls / r.clients : 0,
    peakSameMillisecond: Math.max(0, ...bins.values()),
    timeline: [...bins]
      .sort((a, b) => a[0] - b[0])
      .map(([atMs, calls]) => ({ atMs, calls })),
  };
}

"""Send versioned JSON requests through the bounded Rust action loop."""

import argparse, json, subprocess, tempfile
from pathlib import Path

TOOLS = {
    "read": {
        "type": "object",
        "required": ["path"],
        "properties": {"path": {"type": "string"}},
    },
    "list": {"type": "object", "properties": {"path": {"type": "string"}}},
    "search": {
        "type": "object",
        "required": ["path", "pattern"],
        "properties": {"path": {"type": "string"}, "pattern": {"type": "string"}},
    },
    "help": {"type": "object"},
    "pwd": {"type": "object"},
    "quit": {"type": "object"},
}


def encode(request):
    if (
        not isinstance(request, dict)
        or not isinstance(request.get("id"), str)
        or not request["id"]
    ):
        raise ValueError("request id required")
    tool = request.get("tool")
    args = request.get("arguments", {})
    if tool not in TOOLS or not isinstance(args, dict):
        raise ValueError("known tool and object arguments required")
    if any(key not in args for key in TOOLS[tool].get("required", [])):
        raise ValueError("missing required tool argument")
    if set(args) - set(TOOLS[tool].get("properties", {})):
        raise ValueError("unknown tool argument")
    for value in args.values():
        if not isinstance(value, str) or any(ord(c) < 32 for c in value):
            raise ValueError("string arguments without control characters required")
    if tool == "search":
        return f"search {args['pattern']}\t{args['path']}"
    if tool in ("read", "list"):
        return f"{tool} {args.get('path', '.')}"
    return tool


def receipts(rows, stdout, reason, abnormal=False):
    responses = []
    protocol_error = False
    for line in stdout.splitlines(keepends=True):
        newline = b"\n" if isinstance(line, bytes) else "\n"
        if abnormal and not line.endswith(newline):
            reason += "; incomplete response discarded"
            break
        try:
            event = json.loads(line)
            if (
                not isinstance(event, dict)
                or type(event.get("seq")) is not int
                or event["seq"] < 0
                or event.get("kind") not in ("ok", "error", "rejected")
                or not isinstance(event.get("output"), str)
                or not isinstance(event.get("terminal"), bool)
            ):
                raise ValueError("invalid event fields")
        except (ValueError, UnicodeDecodeError):
            reason = f"invalid native response at position {len(responses) + 1}"
            protocol_error = True
            break
        responses.append(event)
    events = []
    for index, request in enumerate(rows):
        if index < len(responses):
            event = responses[index]
            if event["terminal"] and not protocol_error:
                reason = event.get("output", "session closed")
        else:
            event = {
                "seq": responses[-1]["seq"] if responses else 0,
                "kind": "not-executed",
                "output": "no response received: " + reason,
                "terminal": True,
            }
        events.append({**event, "schema_version": 1, "request_id": request["id"]})
    return events, protocol_error


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("workspace")
    parser.add_argument("requests")
    parser.add_argument("--limit", type=int, default=50)
    parser.add_argument("--out")
    args = parser.parse_args()
    rows = [
        json.loads(line)
        for line in Path(args.requests).read_text().splitlines()
        if line.strip()
    ]
    commands = [encode(row) for row in rows]
    if len({row["id"] for row in rows}) != len(rows):
        raise ValueError("duplicate request id")
    with tempfile.TemporaryDirectory(prefix="rust-shell-private-") as folder:
        binary = Path(folder) / "shell"
        subprocess.run(
            [
                "rustc",
                "--edition=2021",
                str(Path(__file__).with_name("main.rs")),
                "-o",
                str(binary),
            ],
            check=True,
            capture_output=True,
            text=True,
        )
        try:
            run = subprocess.run(
                [str(binary), args.workspace, str(args.limit)],
                input=("\n".join(commands) + ("\n" if commands else "")).encode("utf-8"),
                capture_output=True,
                timeout=30,
            )
            reason = run.stderr.decode("utf-8", errors="replace").strip() or "process ended"
            events, protocol_error = receipts(rows, run.stdout, reason, abnormal=bool(run.returncode))
            exit_code = 1 if run.returncode or protocol_error else 0
        except subprocess.TimeoutExpired as error:
            events, _ = receipts(rows, error.stdout or b"", "process timed out", abnormal=True)
            exit_code = 1
    payload = (
        "\n".join(json.dumps(event, ensure_ascii=False) for event in events)
        + ("\n" if events else "")
    )
    if args.out:
        Path(args.out).write_text(payload)
    print(payload, end="")
    return exit_code


if __name__ == "__main__":
    raise SystemExit(main())

// Streaming Agent Shell in Rust from the standard library.
// Stage contracts live under projects/rust-agent-shell/stages/.
// The default demo is bounded and uses only the local fixture.
// Official references are listed in README.md.

use std::fs;
use std::io::{self, BufRead, Read, Write};
use std::path::{Component, Path, PathBuf};
#[derive(Debug, Clone, PartialEq)]
pub enum Action {
    Help,
    Pwd,
    List(String),
    Read(String),
    Search { pattern: String, path: String },
    Quit,
}
pub fn parse_action(line: &str) -> Result<Action, String> {
    if line.len() > 4096 {
        return Err("command too long".into());
    }
    let text = line.trim();
    let (command, args) = text.split_once(' ').unwrap_or((text, ""));
    match command {
        "help" if args.is_empty() => Ok(Action::Help),
        "pwd" if args.is_empty() => Ok(Action::Pwd),
        "quit" if args.is_empty() => Ok(Action::Quit),
        "list" => Ok(Action::List(
            if args.is_empty() { "." } else { args }.into(),
        )),
        "read" if !args.is_empty() => Ok(Action::Read(args.into())),
        "search" => {
            let (pattern, file) = args
                .split_once('\t')
                .ok_or("search expects pattern<TAB>path")?;
            if pattern.is_empty() || file.is_empty() {
                return Err("empty search argument".into());
            }
            Ok(Action::Search {
                pattern: pattern.into(),
                path: file.into(),
            })
        }
        _ => Err("unsupported command".into()),
    }
}
pub fn contained(root: &Path, relative: &str) -> Result<PathBuf, String> {
    let rel = Path::new(relative);
    if relative.is_empty()
        || rel.is_absolute()
        || rel.components().any(|c| {
            matches!(
                c,
                Component::ParentDir | Component::RootDir | Component::Prefix(_)
            )
        })
    {
        return Err("unsafe path".into());
    }
    let target = root.join(rel).canonicalize().map_err(|e| e.to_string())?;
    if !target.starts_with(root) {
        return Err("path escapes root".into());
    }
    Ok(target)
}
pub fn read_text(file: &Path) -> Result<String, String> {
    let metadata = fs::metadata(file).map_err(|e| e.to_string())?;
    if !metadata.is_file() || metadata.len() > 16384 {
        return Err("file is not bounded text".into());
    }
    let mut bytes = Vec::new();
    fs::File::open(file)
        .map_err(|e| e.to_string())?
        .take(16385)
        .read_to_end(&mut bytes)
        .map_err(|e| e.to_string())?;
    if bytes.len() > 16384 {
        return Err("file grew beyond limit".into());
    }
    String::from_utf8(bytes).map_err(|_| "file is not UTF-8".into())
}
pub fn execute(root: &Path, action: &Action) -> Result<String, String> {
    match action {
        Action::Help => {
            Ok("help | pwd | list [path] | read path | search pattern<TAB>path | quit".into())
        }
        Action::Pwd => Ok(root.display().to_string()),
        Action::Quit => Ok("session closed".into()),
        Action::List(relative) => {
            let dir = contained(root, relative)?;
            let mut names = Vec::new();
            for entry in fs::read_dir(dir).map_err(|e| e.to_string())?.take(101) {
                let entry = entry.map_err(|e| e.to_string())?;
                names.push(entry.file_name().to_string_lossy().into_owned());
            }
            if names.len() > 100 {
                return Err("directory entry budget exceeded".into());
            }
            names.sort();
            Ok(names.join("\n"))
        }
        Action::Read(relative) => read_text(&contained(root, relative)?),
        Action::Search { pattern, path } => {
            let text = read_text(&contained(root, path)?)?;
            let matches: Vec<String> = text
                .lines()
                .enumerate()
                .filter(|(_, line)| line.contains(pattern))
                .take(50)
                .map(|(i, line)| format!("{}:{}", i + 1, line))
                .collect();
            Ok(matches.join("\n"))
        }
    }
}
pub fn json_string(value: &str) -> String {
    let mut out = String::from("\"");
    for ch in value.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
#[derive(Debug, Clone)]
pub struct Event {
    pub seq: usize,
    pub kind: String,
    pub output: String,
    pub terminal: bool,
}
impl Event {
    pub fn json(&self) -> String {
        format!(
            "{{\"seq\":{},\"kind\":{},\"output\":{},\"terminal\":{}}}",
            self.seq,
            json_string(&self.kind),
            json_string(&self.output),
            self.terminal
        )
    }
}
pub struct Session {
    pub root: PathBuf,
    pub steps: usize,
    pub limit: usize,
    pub closed: bool,
}
impl Session {
    pub fn new(root: &Path, limit: usize) -> Result<Self, String> {
        if limit == 0 || limit > 1000 {
            return Err("invalid action budget".into());
        }
        let root = root.canonicalize().map_err(|e| e.to_string())?;
        if !root.is_dir() {
            return Err("root is not directory".into());
        }
        Ok(Self {
            root,
            steps: 0,
            limit,
            closed: false,
        })
    }
    pub fn handle(&mut self, line: &str) -> Event {
        if self.closed {
            return Event {
                seq: self.steps,
                kind: "error".into(),
                output: "session already closed".into(),
                terminal: true,
            };
        }
        if self.steps >= self.limit {
            self.closed = true;
            return Event {
                seq: self.steps,
                kind: "error".into(),
                output: "action budget exhausted".into(),
                terminal: true,
            };
        }
        self.steps += 1;
        match parse_action(line) {
            Ok(action) => {
                let quit = action == Action::Quit;
                let result = execute(&self.root, &action);
                self.closed = quit;
                match result {
                    Ok(output) => Event {
                        seq: self.steps,
                        kind: "ok".into(),
                        output,
                        terminal: quit,
                    },
                    Err(error) => Event {
                        seq: self.steps,
                        kind: "error".into(),
                        output: error,
                        terminal: false,
                    },
                }
            }
            Err(error) => Event {
                seq: self.steps,
                kind: "rejected".into(),
                output: error,
                terminal: false,
            },
        }
    }
}
pub fn read_bounded<R: BufRead>(reader: &mut R) -> Result<Option<String>, String> {
    let mut out = Vec::new();
    loop {
        let buffer = reader.fill_buf().map_err(|e| e.to_string())?;
        if buffer.is_empty() {
            return if out.is_empty() {
                Ok(None)
            } else {
                String::from_utf8(out)
                    .map(Some)
                    .map_err(|_| "invalid UTF-8 command".into())
            };
        }
        let end = buffer.iter().position(|b| *b == b'\n');
        let count = end.map(|n| n + 1).unwrap_or(buffer.len());
        if out.len() + count > 4097 {
            return Err("command too long".into());
        }
        out.extend_from_slice(&buffer[..count]);
        reader.consume(count);
        if end.is_some() {
            while matches!(out.last(), Some(b'\n' | b'\r')) {
                out.pop();
            }
            return String::from_utf8(out)
                .map(Some)
                .map_err(|_| "invalid UTF-8 command".into());
        }
    }
}
pub fn run_loop<R: BufRead, W: Write>(
    session: &mut Session,
    reader: &mut R,
    writer: &mut W,
) -> Result<usize, String> {
    let mut emitted = 0;
    while let Some(line) = read_bounded(reader)? {
        let event = session.handle(&line);
        writeln!(writer, "{}", event.json()).map_err(|e| e.to_string())?;
        writer.flush().map_err(|e| e.to_string())?;
        emitted += 1;
        if event.terminal {
            break;
        }
    }
    Ok(emitted)
}
fn demo() -> Result<(), String> {
    let dir = std::env::temp_dir().join(format!("rust-agent-shell-demo-{}", std::process::id()));
    fs::create_dir(&dir).map_err(|e| e.to_string())?;
    let result = (|| {
        fs::write(
            dir.join("README.md"),
            "A bounded local agent shell.\nEvery read stays inside the workspace.\n",
        )
        .map_err(|e| e.to_string())?;
        let mut session = Session::new(&dir, 10)?;
        let script =
            b"help\nlist .\nread README.md\nsearch bounded\tREADME.md\nexec rm -rf /\nquit\n";
        println!("mode=actual Rust stdin action loop; commands use filesystem APIs, no OS shell");
        run_loop(
            &mut session,
            &mut io::Cursor::new(script),
            &mut io::stdout(),
        )
        .map(|_| ())
    })();
    let _ = fs::remove_dir_all(dir);
    result
}
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let result = if args.iter().any(|a| a == "--demo") {
        demo()
    } else {
        let root = args.get(1).map(String::as_str).unwrap_or(".");
        let limit = args
            .get(2)
            .map(|s| {
                s.parse::<usize>()
                    .map_err(|_| "invalid action budget".to_string())
            })
            .transpose();
        limit
            .and_then(|n| Session::new(Path::new(root), n.unwrap_or(50)))
            .and_then(|mut session| {
                run_loop(&mut session, &mut io::stdin().lock(), &mut io::stdout()).map(|_| ())
            })
    };
    if let Err(error) = result {
        eprintln!("error: {}", error);
        std::process::exit(1);
    }
}

