        },
    ]
}
pub fn satisfies(n: &Needs, p: &Profile) -> bool {
    (!(n.untrusted || n.secrets) || p.filesystem)
        && (!n.network || p.network)
        && (!n.host_kernel || p.kernel)
}

use super::*;
pub fn select(n: &Needs, candidates: &[Profile], budget: u32) -> Result<Profile, Error> {
    candidates
        .iter()
        .filter(|p| p.cost <= budget && satisfies(n, p))
        .min_by(|a, b| a.cost.cmp(&b.cost).then(a.name.cmp(&b.name)))
        .cloned()
        .ok_or(Error::Limit)
}

use super::*;
pub fn plan(n: &Needs, p: &Profile) -> Result<String, Error> {
    if !satisfies(n, p) {
        return Err(Error::Invalid("insufficient profile".into()));
    }
    let mut out = format!(
        "profile={} mode=policy-simulation os_isolation=false\n",
        p.name
    );
    if !p.kernel {
        out.push_str("residual=shared-host-kernel\n");
    }
    if !p.network {
        out.push_str("residual=network-not-denied\n");
    }
    out.push_str("verify=runtime-configuration-and-escape-tests\n");
    Ok(out)
}

"""Leakage-aware development split: identities, content and groups form components."""

import hashlib
import unicodedata


def fingerprint(text):
    return hashlib.sha256(
        " ".join(unicodedata.normalize("NFKC", text).casefold().split()).encode()
    ).hexdigest()


def split_cases(cases, holdout_fraction=0.25):
    if not 0 < holdout_fraction < 1:
        raise ValueError("fraction must lie inside zero and one")
    seen, parents, owners, labels = set(), {}, {}, {}

    def find(key):
        parents.setdefault(key, key)
        if parents[key] != key:
            parents[key] = find(parents[key])
        return parents[key]

    def union(a, b):
        a, b = find(a), find(b)
        parents[max(a, b)] = min(a, b)

    for case in cases:
        key, label, text = (case.get(k) for k in ("id", "label", "text"))
        if (
            not all(isinstance(x, str) and x.strip() for x in (key, label, text))
            or key in seen
        ):
            raise ValueError("unique id, text and label required")
        seen.add(key)
        find(key)
        content = fingerprint(text)
        if content in labels and labels[content] != label:
            raise ValueError("identical content has conflicting labels")
        labels[content] = label
        links = ["content:" + content]
        if case.get("group"):
            if not isinstance(case["group"], str):
                raise ValueError("group must be a string")
            links.append("group:" + case["group"])
        for link in links:
            if link in owners:
                union(key, owners[link])
            else:
                owners[link] = key
    members = {}
    for case in cases:
        members.setdefault(find(case["id"]), []).append(case)
    result = {"development": [], "holdout": []}
    for group in members.values():
        token = min(fingerprint(c["text"]) for c in group)
        score = int(token[:8], 16) / 2**32
        result["holdout" if score < holdout_fraction else "development"].extend(
            dict(c) for c in group
        )
    for rows in result.values():
        rows.sort(key=lambda c: c["id"])
    return result


def audit_partitions(development, holdout):
    a = {fingerprint(c["text"]) for c in development}
    b = {fingerprint(c["text"]) for c in holdout}
    ga = {c["group"] for c in development if c.get("group")}
    gb = {c["group"] for c in holdout if c.get("group")}
    result = {"content_leaks": sorted(a & b), "group_leaks": sorted(ga & gb)}
    result["usable"] = not result["content_leaks"] and not result["group_leaks"]
    return result

"""Propose rules from development errors only.

Lesson: projects/self-improving-skill-loop/stages/03-propose/docs/en.md
The implementation is original and uses explicit local data contracts.
Run its tests through scripts/project_test.py.
"""

from collections import defaultdict
import re
from skill import route


def propose(development, rules, min_support=2):
    if min_support < 1:
        raise ValueError("positive support required")
    labels = defaultdict(set)
    counts = defaultdict(int)
    for case in development:
        for word in set(re.findall(r"\w+", case["text"].casefold())) - {
            "a",
            "the",
            "please",
            "is",
            "my",
        }:
            labels[word].add(case["label"])
            counts[(word, case["label"])] += 1
    candidates = []
    for case in development:
        if route(case["text"], rules) == case["label"]:
            continue
        for word in sorted(set(re.findall(r"\w+", case["text"].casefold()))):
            if (
                labels[word] == {case["label"]}
                and counts[(word, case["label"])] >= min_support
            ):
                item = {"terms": [word], "label": case["label"]}
                if item not in rules and item not in candidates:
                    candidates.append(item)
    return [dict(rule) for rule in rules] + candidates

"""Execute and score a transparent routing skill.

Lesson: projects/self-improving-skill-loop/stages/02-skill/docs/en.md
The implementation is original and uses explicit local data contracts.
Run its tests through scripts/project_test.py.
"""

import re


def route(text, rules, default="unknown"):
    words = set(re.findall(r"\w+", text.casefold()))
    for rule in rules:
        terms = set(rule["terms"])
        if terms and terms <= words:
            return rule["label"]
    return default


def evaluate(cases, rules):
    rows = [
        {"id": c["id"], "expected": c["label"], "predicted": route(c["text"], rules)}
        for c in cases
    ]
    errors = [r for r in rows if r["expected"] != r["predicted"]]
    return {
        "total": len(rows),
        "accuracy": 1 - len(errors) / len(rows) if rows else 0.0,
        "errors": errors,
        "rows": rows,
    }

import math
import re
import unicodedata
from collections import Counter


def normalize(text, aliases=None):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    aliases = aliases or {}
    canonical = lambda value: unicodedata.normalize("NFC", value.casefold())
    if not isinstance(aliases, dict) or any(
        not isinstance(k, str) or not isinstance(v, str) for k, v in aliases.items()
    ):
        raise ValueError("aliases must map strings to strings")
    aliases = {canonical(k): canonical(v) for k, v in aliases.items()}
    return [aliases.get(word, word) for word in re.findall(r"\w+", canonical(text))]


def build_index(documents, aliases=None):
    if not isinstance(documents, dict) or any(
        (not isinstance(k, str) or not k for k in documents)
    ):
        raise ValueError("document ids must be nonempty strings")
    terms = {k: Counter(normalize(v, aliases)) for k, v in documents.items()}
    df = Counter((term for counts in terms.values() for term in counts))
    idf = {
        term: math.log((1 + len(terms)) / (1 + count)) + 1 for term, count in df.items()
    }
    vectors = {}
    for key, counts in terms.items():
        weighted = {term: count * idf[term] for term, count in counts.items()}
        norm = math.sqrt(sum((v * v for v in weighted.values())))
        vectors[key] = (
            {term: value / norm for term, value in weighted.items()} if norm else {}
        )
    return {"vectors": vectors, "idf": idf, "aliases": dict(aliases or {})}


def search(index, query, k=3):
    if not isinstance(k, int) or k < 1:
        raise ValueError("k must be positive")
    counts = Counter(normalize(query, index["aliases"]))
    values = {
        term: count * index["idf"][term]
        for term, count in counts.items()
        if term in index["idf"]
    }
    norm = math.sqrt(sum((v * v for v in values.values())))
    if not norm:
        return []
    results = []
    for key, vector in index["vectors"].items():
        score = sum(
            (value / norm * vector.get(term, 0) for term, value in values.items())
        )
        if score > 0:
            results.append(
                {
                    "id": key,
                    "score": round(score, 6),
                    "matched": sorted(set(values) & set(vector)),
                }
            )
    return sorted(results, key=lambda row: (-row["score"], row["id"]))[:k]


def evaluate(index, cases, k=3):
    if any((c["expected"] not in index["vectors"] for c in cases)):
        raise ValueError("unknown labeled document")
    hits = sum(
        (
            any((r["id"] == c["expected"] for r in search(index, c["query"], k)))
            for c in cases
        )
    )
    return {
        "hits": hits,
        "total": len(cases),
        "recall": hits / len(cases) if cases else 0.0,
    }

import html
import ipaddress
import json
import re


EMAIL = re.compile(
    r"(?<![\w.!#$%&'*+/=?^_`{|}~-])[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?\.[A-Za-z]{2,}(?![\w-]|\.[\w-])"
)
IPV4 = re.compile(r"(?<![\w.])(?:[0-9]{1,3}\.){3}[0-9]{1,3}(?!\w|\.\w)")


def detect(text, literals=()):
    if not isinstance(text, str) or len(text) > 1_000_000:
        raise ValueError("text must be a string of at most 1000000 characters")
    if not isinstance(literals, (list, tuple)) or len(literals) > 100:
        raise ValueError("literals must contain at most 100 strings")
    if any(
        not isinstance(value, str) or not value or len(value) > 256
        for value in literals
    ):
        raise ValueError("each literal must contain 1 to 256 characters")
    found = []

    def add(start, end, kind):
        if len(found) >= 10000:
            raise ValueError("text exceeds the 10000-match limit")
        found.append({"start": start, "end": end, "kind": kind})

    for kind, pattern in (("EMAIL", EMAIL), ("IPV4", IPV4)):
        for match in pattern.finditer(text):
            if kind == "IPV4":
                try:
                    ipaddress.IPv4Address(match.group())
                except ValueError:
                    continue
            add(match.start(), match.end(), kind)
    for literal in sorted(set(literals)):
        offset = 0
        while True:
            start = text.find(literal, offset)
            if start < 0:
                break
            add(start, start + len(literal), "LITERAL")
            offset = start + 1
    return sorted(found, key=lambda span: (span["start"], span["end"], span["kind"]))


def merge_spans(spans, text_length):
    if type(text_length) is not int or text_length < 0 or not isinstance(spans, list):
        raise ValueError("invalid span collection")
    normalized = []
    for span in spans:
        if not isinstance(span, dict) or set(span) != {"start", "end", "kind"}:
            raise ValueError("span needs start, end and kind")
        start, end, kind = span["start"], span["end"], span["kind"]
        if (
            type(start) is not int
            or type(end) is not int
            or not 0 <= start < end <= text_length
        ):
            raise ValueError("span offsets are outside the text")
        if kind not in {"EMAIL", "IPV4", "LITERAL"}:
            raise ValueError("unknown detector kind")
        normalized.append({"start": start, "end": end, "kinds": [kind]})
    result = []
    for span in sorted(normalized, key=lambda item: (item["start"], item["end"])):
        if result and span["start"] < result[-1]["end"]:
            result[-1]["end"] = max(result[-1]["end"], span["end"])
            result[-1]["kinds"] = sorted(set(result[-1]["kinds"] + span["kinds"]))
        else:
            result.append(span)
    return result


def redact(text, literals=()):
    spans = merge_spans(detect(text, literals), len(text))
    parts, cursor, receipts = [], 0, []
    for number, span in enumerate(spans, 1):
        parts.extend([text[cursor : span["start"]], "[REDACTED]"])
        receipts.append(
            {
                "index": number,
                "start": span["start"],
                "end": span["end"],
                "kinds": span["kinds"],
            }
        )
        cursor = span["end"]
    parts.append(text[cursor:])
    return {
        "text": "".join(parts),
        "spans": receipts,
        "redacted_characters": sum(s["end"] - s["start"] for s in spans),
    }


def process(records, literals=()):
    if not isinstance(records, list) or len(records) > 10000:
        raise ValueError("records must be an array with at most 10000 rows")
    detect("", literals)
    result, ledger, seen = [], [], set()
    for number, record in enumerate(records, 1):
        if not isinstance(record, dict) or set(record) != {"id", "text"}:
            raise ValueError(f"row {number}: expected only id and text")
        identity = record["id"]
        if not isinstance(identity, str) or not re.fullmatch(
            r"[A-Za-z0-9_-]{1,64}", identity
        ):
            raise ValueError(f"row {number}: use a non-sensitive alphanumeric id")
        if identity in seen:
            raise ValueError(f"row {number}: duplicate id")
        seen.add(identity)
        redacted = redact(record["text"], literals)
        result.append({"id": identity, "text": redacted["text"]})
        ledger.append(
            {
                "id": identity,
                "spans": redacted["spans"],
                "redacted_characters": redacted["redacted_characters"],
            }
        )
    return {
        "schema_version": 1,
        "records": result,
        "ledger": ledger,
        "totals": {
            "records": len(records),
            "spans": sum(len(row["spans"]) for row in ledger),
            "redacted_characters": sum(row["redacted_characters"] for row in ledger),
        },
        "scope": "ASCII email patterns, valid IPv4 addresses and exact configured literals only; review remaining text before sharing.",
    }


def render_html(report):
    rows = "".join(
        f"<tr><td>{html.escape(row['id'])}</td><td>{html.escape(row['text'])}</td></tr>"
        for row in report["records"]
    )
    ledger = html.escape(json.dumps(report["ledger"], indent=2))
    return f"""<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sensitive text redaction gate</title>
<style>:root{{color-scheme:light dark}}body{{font:17px system-ui;max-width:960px;margin:32px auto;padding:0 18px;line-height:1.6}}table{{width:100%;border-collapse:collapse}}td,th{{padding:12px;border-bottom:1px solid #888;text-align:left;overflow-wrap:anywhere}}th:first-child,td:first-child{{min-width:4.5em;overflow-wrap:normal}}pre{{white-space:pre-wrap;overflow-wrap:anywhere}}button{{font:inherit;padding:8px}}h1{{line-height:1.2}}</style>
<h1>Sensitive text redaction gate</h1><p>{html.escape(report["scope"])}</p><p id="counts">{report["totals"]["spans"]} spans replaced across {report["totals"]["records"]} records.</p>
<table><thead><tr><th>Record</th><th>Redacted text</th></tr></thead><tbody>{rows}</tbody></table><details><summary>Inspect offset receipts</summary><pre>{ledger}</pre></details>
<p>The original text and literal dictionary are absent from this page. Record IDs are caller-supplied and must be non-sensitive.</p></html>"""

