    for (const line of header[1].split("\n")) {
      const match = line.match(/^(name|description):\s*(.+)$/);
      if (match) {
        if (fields[match[1]]) throw new Error("duplicate metadata");
        fields[match[1]] = match[2].startsWith('"')
