    schema_version: 1,
    ...route(
      await loadCatalog(folder),
      request.query,
      request.files ?? [],
      request.allowed ?? [],
      request.margin ?? 1,
    ),
  };
}
if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href
) {
  try {
    console.log(JSON.stringify(await execute(process.argv.slice(2)), null, 2));
  } catch (e) {
    console.error((e as Error).message);
    process.exitCode = 1;
  }
}

