use super::*;
pub fn spans(text: &str, max_bytes: usize) -> Result<Vec<Span>, Error> {
    if text.len() > max_bytes {
        return Err(Error::Limit);
    }
    let mut offset = 0;
    let mut out = Vec::new();
    for (i, raw) in text.split_inclusive('\n').enumerate() {
        let clean = raw
            .strip_suffix('\n')
            .unwrap_or(raw)
            .strip_suffix('\r')
            .unwrap_or(raw.strip_suffix('\n').unwrap_or(raw));
        out.push(Span {
            line: i + 1,
            start: offset,
            end: offset + clean.len(),
            text: clean.into(),
        });
        offset += raw.len();
    }
    Ok(out)
}

use super::*;
pub fn scan(lines: &[Span]) -> Vec<Finding> {
    let mut out = Vec::new();
    for s in lines {
        let t = s.text.to_lowercase();
        let mut rules = Vec::new();
        if t.contains("ignore previous") || t.contains("ignore all instructions") {
            rules.push(("instruction-override", 3));
        }
        if t.contains(".ssh/") || t.contains(".env") {
            rules.push(("secret-access", 2));
        }
        if (t.contains("curl ") || t.contains("wget "))
            && (t.contains("http://") || t.contains("https://"))
        {
            rules.push(("network-command", 2));
        }
        for (rule, severity) in rules {
            out.push(Finding {
                rule: rule.into(),
                severity,
                line: s.line,
                start: s.start,
                end: s.end,
            });
        }
    }
    out
}

use super::*;
pub fn risk_score(findings: &[Finding]) -> Result<u32, Error> {
    let mut seen = std::collections::BTreeSet::new();
    let mut score = 0u32;
    for f in findings {
        if f.line == 0 || f.start > f.end || !(1..=3).contains(&f.severity) {
            return Err(Error::Invalid("invalid finding".into()));
        }
        if seen.insert((f.rule.clone(), f.line)) {
            score = score.checked_add(f.severity).ok_or(Error::Limit)?;
        }
    }
    Ok(score)
}

use super::*;
pub fn review(
    text: &str,
    findings: &[Finding],
    threshold: u32,
    max_findings: usize,
) -> Result<String, Error> {
    if threshold == 0 {
        return Err(Error::Invalid("threshold must be positive".into()));
    }
    if findings.len() > max_findings {
        return Err(Error::Limit);
    }
    let score = risk_score(findings)?;
    let mut out = format!(
        "state={} score={} advisory=true\n",
        if score >= threshold {
            "review-required"
        } else {
            "below-threshold"
        },
        score
    );
    for f in findings {
        let quote = text
            .get(f.start..f.end)
            .ok_or_else(|| Error::Invalid("invalid source slice".into()))?;
        out.push_str(&format!("line {} {} {:?}\n", f.line, f.rule, quote));
    }
    Ok(out)
}

