use super::*;
pub fn parse(text: &str) -> Result<std::collections::BTreeMap<String, String>, Error> {
    let lines: Vec<&str> = text.lines().collect();
    if lines.first() != Some(&"---") {
        return Err(Error::Invalid("missing frontmatter".into()));
    }
    let end = lines
        .iter()
        .skip(1)
        .position(|x| *x == "---")
        .ok_or_else(|| Error::Invalid("unclosed frontmatter".into()))?
        + 1;
    let mut result = std::collections::BTreeMap::new();
    for line in &lines[1..end] {
        if line.trim().is_empty() {
            continue;
        }
        let (key, value) = line
            .split_once(':')
            .ok_or_else(|| Error::Invalid("expected key: value".into()))?;
        let key = key.trim();
        let value = value.trim();
        if key.is_empty()
            || value.is_empty()
            || value.starts_with(['!', '&', '*', '|', '>', '[', '{', '\''])
        {
            return Err(Error::Invalid("unsupported YAML syntax".into()));
        }
        let value = if value.starts_with('"') {
            quoted_scalar(value)?
        } else {
            value.to_string()
        };
        if result.insert(key.into(), value).is_some() {
            return Err(Error::Conflict);
        }
    }
    result.insert("$body".into(), lines[end + 1..].join("\n"));
    Ok(result)
}

fn quoted_scalar(text: &str) -> Result<String, Error> {
    let fail = || Error::Invalid("invalid quoted scalar".into());
    if !text.ends_with('"') || text.len() < 2 {
        return Err(fail());
    }
    let mut chars = text[1..text.len() - 1].chars();
    let mut out = String::new();
    while let Some(ch) = chars.next() {
        if ch == '"' || ch.is_control() {
            return Err(fail());
        }
        if ch != '\\' {
            out.push(ch);
            continue;
        }
        match chars.next().ok_or_else(fail)? {
            '"' => out.push('"'),
            '\\' => out.push('\\'),
            '/' => out.push('/'),
            'n' => out.push('\n'),
            'r' => out.push('\r'),
            't' => out.push('\t'),
            'b' => out.push('\u{8}'),
            'f' => out.push('\u{c}'),
            'u' => {
                let hex: String = chars.by_ref().take(4).collect();
                if hex.len() != 4 {
                    return Err(fail());
                }
                let mut code = u32::from_str_radix(&hex, 16).map_err(|_| fail())?;
                if (0xd800..=0xdbff).contains(&code) {
                    if chars.next() != Some('\\') || chars.next() != Some('u') {
                        return Err(fail());
                    }
                    let low: String = chars.by_ref().take(4).collect();
                    if low.len() != 4 {
                        return Err(fail());
                    }
                    let low = u32::from_str_radix(&low, 16).map_err(|_| fail())?;
                    if !(0xdc00..=0xdfff).contains(&low) {
                        return Err(fail());
                    }
                    code = 0x10000 + ((code - 0xd800) << 10) + (low - 0xdc00);
                }
                out.push(char::from_u32(code).ok_or_else(fail)?);
            }
            _ => return Err(fail()),
        }
    }
    Ok(out)
}

use super::*;
pub fn validate(
    fields: &std::collections::BTreeMap<String, String>,
    directory: &str,
) -> Result<Skill, Error> {
    let name = fields
        .get("name")
        .ok_or_else(|| Error::Invalid("name required".into()))?;
    let desc = fields
        .get("description")
        .ok_or_else(|| Error::Invalid("description required".into()))?;
    if name.is_empty()
        || name.len() > 64
        || name.starts_with('-')
        || name.ends_with('-')
        || name.contains("--")
        || !name
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
    {
        return Err(Error::Invalid("invalid name".into()));
    }
    if name != directory {
        return Err(Error::Conflict);
    }
    if desc.trim().is_empty() || desc.chars().count() > 1024 {
        return Err(Error::Invalid("invalid description".into()));
    }
    Ok(Skill {
        name: name.clone(),
        description: desc.clone(),
        body: fields.get("$body").cloned().unwrap_or_default(),
    })
}

use super::*;
pub fn reference_path(root: &std::path::Path, resource: &str) -> Result<std::path::PathBuf, Error> {
    use std::path::Component;
    let rel = std::path::Path::new(resource);
    if resource.is_empty()
        || resource.contains('\\')
        || rel.components().any(|c| !matches!(c, Component::Normal(_)))
    {
        return Err(Error::Invalid("relative resource required".into()));
    }
    let base = root.canonicalize().map_err(|e| Error::Io(e.to_string()))?;
    let target = base
        .join(rel)
        .canonicalize()
        .map_err(|e| Error::Io(e.to_string()))?;
    if !target.starts_with(base) {
        return Err(Error::Invalid("resource escapes root".into()));
    }
    Ok(target)
}

use super::*;
pub fn disclose(skill: &Skill, activate: bool, budget: usize) -> Result<String, Error> {
    let mut text = format!("{}: {}", skill.name, skill.description);
    if activate && !skill.body.is_empty() {
        text.push_str("\n\n");
        text.push_str(&skill.body);
    }
    if text.chars().count() > budget {
        return Err(Error::Limit);
    }
    Ok(text)
}

