import re, hashlib, json


def _seconds(stamp):
    match = re.fullmatch("(?:(\\d{2,}):)?([0-5]\\d):([0-5]\\d)\\.(\\d{3})", stamp)
    if not match:
        raise ValueError("invalid WebVTT timestamp")
    h, m, s, ms = match.groups()
    return int(h or 0) * 3600 + int(m) * 60 + int(s) + int(ms) / 1000


def parse_vtt(text):
    """Parse UTF-8 WebVTT text into cues {id,start,end,settings,text,duration}. Preserve timestamp strings and supplied IDs; assign cue-N to absent IDs. Allow overlapping cues with nondecreasing starts. Ignore NOTE blocks; reject STYLE/REGION blocks and malformed/duplicate/empty cues."""
    text = text.lstrip("\ufeff").replace("\r\n", "\n").replace("\r", "\n")
    blocks = re.split("\\n\\s*\\n", text.strip())
    if not blocks or not re.fullmatch("WEBVTT(?:[ \\t].*)?", blocks[0]):
        raise ValueError("WEBVTT header required on its own block")
    out = []
    seen = set()
    last = -1
    for block in blocks[1:]:
        lines = block.split("\n")
        if lines[0] == "NOTE" or lines[0].startswith(("NOTE ", "NOTE\t")):
            continue
        if lines[0] in ("STYLE", "REGION"):
            raise ValueError("STYLE and REGION are outside the supported subset")
        if "-->" in lines[0]:
            id = "cue-" + str(len(out) + 1)
        else:
            id = lines.pop(0)
        if not lines:
            raise ValueError("missing cue timing")
        timing = re.fullmatch("(\\S+)\\s+-->\\s+(\\S+)(?:[ \\t]+(.*))?", lines.pop(0))
        if (
            not timing
            or not id
            or id in seen
            or (not lines)
            or (not "\n".join(lines).strip())
        ):
            raise ValueError("malformed or duplicate cue")
        start, end, settings = timing.groups()
        a, b = (_seconds(start), _seconds(end))
        if b <= a or a < last:
            raise ValueError("invalid cue interval or order")
        last = a
        seen.add(id)
        out.append(
            {
                "id": id,
                "start": start,
                "end": end,
                "settings": settings or "",
                "text": "\n".join(lines),
                "duration": round(b - a, 3),
            }
        )
    return out


def propose(cues, translations, glossary):
    """Return cue proposals with proposed text, needs_translation and required_terms. translations maps known cue IDs to nonempty target text. glossary maps source phrases to required target phrases; replace residual source terms longest-first in supplied proposals. Missing translations retain source text and remain unapproved."""
    known = {c["id"] for c in cues}
    if not set(translations) <= known or any(
        (
            not isinstance(v, str)
            or not v.strip()
            or re.search(r"\n\s*\n", v)
            or "\r" in v
            or ("-->" in v)
            for v in translations.values()
        )
    ):
        raise ValueError("invalid translation")
    if any(
        (
            not isinstance(k, str) or not k or (not isinstance(v, str)) or (not v)
            for k, v in glossary.items()
        )
    ):
        raise ValueError("invalid glossary")
    out = []
    for c in cues:
        text = translations.get(c["id"], c["text"])
        required = []
        for source, target in sorted(glossary.items(), key=lambda p: -len(p[0])):
            pattern = "(?<!\\w)" + re.escape(source) + "(?!\\w)"
            if re.search(pattern, c["text"], re.I):
                required.append(target)
                if c["id"] in translations:
                    text = re.sub(pattern, lambda _: target, text, flags=re.I)
        out.append(
            {
                **c,
                "proposed": text,
                "needs_translation": c["id"] not in translations,
                "required_terms": required,
            }
        )
    return out


def inspect(proposals, cps=17):
    """Return review rows with characters, cps, budget and flags. Count visible non-whitespace Unicode code points after stripping cue tags; budget=floor(duration*cps). Flags identify missing translations, missing required terms and reading-budget overflow. cps must be positive and finite."""
    import math

    if not isinstance(cps, (int, float)) or not math.isfinite(cps) or cps <= 0:
        raise ValueError("invalid reading budget")
    rows = []
    for p in proposals:
        visible = re.sub("<[^>]*>", "", p["proposed"])
        characters = len(re.sub("\\s", "", visible))
        budget = math.floor(p["duration"] * cps)
        flags = []
        if p["needs_translation"]:
            flags.append("translation_missing")
        if any(
            (t.casefold() not in p["proposed"].casefold() for t in p["required_terms"])
        ):
            flags.append("glossary_missing")
        if characters > budget:
            flags.append("over_budget")
        rows.append(
            {
                **p,
                "characters": characters,
                "cps": round(characters / p["duration"], 2),
                "budget": budget,
                "flags": flags,
            }
        )
    return rows


def export_localized(proposals, decisions=None, cps=17):
    """Return {schema_version,fingerprint,cues,all_reviewed,vtt}. Review {fingerprint,cues:{id:{text,approved,override_budget?}}} is bound to proposals and reading budget. Approved text must satisfy glossary and structural syntax; over-budget approval needs explicit override_budget=true. vtt is None until every cue is approved."""
    fingerprint = hashlib.sha256(
        json.dumps({"proposals": proposals, "cps": cps}, sort_keys=True).encode()
    ).hexdigest()
    edits = (decisions or {}).get("cues", {})
    if decisions is not None and decisions.get("fingerprint") != fingerprint:
        raise ValueError("stale review")
    if not set(edits) <= {p["id"] for p in proposals}:
        raise ValueError("unknown cue decision")
    resolved = []
    for p in proposals:
        d = edits.get(p["id"], {})
        text = d.get("text", p["proposed"])
        approved = d.get("approved", False)
        if (
            not isinstance(text, str)
            or not text.strip()
            or re.search(r"\n\s*\n", text)
            or ("\r" in text)
            or ("-->" in text)
            or (type(approved) is not bool)
        ):
            raise ValueError("invalid reviewed cue")
        row = inspect(
            [
                {
                    **p,
                    "proposed": text,
                    "needs_translation": p["needs_translation"] and (not approved),
                }
            ],
            cps,
        )[0]
        if approved and (
            "glossary_missing" in row["flags"]
            or ("over_budget" in row["flags"] and d.get("override_budget") is not True)
        ):
            raise ValueError("resolve glossary or acknowledge reading-budget overflow")
        resolved.append(
            {
                **row,
                "approved": approved,
                "override_budget": d.get("override_budget", False),
            }
        )
    complete = bool(resolved) and all((r["approved"] for r in resolved))
    vtt = None
    if complete:
        vtt = (
            "WEBVTT\n\n"
            + "\n\n".join(
                (
                    r["id"]
                    + "\n"
                    + r["start"]
                    + " --> "
                    + r["end"]
                    + (" " + r["settings"] if r["settings"] else "")
                    + "\n"
                    + r["proposed"]
                    for r in resolved
                )
            )
            + "\n"
        )
    return {
        "schema_version": 1,
        "fingerprint": fingerprint,
        "cues": resolved,
        "all_reviewed": complete,
        "vtt": vtt,
    }

"""Record allowed handoff state transitions.

Lesson: projects/support-agent-with-google-adk/stages/03-handoff/docs/en.md
The implementation is original and uses explicit local data contracts.
Run its tests through scripts/project_test.py.
"""

from routing import route


def begin(ticket):
    return {
        "ticket_id": ticket["id"],
        "state": "received",
        "route": None,
        "history": [],
    }


def transition(session, event, payload=None):
    allowed = {
        "received": {"classify": "routed"},
        "routed": {"respond": "answered", "escalate": "escalated"},
        "answered": {},
        "escalated": {},
    }
    if event not in allowed.get(session["state"], {}):
        raise ValueError("invalid ticket transition")
    next_state = {**session, "history": list(session["history"])}
    if event == "classify":
        next_state["route"] = route(payload or "")
    if event == "respond" and session["route"] == "human":
        raise ValueError("human route requires escalation")
    if event == "respond" and (not isinstance(payload, str) or not payload.strip()):
        raise ValueError("response text required")
    if event == "respond":
        next_state["response"] = payload.strip()
    if event == "escalate":
        next_state["escalation_reason"] = payload or "Human review required"
    next_state["state"] = allowed[session["state"]][event]
    next_state["history"].append({"event": event, "state": next_state["state"]})
    return next_state

"""Route tickets and enforce specialist capabilities.

Lesson: projects/support-agent-with-google-adk/stages/02-routing/docs/en.md
The implementation is original and uses explicit local data contracts.
Run its tests through scripts/project_test.py.
"""

import re

ROUTES = {
    "billing": {"invoice", "refund", "payment"},
    "access": {"password", "login", "account"},
    "platform": {"outage", "latency", "error"},
}
TOOLS = {
    "billing": {"read_invoice"},
    "access": {"read_account"},
    "platform": {"read_status"},
}


def route(text):
    words = set(re.findall(r"\w+", text.lower()))
    scores = sorted(
        ((len(words & terms), name) for name, terms in ROUTES.items()),
        key=lambda pair: (-pair[0], pair[1]),
    )
    if not scores[0][0] or len(scores) > 1 and scores[0][0] == scores[1][0]:
        return "human"
    return scores[0][1]


def authorize(specialist, tool):
    return tool in TOOLS.get(specialist, set())

from pathlib import Path
import os
import re
import signal
import stat
import subprocess
import sys
import tempfile


def safe_path(workspace, relative):
    root = Path(workspace).resolve()
    candidate = Path(relative)
    if candidate.is_absolute() or ".." in candidate.parts:
        raise ValueError("relative workspace path required")
    target = (root / candidate).resolve()
    if not target.is_relative_to(root) or not target.is_file():
        raise ValueError("workspace file required")
    return target


def apply_patch(workspace, relative, old, new):
    target = safe_path(workspace, relative)
    if not isinstance(old, str) or not old or (not isinstance(new, str)):
        raise ValueError("nonempty old text and string replacement required")
    content = target.read_text()
    if content.count(old) != 1:
        raise ValueError("patch must match exactly once")
    permissions = stat.S_IMODE(target.stat().st_mode)
    name = None
    try:
        with tempfile.NamedTemporaryFile("w", dir=target.parent, delete=False) as temporary:
            name = temporary.name
            temporary.write(content.replace(old, new, 1))
        os.chmod(name, permissions)
        os.replace(name, target)
    finally:
        if name is not None and os.path.exists(name):
            os.unlink(name)
    return {"path": relative, "replacements": 1}


def run_tests(workspace, timeout=5):
    root = Path(workspace).resolve()
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        raise ValueError("positive timeout required")
    if not (root / "tests").is_dir():
        return {
            "state": "failed",
            "passed": False,
            "tests": 0,
            "output": "missing tests directory",
        }
    env = {**os.environ, "PYTHONDONTWRITEBYTECODE": "1", "PYTHONPATH": str(root)}
    try:
        process = subprocess.Popen(
            [sys.executable, "-B", "-m", "unittest", "discover", "-s", "tests"],
            cwd=root,
            env=env,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            start_new_session=True,
        )
        stdout, stderr = process.communicate(timeout=timeout)
        result = subprocess.CompletedProcess(
            process.args, process.returncode, stdout, stderr
        )
    except subprocess.TimeoutExpired:
        os.killpg(process.pid, signal.SIGKILL)
        process.communicate()
        return {
            "state": "timeout",
            "passed": False,
            "tests": 0,
            "output": "test time budget exhausted",
        }
    output = result.stdout + result.stderr
    summary = re.search(
        r"^Ran (\d+) tests? in [^\n]+\n\n"
        r"(OK|FAILED|NO TESTS RAN)(?: \(([^\n]*)\))?\s*\Z",
        result.stderr,
        re.MULTILINE,
    )
    tests = int(summary.group(1)) if summary else 0
    skipped = (
        re.search(r"\bskipped=(\d+)\b", summary.group(3) or "") if summary else None
    )
    passed = bool(
        result.returncode == 0
        and summary
        and summary.group(2) == "OK"
        and tests > 0
        and not (skipped and int(skipped.group(1)) > 0)
    )
    return {
        "state": "passed" if passed else "failed",
        "passed": passed,
        "tests": tests,
        "output": output,
    }


def agent_loop(workspace, actions, max_steps=6):
    if not isinstance(max_steps, int) or max_steps < 1:
        raise ValueError("positive step budget required")
    trace = []
    for action in actions[:max_steps]:
        try:
            if action.get("tool") == "patch":
                result = apply_patch(
                    workspace, action["path"], action["old"], action["new"]
                )
            elif action.get("tool") == "test":
                result = run_tests(workspace)
            else:
                raise ValueError("unknown tool")
        except (ValueError, KeyError, OSError) as error:
            trace.append({"tool": action.get("tool"), "error": str(error)})
            return {"state": "failed", "trace": trace}
        trace.append({"tool": action["tool"], "result": result})
        if action["tool"] == "test" and result["passed"]:
            return {"state": "completed", "trace": trace}
    return {
        "state": "budget_exhausted" if len(actions) >= max_steps else "failed",
        "trace": trace,
    }


def drive(workspace, planner, max_steps=6):
    """Call the planner after every observation. Tests are executable trusted code."""
    if not isinstance(max_steps, int) or max_steps < 1:
        raise ValueError("positive step budget required")
    trace = []
    for step in range(max_steps):
        action = planner(tuple(trace))
        if action is None:
            return {"state": "failed", "reason": "planner abstained", "trace": trace}
        result = agent_loop(workspace, [action], 1)
        for row in result["trace"]:
            row["action"] = action
        trace.extend(result["trace"])
        if result["state"] == "completed":
            return {"state": "completed", "trace": trace}
        if any("error" in row for row in result["trace"]):
            return {"state": "failed", "trace": trace}
    return {"state": "budget_exhausted", "trace": trace}


def proposal_planner(proposals):
    """Select an exact repair only when its failure marker appears in a test result."""

    def json_key(action):
        return tuple(action.get(key) for key in ("path", "old", "new"))

    def choose(trace):
        if not trace or trace[-1]["tool"] == "patch":
            return {"tool": "test"}
        output = trace[-1].get("result", {}).get("output", "")
        used = {
            json_key(row.get("action", {})) for row in trace if row["tool"] == "patch"
        }
        for proposal in proposals:
            if (
                proposal["failure_contains"] in output
                and json_key(
                    {
                        "path": proposal["path"],
                        "old": proposal["old"],
                        "new": proposal["new"],
                    }
                )
                not in used
            ):
                return {
                    "tool": "patch",
                    "path": proposal["path"],
                    "old": proposal["old"],
                    "new": proposal["new"],
                }
        return None

    return choose

