use super::*;
pub fn call(line: &str, max_bytes: usize) -> Result<Call, Error> {
    if line.len() > max_bytes {
        return Err(Error::Limit);
    }
    if line.chars().any(|c| c.is_control()) {
        return Err(Error::Invalid("control character".into()));
    }
    let p: Vec<&str> = line.split('|').collect();
    if p.len() != 4 || p.iter().any(|s| s.is_empty()) {
        return Err(Error::Invalid("id|role|tool|argument required".into()));
    }
    Ok(Call {
        id: p[0].into(),
        role: p[1].into(),
        tool: p[2].into(),
        argument: p[3].into(),
    })
}

use super::*;
pub fn decide(c: &Call) -> Decision {
    if !matches!(c.role.as_str(), "reader" | "editor") {
        return Decision::Deny;
    }
    let p = std::path::Path::new(&c.argument);
    if c.argument.starts_with('.')
        || c.argument.contains('\\')
        || p.components()
            .any(|x| !matches!(x, std::path::Component::Normal(_)))
    {
        return Decision::Deny;
    }
    match (c.role.as_str(), c.tool.as_str()) {
        (_, "read") => Decision::Allow,
        ("editor", "write") => Decision::ApprovalRequired,
        _ => Decision::Deny,
    }
}

use super::*;
pub fn authorize(c: &Call, approval: Option<&mut Approval>) -> Result<(), Error> {
    match decide(c) {
        Decision::Deny => Err(Error::Invalid("policy denied".into())),
        Decision::Allow => Ok(()),
        Decision::ApprovalRequired => {
            let a = approval.ok_or_else(|| Error::Invalid("approval required".into()))?;
            if a.used || a.request != *c {
                return Err(Error::Conflict);
            }
            a.used = true;
            Ok(())
        }
    }
}

#[derive(Debug, Clone)]
pub struct ExecutionApproval {
    pub request: Call,
    pub content: String,
    pub used: bool,
}

pub fn dispatch(
    root: &std::path::Path,
    request: &Call,
    content: Option<&str>,
    approval: Option<&mut ExecutionApproval>,
) -> Result<String, Error> {
    use std::io::Read;
    let base = root.canonicalize().map_err(|e| Error::Io(e.to_string()))?;
    if decide(request) == Decision::Deny {
        return Err(Error::Invalid("policy denied".into()));
    }
    let target = base
        .join(&request.argument)
        .canonicalize()
        .map_err(|e| Error::Io(e.to_string()))?;
    if !target.starts_with(&base) || !target.is_file() {
        return Err(Error::Invalid("existing contained file required".into()));
    }
    if request.tool == "write" {
        let text = content.ok_or_else(|| Error::Invalid("write content required".into()))?;
        if text.len() > 16384 {
            return Err(Error::Limit);
        }
        let receipt = approval.ok_or_else(|| Error::Invalid("approval required".into()))?;
        if receipt.used || receipt.request != *request || receipt.content != text {
            return Err(Error::Conflict);
        }
        let mut gate = Approval {
            request: receipt.request.clone(),
            used: receipt.used,
        };
        authorize(request, Some(&mut gate))?;
        receipt.used = true;
        std::fs::write(target, text).map_err(|e| Error::Io(e.to_string()))?;
        Ok(format!("wrote {} bytes", text.len()))
    } else {
        authorize(request, None)?;
        if content.is_some() {
            return Err(Error::Invalid("read has no content".into()));
        }
        let mut text = String::new();
        std::fs::File::open(target)
            .map_err(|e| Error::Io(e.to_string()))?
            .take(16385)
            .read_to_string(&mut text)
            .map_err(|e| Error::Io(e.to_string()))?;
        if text.len() > 16384 {
            return Err(Error::Limit);
        }
        Ok(text)
    }
}

use super::*;
pub fn audit(
    log: &mut Vec<String>,
    c: &Call,
    d: &Decision,
    max_entries: usize,
) -> Result<(), Error> {
    if log.len() >= max_entries {
        return Err(Error::Limit);
    }
    let prefix = format!("{}\t", c.id);
    if log.iter().any(|row| row.starts_with(&prefix)) {
        return Err(Error::Conflict);
    }
    log.push(format!("{}\t{}\t{}\t{:?}", c.id, c.role, c.tool, d));
    Ok(())
}

