import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { resolve } from "node:path";
import { runTicket, executePlan, type Tool } from "./main.ts";
const args: Record<string, string> = {};
let approved = false;
for (let i = 2; i < process.argv.length; i++) {
  const key = process.argv[i];
  if (key === "--approved") {
    approved = true;
    continue;
  }
  if (
    !["--ticket", "--checkpoint", "--out"].includes(key) ||
    !process.argv[i + 1]
  )
    throw new Error(
      "Use --ticket FILE --out DIRECTORY, or --checkpoint FILE --approved --out DIRECTORY",
    );
  args[key] = process.argv[++i];
}
if (
  Boolean(args["--ticket"]) === Boolean(args["--checkpoint"]) ||
  !args["--out"]
)
  throw new Error("Choose one --ticket or --checkpoint and provide --out");
const effects: { name: string; query: string }[] = [];
const tool: Tool = async (name, query) => {
  effects.push({ name, query });
  return name === "lookup"
    ? "Local workshop policy: record equipment returns on the desk card."
    : "Local simulation recorded update: " + query;
};
const result = args["--checkpoint"]
  ? await executePlan(
      JSON.parse(readFileSync(args["--checkpoint"], "utf8")),
      tool,
      { approved },
    )
  : await runTicket(JSON.parse(readFileSync(args["--ticket"], "utf8")), tool, {
      approved,
    });
const out = resolve(args["--out"]);
mkdirSync(out, { recursive: true });
const report = {
  method: "Scratch workflow with an injected local simulated tool",
  result,
  effects,
};
writeFileSync(resolve(out, "workflow.json"), JSON.stringify(report, null, 2));
if (result.status === "suspended")
  writeFileSync(
    resolve(out, "checkpoint.json"),
    JSON.stringify(result.checkpoint, null, 2),
  );
const escape = (value: string) =>
  value.replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ]!,
  );
writeFileSync(
  resolve(out, "index.html"),
  '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Workflow review</title><style>body{font:18px system-ui;max-width:850px;margin:3rem auto;padding:0 1rem}pre{white-space:pre-wrap}</style><h1>Workflow review</h1><p>Local simulated tool; no external account changed.</p><h2>' +
    escape(result.status) +
    "</h2><pre>" +
    escape(JSON.stringify(report, null, 2)) +
    "</pre></html>",
);
console.log(
  JSON.stringify(
    { status: result.status, effects, output: resolve(out, "index.html") },
    null,
    2,
  ),
);
if (result.status === "failed") process.exitCode = 1;

import { execFileSync } from "node:child_process";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
const here = dirname(fileURLToPath(import.meta.url));
const directory = mkdtempSync(resolve(tmpdir(), "workflow-demo-"));
try {
  console.log(
    "Local simulated tool: suspend before an update, inspect checkpoint, then explicitly resume.",
  );
  execFileSync(
    process.execPath,
    [
      "--experimental-strip-types",
      resolve(here, "cli.ts"),
      "--ticket",
      resolve(here, "fixtures/ticket.json"),
      "--out",
      resolve(directory, "pending"),
    ],
    { stdio: "inherit" },
  );
  execFileSync(
    process.execPath,
    [
      "--experimental-strip-types",
      resolve(here, "cli.ts"),
      "--checkpoint",
      resolve(directory, "pending/checkpoint.json"),
      "--approved",
      "--out",
      resolve(directory, "resumed"),
    ],
    { stdio: "inherit" },
  );
  console.log(
    "Use cli.ts with your own ticket JSON to keep the HTML report. Use optional-mastra/cli.ts for real SDK persistence.",
  );
} finally {
  rmSync(directory, { recursive: true, force: true });
}

/*
 * Typed Workflow Agent with Mastra reference implementation.
 * Follow stages in projects/typed-workflow-agent-with-mastra/stages/.
 * The demo is deterministic and requires no provider credentials.
 * Protocol references are listed in the project README.
 */
import { pathToFileURL } from "node:url";
import path from "node:path";

export type Ticket = { id: string; message: string };
export type Classification = {
  ticket: Ticket;
  intent: "read" | "write";
  topic: string;
};
export type Action = { tool: "lookup" | "update"; query: string };
export type Plan = {
  ticket: Ticket;
  actions: Action[];
  requiresApproval: boolean;
};
export type Tool = (name: Action["tool"], query: string) => Promise<string>;
export type Trace = { step: string; status: string; attempt: number };
export type Result =
  | {
      status: "complete";
      result: { ticketId: string; answer: string; calls: number };
      trace: Trace[];
    }
  | { status: "suspended"; checkpoint: Plan; trace: Trace[] }
  | { status: "failed"; reason: string; trace: Trace[] };
export function parseTicket(raw: unknown): Ticket {
  if (!raw || typeof raw !== "object") throw new Error("invalid ticket");
  const t = raw as Ticket;
  if (
    typeof t.id !== "string" ||
    !t.id.trim() ||
    typeof t.message !== "string" ||
    !t.message.trim() ||
    t.message.length > 10000
  )
    throw new Error("invalid ticket");
  return { id: t.id.trim(), message: t.message.trim() };
}
export function classify(raw: unknown): Classification {
  const ticket = parseTicket(raw);
  const lower = ticket.message.toLowerCase();
  return {
    ticket,
    intent: /\b(update|delete|change|cancel)\b/.test(lower) ? "write" : "read",
    topic: lower.includes("billing")
      ? "billing"
      : lower.includes("account")
        ? "account"
        : "general",
  };
}
export function makePlan(c: Classification): Plan {
  parseTicket(c.ticket);
  if (!["read", "write"].includes(c.intent)) throw new Error("invalid intent");
  return {
    ticket: c.ticket,
    actions: [
      {
        tool: c.intent === "write" ? "update" : "lookup",
        query: c.ticket.message,
      },
    ],
    requiresApproval: c.intent === "write",
  };
}
export function validatePlan(plan: Plan): Plan {
  parseTicket(plan.ticket);
  if (
    !Array.isArray(plan.actions) ||
    !plan.actions.length ||
    plan.actions.length > 10 ||
    plan.actions.some(
      (a) =>
        !["lookup", "update"].includes(a.tool) ||
        typeof a.query !== "string" ||
        !a.query.trim(),
    )
  )
    throw new Error("invalid plan");
  if (plan.requiresApproval !== plan.actions.some((a) => a.tool === "update"))
    throw new Error("invalid approval contract");
  return plan;
}
export async function executePlan(
  plan: Plan,
  tool: Tool,
  options: { approved?: boolean; maxCalls?: number; maxAttempts?: number } = {},
): Promise<Result> {
  validatePlan(plan);
  const maxCalls = options.maxCalls ?? 3,
    maxAttempts = options.maxAttempts ?? 2;
  if (
    !Number.isInteger(maxCalls) ||
    maxCalls < 1 ||
    maxCalls > 100 ||
    !Number.isInteger(maxAttempts) ||
    maxAttempts < 1 ||
    maxAttempts > 10
  )
    throw new Error("invalid budget");
  const trace: Trace[] = [];
  if (plan.requiresApproval && !options.approved)
    return {
      status: "suspended",
      checkpoint: structuredClone(plan),
      trace: [{ step: "approval", status: "suspended", attempt: 0 }],
    };
  let calls = 0;
  const answers: string[] = [];
  for (const action of plan.actions) {
    let complete = false;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      if (calls >= maxCalls)
        return { status: "failed", reason: "call budget exhausted", trace };
      calls++;
      try {
        const result = await tool(action.tool, action.query);
        if (typeof result !== "string" || !result.trim())
          throw new Error("empty tool result");
        answers.push(result.trim());
        trace.push({ step: action.tool, status: "complete", attempt });
        complete = true;
        break;
      } catch (e) {
        trace.push({ step: action.tool, status: "failed", attempt });
        if (attempt === maxAttempts)
          return { status: "failed", reason: (e as Error).message, trace };
      }
    }
    if (!complete)
      return { status: "failed", reason: "retry exhausted", trace };
  }
  return {
    status: "complete",
    result: { ticketId: plan.ticket.id, answer: answers.join("\n"), calls },
    trace,
  };
}
export async function runTicket(
  raw: unknown,
  tool: Tool,
  options: { approved?: boolean; maxCalls?: number; maxAttempts?: number } = {},
): Promise<Result> {
  return executePlan(makePlan(classify(raw)), tool, options);
}
if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href
) {
  const tool: Tool = async (name, query) =>
    name === "lookup"
      ? "Billing policy: receipts are required."
      : `Recorded change: ${query}`;
  const read = await runTicket(
    { id: "T-1", message: "Find billing policy" },
    tool,
  );
  const paused = await runTicket(
    { id: "T-2", message: "Update billing address" },
    tool,
  );
  const resumed =
    paused.status === "suspended"
      ? await executePlan(paused.checkpoint, tool, { approved: true })
      : paused;
  console.log(JSON.stringify({ read, paused, resumed }, null, 2));
}

import { createStep, createWorkflow } from "@mastra/core/workflows";
import { Mastra } from "@mastra/core/mastra";
import { InMemoryStore, type MastraCompositeStore } from "@mastra/core/storage";
import { createHash } from "node:crypto";
import { z } from "zod";
import {
  classify,
  makePlan,
  executePlan,
  validatePlan,
  type Tool,
  type Plan,
} from "../main.ts";
const ticketSchema = z.object({
  id: z.string().min(1),
  message: z.string().min(1).max(10000),
});
const classificationSchema = z.object({
  ticket: ticketSchema,
  intent: z.enum(["read", "write"]),
  topic: z.string(),
});
const planSchema = z.object({
  ticket: ticketSchema,
  actions: z
    .array(
      z.object({
        tool: z.enum(["lookup", "update"]),
        query: z.string().min(1),
      }),
    )
    .min(1)
    .max(10),
  requiresApproval: z.boolean(),
});
const resultSchema = z.object({
  ticketId: z.string(),
  answer: z.string(),
  calls: z.number(),
});
export function planHash(plan: Plan): string {
  return createHash("sha256")
    .update(JSON.stringify(validatePlan(plan)))
    .digest("hex");
}

export function createTicketWorkflow(
  tool: Tool,
  approved = false,
  storage: MastraCompositeStore = new InMemoryStore(),
) {
  const classifyStep = createStep({
    id: "classify",
    inputSchema: ticketSchema,
    outputSchema: classificationSchema,
    execute: async ({ inputData }) => classify(inputData),
  });
  const planStep = createStep({
    id: "plan",
    inputSchema: classificationSchema,
    outputSchema: planSchema,
    execute: async ({ inputData }) => makePlan(inputData),
  });
  const executeStep = createStep({
    id: "execute",
    inputSchema: planSchema,
    outputSchema: resultSchema,
    suspendSchema: z.object({
      ticketId: z.string(),
      planHash: z.string(),
      plan: planSchema,
      reason: z.string(),
    }),
    resumeSchema: z.object({
      approved: z.boolean(),
      ticketId: z.string(),
      planHash: z.string(),
    }),
    execute: async ({ inputData, resumeData, suspendData, suspend }) => {
      const plan = validatePlan(inputData),
        digest = planHash(plan);
      if (plan.requiresApproval && !approved) {
        if (
          suspendData &&
          (suspendData.planHash !== digest ||
            suspendData.ticketId !== plan.ticket.id)
        )
          throw new Error("Stored approval context changed");
        if (!resumeData?.approved)
          return suspend({
            ticketId: plan.ticket.id,
            planHash: digest,
            plan: structuredClone(plan),
            reason: "Explicit approval required before update",
          });
        if (
          resumeData.ticketId !== plan.ticket.id ||
          resumeData.planHash !== digest
        )
          throw new Error("Approval does not match the suspended plan");
      }
      const result = await executePlan(plan, tool, {
        approved: approved || resumeData?.approved === true,
        maxCalls: 3,
        maxAttempts: 2,
      });
      if (result.status !== "complete")
        throw new Error(
          result.status === "failed"
            ? result.reason
            : "Unexpected scratch suspension",
        );
      return result.result;
    },
  });
  const workflow = createWorkflow({
    id: "ticket-triage",
    inputSchema: ticketSchema,
    outputSchema: resultSchema,
  })
    .then(classifyStep)
    .then(planStep)
    .then(executeStep)
    .commit();
  const mastra = new Mastra({
    workflows: { "ticket-triage": workflow },
    storage,
    logger: false,
  });
  return mastra.getWorkflow("ticket-triage");
}

export async function persistentWorkflow(tool: Tool, url: string) {
  if (!url.startsWith("file:"))
    throw new Error("Use an explicit local file: database URL");
  const { LibSQLStore } = await import("@mastra/libsql");
  const storage = new LibSQLStore({ id: "ticket-approval-store", url });
  return { workflow: createTicketWorkflow(tool, false, storage), storage };
}

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { resolve } from "node:path";
import { persistentWorkflow } from "./adapter.ts";
const args: Record<string, string> = {};
for (let i = 2; i < process.argv.length; i += 2) {
  if (
    !["--ticket", "--db", "--out", "--resume", "--approval"].includes(
      process.argv[i],
    ) ||
    !process.argv[i + 1]
  )
    throw new Error(
      "Use --ticket FILE --db FILE --out DIRECTORY, or --resume RUN_ID --approval FILE --db FILE --out DIRECTORY",
    );
  args[process.argv[i]] = process.argv[i + 1];
}
if (!args["--db"] || !args["--out"])
  throw new Error("--db and --out are required");
const out = resolve(args["--out"]);
mkdirSync(out, { recursive: true });
const effects: unknown[] = [];
const tool = async (name: string, query: string) => {
  effects.push({ name, query });
  return name === "lookup"
    ? "Workshop policy: label borrowed tools with the checkout date."
    : "Local simulation recorded the requested update: " + query;
};
const { workflow, storage } = await persistentWorkflow(
  tool,
  "file:" + resolve(args["--db"]),
);
try {
  const run = await workflow.createRun(
    args["--resume"] ? { runId: args["--resume"] } : {},
  );
  let result;
  if (args["--resume"]) {
    if (!args["--approval"])
      throw new Error("--resume requires a reviewed --approval JSON file");
    result = await run.resume({
      step: "execute",
      resumeData: JSON.parse(readFileSync(args["--approval"], "utf8")),
    });
  } else {
    if (!args["--ticket"]) throw new Error("Start requires --ticket JSON");
    result = await run.start({
      inputData: JSON.parse(readFileSync(args["--ticket"], "utf8")),
    });
  }
  writeFileSync(
    resolve(out, "workflow.json"),
    JSON.stringify(
      {
        runId: run.runId,
        status: result.status,
        result,
        effects,
        method: "Real persistent Mastra workflow with a local simulated tool",
      },
      null,
      2,
    ),
  );
  if (result.status === "suspended") {
    const p = result.steps.execute.suspendPayload;
    writeFileSync(
      resolve(out, "approval.json"),
      JSON.stringify(
        { approved: false, ticketId: p.ticketId, planHash: p.planHash },
        null,
        2,
      ),
    );
  }
  console.log(
    JSON.stringify(
      {
        runId: run.runId,
        status: result.status,
        effects,
        output: resolve(out, "workflow.json"),
        approval:
          result.status === "suspended"
            ? "Inspect workflow.json, then edit approval.json explicitly and resume."
            : null,
      },
      null,
      2,
    ),
  );
  if (result.status === "failed") process.exitCode = 1;
} finally {
  await storage.close();
}

