/*
 * Self-Correcting Workflow Hooks reference implementation.
 * Follow stages in projects/workflow-hooks/stages/.
 * The demo is deterministic and requires no provider credentials.
 * Protocol references are listed in the project README.
 */
import { pathToFileURL } from "node:url";
import path from "node:path";

import { promises as fs } from "node:fs";
export type Correction = {
  id: string;
  session: string;
  scope: string;
  rule: string;
  source: string;
  locator?: string;
};
export type Rule = {
  key: string;
  scope: string;
  text: string;
  sourceIds: string[];
  sessions: string[];
  evidence?: { id: string; session: string; source: string; locator: string }[];
  state: "candidate" | "approved" | "retired";
};
export function normalize(text: string): string {
  return text.trim().toLowerCase().replace(/\s+/g, " ");
}
export function ingest(raw: unknown): Correction {
  if (!raw || typeof raw !== "object") throw new Error("invalid correction");
  const c = raw as Correction;
  for (const k of ["id", "session", "scope", "rule", "source"] as const)
    if (typeof c[k] !== "string" || !c[k].trim())
      throw new Error(`missing ${k}`);
  if (c.rule.length > 500 || c.source.length > 2000)
    throw new Error("too large");
  if (/(?:sk-|ghp_)[a-z0-9]{12,}/i.test(c.rule + " " + c.source))
    throw new Error("credential-like content");
  return {
    ...c,
    rule: c.rule.trim().replace(/\s+/g, " "),
    scope: normalize(c.scope),
  };
}
export function consolidate(corrections: Correction[]): Rule[] {
  const groups = new Map<string, Rule>();
  const ids = new Map<string, string>();
  for (const raw of corrections) {
    const c = ingest(raw);
    const signature = JSON.stringify(c);
    if (ids.has(c.id)) {
      if (ids.get(c.id) !== signature)
        throw new Error("conflicting correction id");
      continue;
    }
    ids.set(c.id, signature);
    const key = JSON.stringify([c.scope, c.rule]);
    let r = groups.get(key);
    if (!r) {
      r = {
        key,
        scope: c.scope,
        text: c.rule,
        sourceIds: [],
        sessions: [],
        evidence: [],
        state: "candidate",
      };
      groups.set(key, r);
    }
    r.sourceIds.push(c.id);
    r.evidence!.push({
      id: c.id,
      session: c.session,
      source: c.source,
      locator: c.locator ?? `session:${c.session}#${c.id}`,
    });
    if (!r.sessions.includes(c.session)) r.sessions.push(c.session);
  }
  return [...groups.values()].sort((a, b) => a.key.localeCompare(b.key));
}
export function transition(
  rule: Rule,
  event: "approve" | "retire",
  minimumSessions = 2,
): Rule {
  if (event === "retire") return { ...rule, state: "retired" };
  if (rule.state === "retired")
    throw new Error("retired rule cannot be approved");
  if (rule.sessions.length < minimumSessions)
    throw new Error("insufficient independent sessions");
  return { ...rule, state: "approved" };
}
export function hook(
  rules: Rule[],
  scope: string,
): {
  rules: string[];
  sources: string[];
  evidence: NonNullable<Rule["evidence"]>;
} {
  const selected = rules.filter(
    (r) =>
      r.state === "approved" &&
      (r.scope === "global" || r.scope === normalize(scope)),
  );
  return {
    rules: selected.map((r) => r.text),
    evidence: selected.flatMap((r) => r.evidence ?? []),
    sources: [...new Set(selected.flatMap((r) => r.sourceIds))],
  };
}
export async function save(file: string, rules: Rule[]): Promise<void> {
  await fs.mkdir(path.dirname(file), { recursive: true });
  const temp = file + "." + process.pid + "." + crypto.randomUUID() + ".tmp";
  try {
    await fs.writeFile(temp, JSON.stringify({ version: 1, rules }, null, 2), {
      flag: "wx",
      mode: 0o600,
    });
    await fs.rename(temp, file);
  } finally {
    await fs.rm(temp, { force: true });
  }
}
export async function load(file: string): Promise<Rule[]> {
  try {
    const data = JSON.parse(await fs.readFile(file, "utf8"));
    if (data.version !== 1 || !Array.isArray(data.rules))
      throw new Error("invalid store");
    for (const r of data.rules)
      if (
        !["candidate", "approved", "retired"].includes(r.state) ||
        !Array.isArray(r.sourceIds) ||
        !Array.isArray(r.sessions) ||
        typeof r.text !== "string" ||
        typeof r.scope !== "string"
      )
        throw new Error("invalid rule");
    return data.rules;
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw e;
  }
}
if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href
) {
  const c = [
    {
      id: "c1",
      session: "s1",
      scope: "project",
      rule: "Run tests before changing snapshots",
      source: "Correction in session one",
    },
    {
      id: "c2",
      session: "s2",
      scope: "project",
      rule: "Run tests before changing snapshots",
      source: "Repeated in session two",
    },
  ];
  const rules = consolidate(c).map((r) => transition(r, "approve"));
  await save("rules.json", rules);
  console.log(
    JSON.stringify(
      { stored: "rules.json", ...hook(await load("rules.json"), "project") },
      null,
      2,
    ),
  );
}

import math, csv, io, copy
from decimal import Decimal, InvalidOperation


def _number(value):
    try:
        n = Decimal(str(value))
    except InvalidOperation:
        raise ValueError("quantity must be numeric") from None
    if not n.is_finite() or n < 0:
        raise ValueError("quantity must be finite and nonnegative")
    return n


def _factor(source, target, conversions):
    graph = {}
    for c in conversions:
        factor = _number(c["factor"])
        if not factor:
            raise ValueError("conversion factor must be positive")
        graph.setdefault(c["from"], []).append((c["to"], factor))
        graph.setdefault(c["to"], []).append((c["from"], 1 / factor))
    known = {source: Decimal(1)}
    queue = [source]
    for unit in queue:
        for other, factor in graph.get(unit, []):
            value = known[unit] * factor
            if other in known:
                if abs(known[other] - value) > Decimal("0.000000001"):
                    raise ValueError("inconsistent conversion cycle")
            else:
                known[other] = value
                queue.append(other)
    return known.get(target)


def validate(document):
    """Return a deep-copied model. participants is a nonnegative integer; materials have unique id,name,kind,quantity,unit and shared materials need positive integer share. Inventory IDs must exist. Explicit positive conversion factors map from->to. Reject inconsistent conversion cycles."""
    d = copy.deepcopy(document)
    n = d.get("participants")
    if type(n) is not int or n < 0:
        raise ValueError("participants must be a nonnegative integer")
    seen = set()
    for m in d["materials"]:
        if (
            not all(
                (isinstance(m.get(k), str) and m[k] for k in ("id", "name", "unit"))
            )
            or m["id"] in seen
            or m.get("kind") not in ("consumable", "shared")
        ):
            raise ValueError("invalid material")
        seen.add(m["id"])
        _number(m["quantity"])
        if m["kind"] == "shared" and (
            type(m.get("share")) is not int or m["share"] <= 0
        ):
            raise ValueError("sharing group must be positive")
    for r in d.get("inventory", []):
        if (
            r.get("id") not in seen
            or not isinstance(r.get("unit"), str)
            or (not r["unit"])
        ):
            raise ValueError("invalid inventory item")
        _number(r["quantity"])
    conversions = d.get("conversions", [])
    for c in conversions:
        if not all((isinstance(c.get(k), str) and c[k] for k in ("from", "to"))):
            raise ValueError("invalid conversion unit")
        _factor(c["from"], c["to"], conversions)
    return d


def scale(model, participants=None):
    """Return [{id,name,kind,unit,groups,required}] using quantity*participants for consumables and quantity*ceil(participants/share) for reusable shared equipment. required is a decimal string; zero participants requires zero of both kinds."""
    n = model["participants"] if participants is None else participants
    if type(n) is not int or n < 0:
        raise ValueError("participants must be nonnegative integer")
    rows = []
    for m in model["materials"]:
        groups = n if m["kind"] == "consumable" else math.ceil(n / m["share"])
        rows.append(
            {k: m[k] for k in ("id", "name", "kind", "unit")}
            | {"groups": groups, "required": str(_number(m["quantity"]) * groups)}
        )
    return rows


def shortages(model, participants=None):
    """Return scaled rows plus available,shortage (decimal strings or None) and unresolved inventory entries. Sum compatible inventory through explicit reciprocal conversion paths. Any unconvertible inventory for an item leaves availability and shortage unknown; never silently infer density or package size."""
    rows = scale(model, participants)
    for r in rows:
        total = Decimal(0)
        unresolved = []
        for item in model.get("inventory", []):
            if item["id"] != r["id"]:
                continue
            factor = _factor(item["unit"], r["unit"], model.get("conversions", []))
            if factor is None:
                unresolved.append(item)
            else:
                total += _number(item["quantity"]) * factor
        r.update(
            available=None if unresolved else str(total),
            shortage=None
            if unresolved
            else str(max(Decimal(0), _number(r["required"]) - total)),
            unresolved=unresolved,
        )
    return rows


def export_plan(model, counts):
    """Return schema_version=1 {participants,packing,scenarios,csv,uncertain_items}. counts is a unique list of nonnegative integers for comparison. CSV contains id,name,required,available,shortage,unit,status; unknown quantities are blank with status=review."""
    if len(set(counts)) != len(counts):
        raise ValueError("duplicate scenario count")
    packing = shortages(model)
    scenarios = [{"participants": n, "packing": shortages(model, n)} for n in counts]
    buf = io.StringIO(newline="")
    keys = ["id", "name", "required", "available", "shortage", "unit", "status"]
    w = csv.DictWriter(buf, fieldnames=keys)
    w.writeheader()
    for row in packing:
        w.writerow(
            {k: row[k] for k in keys if k != "status"}
            | {"status": "review" if row["unresolved"] else "known"}
        )
    return {
        "schema_version": 1,
        "participants": model["participants"],
        "packing": packing,
        "scenarios": scenarios,
        "csv": buf.getvalue(),
        "uncertain_items": [r["id"] for r in packing if r["unresolved"]],
    }

{
  "participants": 8,
  "materials": [
    {
      "id": "paper",
      "name": "Colored paper",
      "kind": "consumable",
      "quantity": 2,
      "unit": "sheet"
    },
    {
      "id": "scissors",
      "name": "Scissors",
      "kind": "shared",
      "quantity": 1,
      "unit": "pair",
      "share": 3
    },
    {
      "id": "glue",
      "name": "Glue",
      "kind": "consumable",
      "quantity": 10,
      "unit": "ml"
    }
  ],
  "inventory": [
    {
      "id": "paper",
      "quantity": 20,
      "unit": "sheet"
    },
    {
      "id": "scissors",
      "quantity": 3,
      "unit": "pair"
    },
    {
